window.PLUS = {"1653":{"k":["모델링 3대 특징: **추상화 · 단순화 · 명확화**(정확화)","모델링은 DB 구축의 사전 작업이면서 **업무를 분석·설명하는 도구**이기도 함"],"w":["추상화는 3대 특징 중 하나. 현실의 공통 성질만 뽑아 일정한 형식으로 표현한다는 설명 그대로라 맞는 보기","","단순화도 3대 특징. 복잡한 현실을 제한된 표기법으로 쉽게 표현한다는 정의와 일치","명확화(정확화)도 3대 특징. 모호함 없이 누구나 같은 뜻으로 읽게 한다는 설명이 정확함"],"t":"보기에 '~만을 위해', '~뿐이다', '반드시 ~만' 같은 한정 표현이 보이면 일단 의심하세요. 모델링 문제의 오답은 대부분 범위를 좁혀 놓은 문장입니다."},"1654":{"k":["데이터 모델은 DB 설계도이면서 **업무 자체를 설명하고 분석하는 수단**","업무 설명용 표기법이 따로 있는 게 아니라 모델이 그 역할을 함"],"w":["업무 정보의 기초가 되는 정보를 약속된 표기법으로 표현하는 것이 모델링의 정의 그대로라 맞음","모델로 DB를 만들고 개발·데이터 관리에 쓰는 것도 모델링의 목적이라 맞음","","모델 자체가 업무 흐름을 설명·분석하는 의미를 가진다는 건 모델링의 중요한 역할이라 맞음"],"t":"'업무 설명은 별도의 ~를 이용한다'처럼 모델의 역할을 다른 것에 떠넘기는 문장은 오답 패턴입니다."},"1655":{"k":["모델링 유의사항 3가지: **중복 · 비유연성 · 비일관성**","대응: 중복 최소화 / 데이터 정의와 프로세스 **분리** / 연관관계 명확히 정의"],"w":["같은 정보를 여러 곳에 저장하지 않게 하는 것은 '중복' 유의사항의 올바른 대응이라 맞음","데이터 정의를 사용 프로세스와 분리해야 업무가 바뀌어도 모델이 흔들리지 않음. '비유연성' 대응책이라 맞음","","데이터 간 연관관계를 명확히 정의하면 일부만 고쳐 생기는 모순을 막음. '비일관성' 대응책이라 맞음"],"t":"유의사항 문제는 '프로그램(프로세스)과 데이터를 떼어 놓는다'가 정답 방향입니다. 연계성을 '높인다', 프로세스에 '맞춘다'는 말이 나오면 거의 오답."},"1656":{"k":["**비유연성**: 업무가 조금만 바뀌어도 모델을 자주 고쳐야 하는 문제","해결책은 데이터 정의를 사용 프로세스와 분리하는 것"],"w":["중복은 같은 정보를 여러 장소에 저장해서 생기는 문제. 지문은 변경에 약한 구조를 말하므로 다름","","비일관성은 중복이 없어도 연관 데이터를 고려하지 않고 일부만 바꿔 서로 모순이 생기는 문제","일관성은 지켜야 할 목표이지 유의사항(피해야 할 것) 이름이 아님"],"t":"지문에 '사소한 업무 변화', '수시로 변경', '유지보수'가 보이면 비유연성, '모순', '상호 연관'이 보이면 비일관성, '여러 장소에 같은 정보'면 중복입니다."},"1657":{"k":["외부 스키마 = **사용자 관점(View)**, 여러 개","개념 스키마 = 모든 관점을 **통합**한 조직 전체 구조, 하나","내부 스키마 = 물리 저장 구조"],"w":["통합된 전체 사용자 관점은 개념 스키마의 정의라 맞음","물리적 저장 구조를 표현하는 건 내부 스키마라 맞음","","논리적 독립성은 외부-개념 사이의 사상으로 보장되므로 맞음"],"t":"'View', '사용자별', '여러 개'는 외부 스키마, '통합', '조직 전체', '하나'는 개념 스키마로 키워드를 짝지어 외우세요."},"1658":{"k":["**개념 스키마**: 모든 사용자 관점을 통합한 조직 전체 DB 구조","DB에 저장되는 데이터와 그 관계, 제약조건을 표현"],"w":["외부 스키마는 각 사용자·응용 프로그램이 보는 일부 관점(서브스키마)이라 '통합'과 반대","","내부 스키마는 레코드 형식·인덱스 같은 물리 저장 구조","'논리 스키마'는 3단계 구조(외부·개념·내부)의 공식 이름이 아님"],"t":"3단계 스키마 보기에 '논리', '물리'라는 이름이 붙어 있으면 함정입니다. 공식 이름은 외부·개념·내부 세 개뿐."},"1659":{"k":["IE 표기에서 엔터티에 **붙은 기호 = 최대**, 먼 기호 = 최소","고객 쪽 `│` → 주문은 고객이 **반드시** 1명, 주문 쪽 `○<` → 고객은 주문이 0건 이상"],"w":["주문 쪽 끝이 까마귀발(여러 개)이라 한 고객이 여러 주문을 낼 수 있음. 맞는 설명","고객 쪽 끝이 필수(│)라 주문에는 반드시 고객이 있어야 함. 맞는 설명","주문 쪽에 ○(선택)가 있어 주문이 없는 고객도 가능. 맞는 설명",""],"t":"관계를 읽을 때는 '읽고 싶은 문장의 목적어 쪽' 끝 기호를 봅니다. '주문은 고객이 있어야 하나?'를 보려면 고객 쪽 끝을 보세요."},"1660":{"k":["ERD는 1976년 **피터 첸**이 제안","작성 순서: 엔터티 도출 → 배치 → 관계 설정 → 관계명 → 관계차수 → 선택사양","가장 중요한 엔터티는 **왼쪽 상단**"],"w":["피터 첸이 1976년 E-R 모델을 만들었다는 건 사실이라 맞음","도출 → 배치 → 관계 설정 → 관계명 순서가 맞음","관계명은 관계를 정확히 읽게 해 주는 핵심 요소라 맞음",""],"t":"배치 문제는 '사람이 글 읽는 방향(왼→오, 위→아래)'만 기억하면 됩니다. 중요한 건 시선이 처음 닿는 왼쪽 위."},"1661":{"k":["엔터티 조건: 업무에 필요, **인스턴스 2개 이상**, **속성 2개 이상**, 관계 1개 이상","속성(이름·주소)은 엔터티가 아니라 엔터티를 설명하는 항목"],"w":["S병원은 하나뿐이라 인스턴스가 1개. 인스턴스가 하나면 엔터티가 될 수 없음","","이름은 환자 한 명 한 명을 설명하는 속성","주소도 환자를 설명하는 속성. 따로 관리할 대상이 아님"],"t":"시나리오형은 '여러 개 있고(인스턴스), 각자 여러 정보(속성)를 가진 명사'를 찾으면 됩니다. '하나뿐인 회사·병원'은 늘 함정."},"1662":{"k":["엔터티는 영속적으로 존재하는 **인스턴스 2개 이상의 집합**","속성 필수, 관계 필수(통계·코드성은 예외), 업무에 필요해야 함"],"w":["속성이 없는 엔터티는 없음. 반드시 속성을 가져야 한다는 건 엔터티 특징 그대로","관계는 1개 이상 있어야 하고, 통계성·코드성 엔터티만 관계를 생략할 수 있다는 예외까지 정확함","","데이터로 있어도 업무에서 쓰지 않으면 엔터티가 아님. 맞는 설명"],"t":"'싱글턴', '하나의 인스턴스로 충분'이 나오면 바로 오답입니다. 엔터티는 집합이라 최소 두 개."},"1663":{"k":["엔터티 특징 6가지: 업무 필요 · 유일 식별자 · 인스턴스 2개↑ · 업무 프로세스가 이용 · 속성 포함 · **관계 1개 이상**"],"w":["","유일한 식별자로 인스턴스를 구분할 수 있어야 함. 엔터티 특징 맞음","생성·조회·수정·삭제 등 업무 프로세스가 이용해야 함. 맞음","속성이 없으면 엔터티가 아님. 반드시 포함해야 한다는 설명 맞음"],"t":"'관계를 가지지 않는다'는 원칙 자체를 부정하는 문장입니다. 예외(코드·통계)가 있다는 것과 원칙이 없다는 건 다릅니다."},"1664":{"k":["발생 시점 분류: **기본(키) · 중심(메인) · 행위**","유무형 분류: 유형 · 개념 · 사건"],"w":["","행위 엔터티는 두 개 이상 부모에서 발생하는 이력·내역. 발생 시점 분류에 포함","중심 엔터티는 기본 엔터티에서 발생한 업무 중심 거래. 포함","기본 엔터티는 독립적으로 생성되는 엔터티. 포함"],"t":"발생 시점은 '기중행', 유무형은 '유개사'로 외우세요. '관계 엔터티', '교차 엔터티'는 두 분류 어디에도 없습니다."},"1665":{"k":["엔터티 이름: 현업 용어 · **약어 지양** · 단수 명사 · 전체에서 유일 · 생성 의미대로"],"w":["","현업 용어를 써야 업무 담당자와 소통이 됨. 맞는 원칙","같은 이름이 둘이면 혼란이 생기므로 유일해야 함. 맞는 원칙","고객이 주문한 것은 '주문'처럼 생성 의미대로 짓는 게 원칙. 맞음"],"t":"이름 짓기 문제에서 '약어'는 엔터티든 속성이든 늘 '가급적 쓰지 않는다'가 정답입니다."},"1666":{"k":["**속성**: 업무에 필요한, 의미상 더 이상 분리되지 않는 **최소 데이터 단위**"],"w":["도메인은 속성이 가질 수 있는 값의 범위(타입·크기·제약)","","엔터티는 속성들을 가진 인스턴스의 집합. 최소 단위가 아님","관계는 엔터티와 엔터티 사이의 연관"],"t":"'최소 단위', '더 이상 분리되지 않는'이 나오면 속성, '값의 범위'가 나오면 도메인입니다."},"1667":{"k":["한 인스턴스에서 한 속성은 **값 하나만** 가짐","값이 여러 개면 별도 엔터티로 분리 (1차 정규화 원리)"],"w":["속성은 엔터티를 자세하고 구체적으로 설명하는 정보라 맞음","엔터티는 속성 두 개 이상을 가지는 게 원칙이라 맞음","","같은 성격의 값들이 모인 것이라 속성도 집합으로 볼 수 있음. 맞음"],"t":"속성 문제에서 '하나 이상의 값', '여러 값'이 나오면 1정규형 위배 = 오답으로 바로 연결하세요."},"1668":{"k":["**2차 정규화** = 부분 함수 종속 제거 (PK 일부에만 종속된 속성을 떼어냄)","복합 PK(주문번호, 상품코드)에서 상품명·가격은 상품코드에만 종속"],"w":["1차 정규화는 반복 속성·다중값을 없애 원자값으로 만드는 것","","3차 정규화는 일반 속성끼리의 이행 종속 제거","4차 정규화는 다치 종속 제거"],"t":"정규화 전후 그림이 나오면 '떼어 나간 속성이 무엇에 종속됐는지'만 보세요. PK 일부 → 2차, 일반 속성 → 3차."},"1669":{"k":["속성 특성 분류: **기본**(업무에서 바로) · **설계**(설계하며 만든 코드·일련번호) · **파생**(계산된 값)","파생 속성은 조회 성능을 위해 저장하지만 정합성 관리 부담 → 최소화"],"w":["","기본 속성은 업무 분석에서 바로 나온 원래 속성(단가, 이름)","설계 속성은 업무에 없던 걸 설계 중 만든 속성(상태코드, 일련번호)","PK 속성은 구성 방식 분류(PK·FK·일반)에 속하는 이름이라 특성 분류와 다름"],"t":"'계산', '빠른 조회를 위해 저장'은 파생 속성, '코드', '일련번호'는 설계 속성입니다."},"1670":{"k":["**도메인**: 속성이 가질 수 있는 값의 범위","데이터 타입 · 크기(길이) · 제약사항(범위, 허용 값)"],"w":["시스템 카탈로그는 DBMS가 테이블·컬럼 정보 같은 메타데이터를 보관하는 곳","용어 사전은 표준 용어와 뜻을 정리한 사전","속성 사전은 속성 목록과 설명을 정리한 문서. 값의 범위 정의를 가리키는 용어는 아님",""],"t":"'~사이의 값', '~자리 이내 문자열'처럼 범위와 형식을 정하는 문장은 도메인입니다."},"1671":{"k":["속성명: 현업 용어 · 서술식 금지 · 약어 지양 · **전체 모델에서 유일**"],"w":["약어를 남발하면 뜻이 모호해져 소통이 어려워짐. 가급적 제한한다는 원칙이 맞음","'처음 가입한 날짜' 같은 서술식 이름 대신 '가입일자'처럼 써야 함. 맞음","","용어가 겹칠 때 해당 업무에서 자주 쓰는 이름을 고른다는 건 맞는 방법"],"t":"'이름', '주소'처럼 여러 엔터티에 같은 속성명을 쓰는 건 일관성처럼 보여도 오답입니다. 직원명·고객명처럼 유일하게."},"1672":{"k":["UML **연관관계** = 실선 · 존재적 · 소스코드에서 **멤버변수**로 선언","UML **의존관계** = 점선 · 행위적 · 오퍼레이션 **파라미터**로 사용","ERD는 존재·행위 관계를 구분하지 않음"],"w":["ERD는 두 관계를 같은 선으로 그려 구분하지 않는다는 설명 맞음","UML에서 연관은 실선, 의존은 점선으로 다르게 표현. 맞음","연관은 늘 쓰는 존재적 관계, 의존은 행위에 따른 관계. 맞음",""],"t":"'연관 = 멤버변수(늘 들고 있음)', '의존 = 파라미터(필요할 때 받음)'로 외우면 바뀐 보기를 바로 잡습니다."},"1673":{"k":["관계 표기 3요소: **관계명 · 관계차수 · 관계선택사양**(관차선)","관계 분류: 존재적(부서-사원 소속) / 행위적(주문-배송)"],"w":["관계는 존재에 의한 관계와 행위에 의한 관계로 나뉨. 맞는 설명","","사원이 부서에 '소속'되는 건 존재 자체로 맺어지는 관계라 존재적 관계의 대표 예","배송은 주문이라는 행위가 있어야 생기므로 행위에 의한 관계. 맞음"],"t":"'식별성', '관계 인덱스', '관계 유형' 같은 말이 3요소 자리에 끼어 있으면 오답입니다. 3요소는 '관차선'."},"1674":{"k":["**물리적 독립성**: 내부 스키마(파일·색인 구조)가 바뀌어도 개념·외부 스키마와 응용 프로그램에 영향 없음","**논리적 독립성**: 개념 스키마가 바뀌어도 외부 스키마에 영향 없음"],"w":["논리적 독립성은 개념 스키마(논리 구조) 변경으로부터 외부 스키마를 보호하는 것. 지문은 파일·색인 같은 물리 구조 변경 이야기","","'개념적 독립성'은 존재하지 않는 용어","'내부적 독립성'도 없는 용어. 독립성은 논리적·물리적 두 가지뿐"],"t":"'파일 구조', '색인(인덱스)', '저장 장치'가 바뀌는 이야기면 물리적, '테이블 구조', '컬럼 추가'가 바뀌는 이야기면 논리적 독립성입니다."},"1675":{"k":["**관계차수(Cardinality)**: 한 인스턴스가 상대 인스턴스 몇 개와 연결되나 (1:1, 1:M, M:N)","선택사양(Optionality): 필수냐 선택이냐"],"w":["관계명은 관계에 붙이는 이름(소속된다, 주문한다)","","관계선택사양은 관계가 반드시 있어야 하는지(필수) 없어도 되는지(선택)를 나타냄","'관계정의'는 관계 표기 구성요소가 아님"],"t":"'몇 개', '참여자의 수', '1:M'이 나오면 차수, '반드시', '없을 수도'가 나오면 선택사양입니다."},"1676":{"k":["관계 확인 4가지: 연관규칙 · 정보의 조합 · 규칙 서술 · 관계를 이어 주는 **동사(Verb)**","엔터티는 명사에서, 관계는 동사에서 찾음"],"w":["두 엔터티 사이에 관심 있는 연관규칙이 있는지 확인하는 건 맞는 항목","두 엔터티 정보가 조합되어 쓰이는지 확인하는 것도 맞는 항목","","업무기술서·장표에 관계연결 규칙이 서술됐는지 보는 것도 맞는 항목"],"t":"명사 → 엔터티(또는 속성), 동사 → 관계. 이 짝만 기억하면 '명사(Noun)'로 바꿔 놓은 함정을 바로 잡습니다."},"1677":{"k":["관계 도출 확인 사항 **4가지 전부**: 연관규칙 · 정보 조합 · 규칙 서술 · 동사"],"w":["(라) 관계를 이어 주는 동사가 있는지도 확인 항목이라 빠지면 안 됨","(다) 업무기술서에 관계 규칙이 서술됐는지도 확인 항목","(나) 두 엔터티 사이 정보의 조합 발생 여부도 확인 항목",""],"t":"'모두 고르시오'에서 네 항목이 전부 표준 문구 그대로면 전부 맞는 경우가 많습니다. 하나만 이상한 단어가 섞였는지부터 찾아보세요."},"1678":{"k":["주식별자 4특징: **유일성 · 최소성 · 불변성 · 존재성**","(가) 유일성 (나) 최소성 (다) 불변성 (라) 존재성"],"w":["(라) 존재성(값이 반드시 있어야 함)도 고려해야 함","(가) 유일성이 빠짐. 가장 기본이 되는 특징","(가) 유일성이 빠짐",""],"t":"주식별자 4특징은 '유최불존'. 보기 네 개가 각각 하나씩 설명하고 있으면 답은 '모두'입니다."},"1679":{"k":["식별자 분류 4축: 대표성(주/보조) · 생성(내부/외부) · 속성 수(단일/복합) · 대체 여부(**본질/인조**)","사번은 업무에서 원래 쓰는 값 → 본질식별자"],"w":["사번은 사원을 대표하는 식별자라 주식별자 맞음","속성 하나(사번)로 식별하므로 단일식별자 맞음","다른 엔터티에서 받아온 게 아니라 사원 안에서 생긴 값이라 내부식별자 맞음",""],"t":"인조식별자는 '업무에 없던 일련번호를 일부러 만든 것'입니다. 사번·주문번호처럼 업무에서 실제로 쓰는 번호는 본질식별자로 봅니다."},"1680":{"k":["주식별자는 **유일성**을 보장해야 함","이름·명칭·내역처럼 중복될 수 있는 값은 주식별자로 부적절"],"w":["사원번호는 사원마다 하나씩 부여돼 유일하므로 식별자로 적절","","주민번호도 사람마다 유일해 식별자로 쓸 수 있음","업무에 없던 일련번호(인조식별자)도 유일성만 지키면 식별자로 쓸 수 있음"],"t":"식별자 보기에 '이름', '명', '내역'이 들어가 있으면 동명이인부터 떠올리세요."},"1681":{"k":["**존재성**: 주식별자가 지정되면 반드시 값이 있어야 함 (NULL 불가)","유일성 · 최소성 · 불변성 · 존재성"],"w":["모든 인스턴스를 유일하게 구분한다는 유일성 설명이 정확함","","한번 정한 식별자 값은 바뀌지 않아야 한다는 불변성 설명이 정확함","유일성을 만족하는 최소 속성 수라는 최소성 설명이 정확함"],"t":"PK와 NULL이 같은 문장에 나오면 거의 항상 오답입니다. PK = NOT NULL + UNIQUE."},"1682":{"k":["**식별 관계**는 부모 PK가 자식 PK까지 내려가서 조인을 줄일 수 있음","**비식별 관계**를 쓰는 경우: 부모 없이 자식 생성 / 부모가 먼저 소멸 / 자식에 독립 PK가 유리"],"w":["부모 없이 자식이 먼저 생길 수 있으면 자식 PK에 부모 PK를 넣을 수 없으므로 비식별 관계가 맞음","부모가 먼저 지워져도 자식이 남아야 하면 비식별 관계로 연결해야 함. 맞음","","상속받은 PK가 길어지는 것보다 독립 PK가 유리하면 비식별 관계. 맞음"],"t":"'조인을 줄인다', 'SQL을 단순하게(조인 경로 단축)'는 식별 관계의 장점입니다. 비식별 이유로 나오면 오답."},"1683":{"k":["대표성: **주식별자**(대표) / **보조식별자**(유일하지만 대표 X)","대체 여부: **본질식별자**(업무 의미) / 인조식별자(만든 번호)","생성: 내부식별자 / **외부식별자**(다른 엔터티에서 상속)"],"w":["(가)는 대표성이 있으니 보조가 아니라 주식별자. (나)도 '실질식별자'라는 분류는 없음","(가)는 주식별자, (나)는 보조식별자여야 함. 자리를 바꿔 놓음","","(다) '업무적으로 의미가 부여된' 식별자는 인조가 아니라 본질식별자"],"t":"짝짓기 문제는 확실한 것 하나로 보기를 지워 나가세요. '다른 엔터티로부터 상속' = 외부식별자만 알아도 ①②가 바로 빠집니다."},"1684":{"k":["**도메인** = 속성이 가질 수 있는 값의 범위","데이터 타입 · 크기 · 제약사항이 모두 도메인 안에 들어감"],"w":["제약사항은 도메인을 정할 때 지정하는 요소 중 하나일 뿐, 범위 전체를 부르는 이름이 아님","","데이터 타입도 도메인의 구성요소 중 하나","데이터 크기도 도메인의 구성요소 중 하나"],"t":"타입·크기·제약은 '부분', 도메인은 그걸 다 합친 '전체'입니다. 부분과 전체를 묻는 문제로 보면 쉽습니다."},"1685":{"k":["특성 분류: **기본**(업무 분석에서 바로) · **설계**(설계하며 만듦) · **파생**(계산·변형)","구성 분류: PK · FK · **일반** 속성 → 분류 기준이 다름"],"w":["","㉡ 설계하며 만든 속성은 설계 속성, ㉢ 계산으로 만든 속성은 파생 속성. 일반 속성은 다른 분류","㉠은 기본 속성. 일반 속성은 PK·FK가 아닌 속성을 가리키는 구성 분류 용어","㉠ 자리에 일반 속성은 맞지 않음. 업무분석으로 바로 정의한 건 기본 속성"],"t":"'일반 속성'은 PK·FK와 짝을 이루는 말입니다. 기본·설계·파생 문제에 섞여 나오면 거의 함정."},"1686":{"k":["**후보키**: 모든 속성을 결정하면서(유일성) 군더더기가 없는(최소성) 속성 집합","함수 종속을 따라가며 결정되는 속성(폐포)을 넓혀 보면 판단됨"],"w":["d → ab, ab → cde이므로 d 하나로 모든 속성이 결정됨. 후보키 맞음","ab → cde로 바로 전체가 결정됨. 후보키 맞음","","e → b이므로 ae가 있으면 ab를 얻고, ab → cde로 전체 결정. 후보키 맞음"],"t":"후보키 판정은 '이 속성들로 시작해서 화살표를 타면 전부 나오나?'만 해 보면 됩니다. ac처럼 출발할 화살표가 없으면 바로 탈락."},"1687":{"k":["**2NF 위배** = 부분 함수 종속: 복합 PK의 일부(상품번호)만으로 결정되는 속성(상품명)이 있음"],"w":["한 칸에 값이 하나씩만 있으니 1NF는 만족","","3NF를 따지기 전에 2NF부터 깨져 있으므로 '만족하지 않는 정규형'은 2NF","4NF는 다치 종속 문제로, 2NF도 안 되는 상태에서 볼 단계가 아님"],"t":"'만족하지 않는 정규형'은 가장 낮은 단계에서 답이 정해집니다. 아래부터 차례로 확인하세요."},"1688":{"k":["관서번호 → 관리점번호, 관서명, 상태, 관서등록일자 = PK **일부**에 종속 → **2차 정규화**","분리한 테이블의 PK는 결정자(관서번호) 하나"],"w":["2차 정규화는 맞지만, 떼어낸 테이블에 납부자번호까지 PK로 남기면 부분 종속이 그대로 남음","부분 종속 제거는 3차가 아니라 2차. PK에 납부자번호가 남은 것도 틀림","","PK 구성은 맞지만 부분 종속 제거를 3차 정규화라고 한 것이 틀림"],"t":"정규화 결과 테이블의 PK는 항상 '결정자'입니다. FD 왼쪽에 있는 것만 PK로 가져가면 됩니다."},"1689":{"k":["정규화: 중복 제거 → 용량 감소, **입력·수정·삭제 성능 향상**","조회는 조인이 늘어 **느려질 수도** 있음 (보장 X)","반정규화도 조회 성능을 항상 올리지는 않음"],"w":["중복 속성을 없애므로 저장 용량이 줄어듦. 맞음","중복이 없어 한 곳만 고치면 되므로 일반적인 데이터 처리(DML) 성능은 좋아짐. 맞음","반정규화가 늘 빠른 건 아니고, 정규화로 테이블이 작아져 오히려 빨라지는 경우도 있음. 맞음",""],"t":"성능 문제에서 '항상', '보장'이 붙은 문장은 거의 오답입니다. 정규화·반정규화 모두 상황에 따라 달라집니다."},"1690":{"k":["같은 성격의 컬럼이 1~9처럼 **반복**되면 1NF 위배 → 행으로 분리(1차 정규화)","컬럼마다 인덱스를 만들면 DML 성능 저하"],"w":["컬럼 단위로 반복되는 그룹이 있다는 건 1NF를 '위반'한 상태. 1NF라고 할 수 없음","조건이 여러 컬럼에 OR로 걸리면 PK 인덱스로는 해결 안 됨. 인덱스 없는 컬럼 하나 때문에 전체를 읽게 됨","반복 속성은 2NF가 아니라 1NF 문제. '이전종속'도 맞지 않는 용어",""],"t":"'코드1, 코드2, …코드9'처럼 번호 붙은 컬럼 묶음을 보면 1차 정규화부터 떠올리세요."},"1691":{"k":["1NF: 반복 그룹(LAB실 이용 1~4, 대출도서 여러 권) 분리","2NF: 부분 종속(도서 정보) 분리","3NF: 이행 종속(학과명, 승인교수명) 분리 → 학과·학생·교수·LAB실이용·대출·대출도서·도서 **7개**"],"w":["학과나 교수처럼 이행 종속으로 떨어져 나가야 할 엔터티를 빼먹은 개수","도서 또는 대출도서 분리를 빠뜨린 개수","","필요 이상으로 쪼갠 개수. 대출자 정보는 학생·교수로 이미 표현됨"],"t":"엔터티 개수 세기는 '반복 묶음 → 새 엔터티', '이름(명)이 코드에 딸려 있음 → 새 엔터티' 두 가지만 체크하며 세면 됩니다."},"1692":{"k":["**3NF** = 2NF를 만족하면서 PK가 아닌 속성이 PK에 **이행적으로 종속되지 않음**","각 단계는 이전 단계를 전제로 함"],"w":["3NF 정의의 전제는 1NF가 아니라 2NF","㉠ 자리는 2NF여야 함. 1NF에서 바로 3NF로 가지 않음","","순서가 뒤바뀜. ㉠이 2NF, ㉡이 3NF"],"t":"정의 문장에 '이행'이 나오면 3NF, '부분'이 나오면 2NF, '원자값'이면 1NF입니다."},"1693":{"k":["정규화는 **논리** 데이터 모델링 단계의 활동","1NF 원자값 → 2NF 주식별자 전체에 종속 → 3NF 이행 종속 없음"],"w":["","1NF는 모든 속성이 인스턴스마다 값 하나만 가진다는 뜻이라 맞음","3NF는 2NF를 전제로 하므로 일반속성이 주식별자 전체에 종속돼 있다는 말이 맞음","반정규화는 중복을 허용해 성능을 노리지만 늘 빨라지는 건 아님. 맞음"],"t":"단계 짝: 개념 = ERD 처음 작성, 논리 = 정규화, 물리 = 반정규화·인덱스. 정규화 앞에 '개념'이 붙으면 오답 신호입니다."},"1694":{"k":["**식별 관계**: 부모 식별자 → 자식 **식별자(PK)**에 포함","**비식별 관계**: 부모 식별자 → 자식 **일반속성**","관계 = 식별자 상속, 조인 = 상속된 속성(매핑키)으로 결합"],"w":["조인은 상속받은 속성을 매핑키로 써서 데이터를 결합하는 것. 맞는 정의","","관계를 맺는다는 건 식별자를 상속시켜 나중에 그 키로 결합하겠다는 뜻. 맞음","주문.고객번호 = 고객.고객번호로 연결하므로 조인키는 고객번호. 맞음"],"t":"식별/비식별을 바꿔 쓰는 함정이 가장 흔합니다. '식별 관계 = 자식 PK가 된다'만 확실히 잡아 두세요."},"1695":{"k":["**2NF**: 일반속성이 주식별자 **전체**에 종속 (부분 종속 없음)"],"w":["1NF는 모든 속성이 원자값(하나의 값)을 가지는 것","","3NF는 일반속성끼리의 이행 종속이 없는 것","BCNF는 모든 결정자가 후보키인 것"],"t":"'전체에 종속' = 2NF, '이행 종속 없음' = 3NF, '결정자가 후보키' = BCNF. 정의 문장의 핵심 단어 하나로 고르면 됩니다."},"1696":{"k":["학번 → 지도교수명, 학번 → 학과명: 복합 PK(학번, 과목코드)의 **일부**에 종속 → 2NF 위배","현재 상태 = 1NF, 다음 작업 = **2차 정규화**"],"w":["","부분 종속이 남아 있어 2NF가 아님. 따라서 '2차 정규형'이라 할 수 없음","2NF도 못 갖췄으니 3NF는 더욱 아님","BCNF는 3NF보다 위 단계라 해당 없음"],"t":"FD 목록에서 왼쪽이 PK 일부(학번만)인 줄이 하나라도 있으면 '1정규형, 2차 정규화 대상'으로 바로 답이 나옵니다."},"1697":{"k":["한 칸에 '10,11', '노래,댄스'처럼 값이 **여러 개** → 1NF 위배","1차 정규화로 고객-취미를 행 단위로 분리"],"w":["","2차 정규화(부분 종속)는 1NF를 만족한 뒤에 따질 문제","3차 정규화는 이행 종속 문제라 아직 해당 없음","4차 정규화는 다치 종속 문제라 해당 없음"],"t":"표 안에 쉼표로 이어진 값이 보이면 생각할 것 없이 1차 정규화입니다."},"1698":{"k":["NULL = 모르는 값, 값의 부재","**0도, 공백('')도 아님** (Oracle은 ''를 NULL로 저장하지만 개념상 다름)","IS NULL 외 비교는 모두 UNKNOWN"],"w":["아직 정해지지 않은 '모르는 값'이라는 설명이 맞음","값이 없다는 '부재'의 의미도 맞음","","= , <>, > 같은 비교는 모두 UNKNOWN을 돌려줌. 맞음"],"t":"NULL 정의 문제에서 '0', '공백', '빈 문자열'과 같다고 하면 무조건 오답입니다."},"1699":{"k":["(사번, 부서) PK에서 부서 → 사무실 = **부분 종속** → 분리 = **2차 정규화**","정규화하면 조인이 필요해 조회 성능은 떨어질 수 있음"],"w":["","PK 일부(부서)에 종속된 사무실을 떼어냈으니 2차 정규화가 맞음","(B)의 두 테이블 모두 이행 종속이 없어 3NF까지 만족. 맞음","사번으로 사무실을 찾으려면 두 테이블을 조인해야 하므로 성능 저하가 맞음"],"t":"원래 테이블에 다중값이 없었다면 '제1정규화 수행'은 성립하지 않습니다. 무엇이 떨어져 나갔는지로 단계를 판단하세요."},"1700":{"k":["**원자성**: 묶인 작업은 전부 수행되거나 전혀 수행되지 않음","한 트랜잭션으로 묶고 **끝에서 한 번** COMMIT","중간에 장애 → 이미 한 작업을 UNDO(롤백)"],"w":["반드시 함께 처리돼야 하므로 하나의 트랜잭션으로 묶는 게 맞음","","'모두 수행 또는 모두 미수행'은 원자성의 정의 그대로","A만 끝나고 장애가 나면 A를 되돌려야 원자성이 지켜짐. 맞음"],"t":"'각각 커밋'은 트랜잭션을 두 개로 쪼갠다는 뜻입니다. 함께 처리해야 하는 작업 문제에서 나오면 오답."},"1701":{"k":["NULL + 숫자 = **NULL**","NULL과 비교 = **UNKNOWN** (NULL = NULL도 TRUE 아님)","집계함수는 NULL을 **제외** (0으로 치지 않음)"],"w":["","비교 결과는 NULL이 아니라 UNKNOWN(알 수 없음)","NULL = NULL도 UNKNOWN이라 WHERE에서 걸러짐. TRUE가 아님","SUM·AVG 등은 NULL을 0으로 바꾸지 않고 계산에서 아예 뺌. AVG의 분모도 줄어듦"],"t":"NULL 규칙 세 줄: 계산하면 NULL, 비교하면 UNKNOWN, 집계하면 제외. 이 셋만 구분하면 NULL 문제는 거의 다 풀립니다."},"1702":{"k":["인조식별자: 본질식별자가 복잡할 때 만듦","단점: **중복 데이터를 막기 어려움**, **추가 인덱스** 필요","편하다고 무조건 쓰지 않고 필요할 때만"],"w":["본질식별자가 여러 속성으로 복잡해지면 일련번호로 대신하는 경우가 많음. 맞음","일련번호가 다르면 같은 내용이 두 번 들어가도 PK가 막지 못함. 맞음","본질 속성으로 조회하거나 중복을 막으려면 그쪽에 인덱스를 따로 만들어야 함. 맞음",""],"t":"식별자 문제에서 '되도록 사용하는 것이 바람직'처럼 한쪽을 무조건 권하는 문장은 오답일 가능성이 큽니다."},"1703":{"k":["**DCL**: GRANT, REVOKE (권한)","DML: SELECT·INSERT·UPDATE·DELETE·MERGE / DDL: CREATE·ALTER·DROP·RENAME·TRUNCATE / TCL: COMMIT·ROLLBACK·SAVEPOINT"],"w":["INSERT는 데이터를 넣는 DML","RENAME은 객체 이름을 바꾸는 DDL","COMMIT은 트랜잭션을 확정하는 TCL",""],"t":"DCL은 딱 두 개, GRANT와 REVOKE만 외우면 됩니다. 나머지는 지우는 방식으로 풀어도 충분."},"1704":{"k":["DML 4종: INSERT(입력) · **UPDATE(수정)** · DELETE(삭제) · SELECT(조회)"],"w":["","SELECT는 조회만 하고 값을 고치지 않음","ALTER는 데이터가 아니라 테이블 구조를 바꾸는 DDL","REVOKE는 권한을 회수하는 DCL"],"t":"'데이터 값'을 바꾸면 UPDATE, '테이블 구조'를 바꾸면 ALTER. 무엇을 바꾸는지로 구분하세요."},"1705":{"k":["**TCL**: COMMIT · ROLLBACK · SAVEPOINT","DML 결과를 트랜잭션 단위로 확정·취소"],"w":["DDL은 테이블 같은 구조를 정의하는 명령","DML은 데이터를 조회·조작하는 명령","","'TML'이라는 SQL 분류는 없음"],"t":"'트랜잭션'이라는 단어가 지문에 나오면 TCL입니다. 일부 교재에서 DCL로 묶기도 한다는 말까지 지문에 나와도 답은 TCL."},"1706":{"k":["SELECT 필수 절: **SELECT, FROM** (Oracle)","상수만 조회할 때도 `FROM DUAL`","WHERE·GROUP BY·ORDER BY는 선택"],"w":["WHERE는 조건이 필요할 때만 쓰는 선택 절. 맞음","DISTINCT로 중복 행을 한 건으로 줄일 수 있음. 맞음","","SELECT 절에 스칼라 서브쿼리를 쓸 수 있음. 맞음"],"t":"Oracle 기준 문제에서 FROM이 빠진 SELECT는 오류입니다. SQL Server는 FROM 없이 되지만 시험은 Oracle 기준."},"1707":{"k":["SELECT = DML","GRANT = DCL, DROP·ALTER = DDL"],"w":["","GRANT는 권한을 주는 DCL. TCL은 COMMIT·ROLLBACK·SAVEPOINT","DROP은 객체를 지우는 DDL","ALTER는 구조를 바꾸는 DDL"],"t":"SELECT를 DQL로 따로 보는 교재도 있지만, 보기가 DML·DDL·DCL·TCL 네 가지로만 나오면 SELECT는 DML입니다."},"1708":{"k":["**DDL**: CREATE · ALTER · DROP · RENAME · TRUNCATE (구조 정의)","GRANT는 DCL"],"w":["CREATE는 객체를 만드는 DDL","","ALTER는 구조를 바꾸는 DDL","DROP은 객체를 지우는 DDL"],"t":"'구조'라는 단어가 나오면 DDL. 그 범주에 권한 명령(GRANT, REVOKE)이 섞여 있으면 그게 답입니다."},"1709":{"k":["**WHERE**: 행 조건 / HAVING: 그룹 조건 / GROUP BY: 묶기 / ORDER BY: 정렬"],"w":["","GROUP BY는 같은 값끼리 묶는 절이지 조건을 거는 절이 아님","ORDER BY는 결과를 정렬하는 절","HAVING도 조건이지만 GROUP BY로 묶은 그룹에 거는 조건"],"t":"개별 행을 거르면 WHERE, 묶은 그룹을 거르면 HAVING. '원하는 데이터만'처럼 행 단위면 WHERE입니다."},"1710":{"k":["집계함수는 **WHERE에 쓸 수 없음** → HAVING으로","WHERE는 GROUP BY보다 먼저 실행되어 그 시점엔 그룹이 없음"],"w":["SELECT의 AVG는 GROUP BY DEPTNO와 함께 쓰여 문제없음","FROM EMP는 문법상 문제없음","","GROUP BY DEPTNO는 SELECT의 DEPTNO와 맞아 문제없음"],"t":"실행 순서(FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY)를 떠올리면, WHERE 시점에 AVG를 계산할 그룹이 없다는 게 바로 보입니다."},"1711":{"k":["SUM은 NULL을 **빼고** 더함","더할 값이 전부 NULL이면 SUM 결과는 **NULL**","NULL + 숫자 = NULL"],"w":["첫 번째는 COL2 합 60 + COL3 합 30 = 90. 60은 COL2만 더한 값","첫 번째가 90이 아님. 두 번째 결과 NULL은 맞음","","두 번째는 COL1 > 0인 행이 30 하나뿐이고 그 행의 COL2가 NULL → SUM(COL2) = NULL, NULL + 20 = NULL. 20이 아님"],"t":"SUM(A) + SUM(B) 문제는 각 SUM을 따로 계산한 뒤 더하세요. 한쪽 SUM이 NULL이 되는 순간 전체가 NULL입니다."},"1712":{"k":["NULL 비교는 **IS NULL / IS NOT NULL**만","`= NULL`, `<> NULL`, `!= NULL`은 항상 UNKNOWN → 0건"],"w":["","<> NULL은 UNKNOWN이라 어떤 행도 나오지 않음","!= NULL도 같은 이유로 0건","'NOT NULL'은 제약조건 문법이지 WHERE 조건 문법이 아님. IS가 빠져 오류"],"t":"NULL 앞에는 반드시 IS가 붙어야 합니다. 비교 연산자 기호가 NULL 앞에 있으면 결과는 0건이에요."},"1713":{"k":["**Oracle**: ''(빈 문자열)를 **NULL로 저장** → `= ''`로 못 찾고 IS NULL로 찾음","**SQL Server**: ''는 길이 0인 문자 → `= ''`로 찾히고 IS NULL로는 안 찾힘","문자 컬럼 = 숫자 비교 시 컬럼 쪽이 숫자로 변환 → 숫자로 못 바꾸는 값이 하나라도 있으면 오류"],"w":["VARCHAR2 컬럼을 숫자 1과 비교하면 모든 행의 값을 숫자로 바꿔 보는데, 'A01'처럼 숫자로 못 바꾸는 값이 하나라도 있으면 오류. '001' 같은 값이 '하나 있다'고 되는 게 아니라 '전부' 숫자 형식이어야 함","Oracle에서 ''를 넣으면 공백 문자가 아니라 NULL이 저장됨","Oracle에서는 ''가 NULL이라 `서비스명 = ''`는 NULL과의 비교 → 0건. IS NULL로 찾아야 조회됨",""],"t":"'' 문제는 DBMS 이름부터 확인하세요. Oracle이면 '' = NULL, SQL Server면 '' ≠ NULL. 이 한 줄로 보기 두세 개가 정리됩니다."},"1714":{"k":["**LTRIM(문자, 집합)**: 왼쪽부터 집합에 속한 문자를 지우다가 **다른 문자를 만나면 멈춤**","오른쪽은 RTRIM, 양쪽은 TRIM"],"w":["LOWER는 모든 글자를 소문자로 바꿔 'sql expert'. 맞음","UPPER는 모든 글자를 대문자로 바꿔 'SQL EXPERT'. 맞음","'A'의 아스키코드는 65. 맞음",""],"t":"TRIM 계열 문제는 L(왼쪽)·R(오른쪽)·양쪽 중 어느 쪽인지만 보면 됩니다. 결과 문자열 끝에 지워질 문자가 남아 있는지 확인하세요."},"1715":{"k":["DATE 컬럼은 **시·분·초까지** 저장됨","`TO_DATE('201501','YYYYMM')` = 2015-01-01 **00:00:00** 한 시점","'1월 전체'는 범위 조건(>= 1/1 AND < 2/1)이나 TO_CHAR(…, 'YYYYMM')으로"],"w":["1월 1일 0시 ~ 1월 31일 23:59:59 범위와 가입일시 조건이라 1월 전체를 찾음. ②③과 결과 같음","1월 1일 이상 2월 1일 미만 범위는 1월 전체와 같음. 다중 컬럼 IN도 같은 조건","TO_CHAR로 'YYYYMM'이 201501인 행 = 1월 전체. 결과 같음",""],"t":"날짜를 = 로 비교하는 보기는 '그 순간 딱 하나'만 찾습니다. 기간을 묻는 문제에서 = 가 보이면 그 보기가 다른 결과일 가능성이 큽니다."},"1716":{"k":["집계함수는 **NULL 제외**, WHERE에 **못 씀**","GROUP BY에서 SELECT 별칭 **사용 불가** (GROUP BY가 SELECT보다 먼저 실행)","HAVING은 보통 GROUP BY 뒤에 씀"],"w":["집계함수는 NULL인 행을 빼고 계산함. '포함하여'가 틀림","GROUP BY는 SELECT보다 먼저 실행돼 그 시점엔 별칭이 없음. 시험 기준 사용 불가","집계함수는 WHERE에 올 수 없고 HAVING에서 씀",""],"t":"별칭 문제는 '실행 순서상 별칭이 만들어진 뒤인가?'만 따지면 됩니다. SELECT 뒤에 실행되는 건 ORDER BY 하나뿐."},"1717":{"k":["`LENGTH(C1) - LENGTH(REPLACE(C1, CHR(10)))` = 줄바꿈 **개수**","+1 하면 **줄 수**","REPLACE 세 번째 인자 생략 = 삭제"],"w":["행 수(2건)를 센 값. 문제는 줄 수의 합을 묻고 있음","줄바꿈 개수만 더한 값(1 + 2). 행마다 +1을 해야 줄 수가 됨","","줄 수를 행마다 하나씩 더 센 값. 'A↵A'는 2줄, 'B↵B↵B'는 3줄이라 합 5"],"t":"'전체 길이 − 특정 문자를 지운 길이' 패턴은 그 문자의 개수를 세는 공식입니다. 이 공식은 다른 문제에도 자주 나와요."},"1718":{"k":["Oracle 날짜 연산 단위는 **일**","1/24 = 1시간, 1/24/60 = 1분, 1/24/60/60 = 1초","1/24/(60/10) = 1/24/6 = **10분**"],"w":["1시간 1분을 더한 값. 1/24/6은 1시간이 아니라 10분","5분을 더한 값. 60/10 = 6이라 1시간을 6으로 나눈 10분","","30분을 더한 값. 1시간을 2가 아니라 6으로 나눠야 함"],"t":"분수 식은 '1/24 = 1시간'에서 출발해 나머지 숫자로 나누세요. 1/24/(60/10) → 60분 ÷ 6 = 10분처럼 분 단위로 바꾸면 빠릅니다."},"1719":{"k":["단순 CASE: `CASE 컬럼 WHEN 값 THEN … ELSE … END` (= 비교만)","검색 CASE: `CASE WHEN 조건 THEN …`","DECODE(컬럼, 비교값, 결과, 기본값) 순서"],"w":["IS는 NULL 비교(IS NULL)에만 쓰는 연산자. `LOC IS 'NEW YORK'`은 문법 오류","","CASE의 기본값은 ELSE. DEFAULT라는 키워드는 없어서 오류","DECODE는 (컬럼, 비교값, 결과, 기본값) 순서. 'EAST'와 'NEW YORK' 자리가 바뀌어 LOC = 'EAST'일 때 'NEW YORK'을 돌려주는 식이 됨"],"t":"= 조건 하나만 쓰는 검색 CASE는 언제나 단순 CASE로 바꿀 수 있습니다. 바꿀 때 ELSE와 END가 그대로 있는지 확인하세요."},"1720":{"k":["조건부 집계: `SUM(CASE WHEN 조건 THEN 1 END)` → 맞는 행만 1, 나머지는 NULL이라 빠짐","ELSE 1을 붙이면 **모든 행이 1** → 전체 인원 수가 됨","ISNULL(SQL Server) = NVL(Oracle)"],"w":["SQL Server의 ISNULL로 NULL을 0으로 바꾼 것. 포지션별 인원이 정상으로 나옴","단순 CASE로 같은 조건을 쓴 것. 결과 같음","검색 CASE로 같은 조건. 결과 같음",""],"t":"CASE 집계 문제는 ELSE가 무엇인지부터 보세요. ELSE가 없거나 ELSE 0이면 정상, ELSE 1처럼 '맞지 않는 행에도 값'을 주면 결과가 달라집니다."},"1721":{"k":["HAVING은 **그룹 단위 조건**","`HAVING MAX(수량) > 10` = 그룹(고객) 안에 수량 10 초과 주문이 **한 번이라도** 있음","SELECT의 SUM(수량)은 그 고객 전체 주문의 합"],"w":["고객번호가 아니라 수량에 대한 조건","","주문 횟수를 세려면 COUNT(*) > 10이어야 함. MAX는 가장 큰 수량 값","합계 조건이면 HAVING SUM(수량) > 10이어야 함. 여기는 MAX"],"t":"HAVING 해석은 집계함수 이름을 그대로 읽으세요. MAX > 10 = '가장 큰 게 10 초과' = '하나라도 10 초과'."},"1722":{"k":["**NULLIF(A, B)**: A = B면 NULL, 다르면 A","NVL(A, B): A가 NULL이면 B / COALESCE: 첫 번째 NULL 아닌 값"],"w":["","NVL은 첫 인자가 NULL일 때 두 번째 값으로 바꾸는 함수. 같으면 NULL로 만드는 기능이 아님","IFNULL은 MySQL 함수이고 기능도 NVL과 같음","COALESCE는 나열된 값 중 처음으로 NULL이 아닌 값을 돌려줌"],"t":"'같으면 NULL'은 NULLIF뿐입니다. 이름에 IF가 붙어 '같으면(IF) NULL'로 외우세요."},"1723":{"k":["ORDER BY에는 **컬럼명 · 별칭 · 위치번호**를 쓸 수 있음","별칭을 붙여도 원래 컬럼명으로 정렬 가능","정렬 방향(ASC/DESC)이 결과를 가름"],"w":["DNAME ↑, LOC ↑, 세 번째 컬럼(DEPTNO) ↓. 기준 결과","AREA는 LOC의 별칭이라 ①과 같은 정렬","1번 = DNAME, AREA = LOC, 3번 = DEPTNO DESC. ①과 같음",""],"t":"정렬 비교 문제는 각 보기를 '컬럼 + 방향' 목록으로 바꿔 적어 보세요. 방향 하나가 다른 보기가 답입니다."},"1724":{"k":["LIKE: `_` = 정확히 1글자, `%` = 0글자 이상","'2번째 글자 S' → 앞에 `_` 하나 + S","'4글자 이상' → `_` 개수 + 최소 글자 수 확인"],"w":["","_ S % _ _ → 1글자 + S + 0글자 이상 + 2글자 = 2번째가 S, 최소 4글자. 조건 만족","_ S _ % _ → 2번째가 S, 최소 4글자. 조건 만족","_ S _ _ % → 2번째가 S, 최소 4글자. 조건 만족"],"t":"%는 '없어도 된다'는 점이 핵심입니다. 패턴 맨 앞에 %가 있으면 그 뒤 글자가 몇 번째인지 보장할 수 없어요."},"1725":{"k":["묶기 = **GROUP BY**, 그룹 조건 = HAVING","내림차순 = **DESC**, 오름차순(기본) = ASC"],"w":["","HAVING은 이미 묶인 그룹을 거르는 절. 그룹을 만드는 건 GROUP BY","ASC는 오름차순이라 '내림차순'과 반대","HAVING도 ASC도 모두 틀림"],"t":"'~별로 묶어' → GROUP BY, '~별 ~가 n 이상인' → HAVING. 문제 문장의 동사로 구분하세요."},"1726":{"k":["SUBSTR(문자, 시작, 길이): 위치는 **1부터**, **공백도 한 글자**","ROUND(4.875, 2) → 셋째 자리에서 반올림 = 4.88"],"w":["소수 셋째 자리 5에서 반올림해 4.88. 맞음","'KOREAN'은 6글자. 맞음","MySQL DATE_FORMAT으로 '%Y-%m-%d' 형식 출력 2022-11-02. 맞음",""],"t":"SUBSTR 문제는 글자 위에 번호를 직접 적으세요. G1 a2 n3 g4 n5 e6 u7 n8 처럼 세면 실수가 없습니다."},"1727":{"k":["**인라인 뷰**(FROM 절 서브쿼리)는 같은 FROM의 다른 테이블을 참조할 수 없음","'~별 최초' = GROUP BY ~ + MIN(날짜)를 인라인 뷰로 만든 뒤 원본과 조인"],"w":["인라인 뷰 안에서 바깥 FROM의 C를 참조함. 인라인 뷰는 상관 서브쿼리처럼 쓸 수 없어 오류","","광고ID로 묶으면 '광고별' 최초 일자가 나와 광고매체별 최초가 아님","GROUP BY가 없어 전체에서 최소값 한 건만 나옴. 광고매체별이 아님"],"t":"'~별'이라는 말이 나오면 GROUP BY 기준이 그 컬럼인지부터 확인하세요. 기준만 틀려도 보기 둘이 빠집니다."},"1728":{"k":["`ROLLBACK TO SAVEPOINT a` = a **이후** 작업만 취소, a 이전은 유지","COMMIT 전까지 살아 있는 작업이 모두 확정"],"w":["(나)·(다)는 SAVEPOINT a 이후라 ROLLBACK TO a로 취소됨","(나)·(다)는 취소됐고, (마)는 COMMIT 전에 실행돼 반영됨","(가)는 SAVEPOINT a 이전이라 살아 있음. (나)·(다)는 취소",""],"t":"SAVEPOINT 문제는 위에서부터 '살아 있는 작업 목록'을 적어 가며 따라가세요. ROLLBACK TO가 나오면 그 지점 아래를 지우면 됩니다."},"1729":{"k":["GROUP BY는 **NULL도 하나의 그룹**으로 묶음","MAX·MIN은 NULL 제외, 전부 NULL이면 NULL","COLA + COLC는 둘 중 하나라도 NULL이면 NULL → SUM에서 빠짐"],"w":["","COLB가 NULL인 그룹이 빠짐. 또 MIN(COLA)는 NULL을 빼고 계산하므로 NULL이 아니라 실제 최솟값","COLB NULL 그룹은 COLA가 NULL이라 COLA + COLC도 NULL → SUMAC는 NULL. 나 그룹도 3 + 0 = 3이라 5가 아님","COLB NULL 그룹이 빠졌고 MIN(COLA)도 NULL이 아님"],"t":"GROUP BY 결과 행 수를 셀 때 NULL 그룹을 잊지 마세요. 보기 행 수만 세도 답이 좁혀지는 문제가 많습니다."},"1730":{"k":["HAVING COUNT(*) = 2 → 정확히 2건인 ID만 (100, 999)","ORDER BY에 CASE를 쓰면 **바꾼 값**으로 정렬 → 999는 0이 되어 맨 앞"],"w":["999가 정렬용으로 0이 되므로 100보다 앞에 와야 함","","200은 3건이라 HAVING에서 빠짐","200이 들어갈 수 없고 순서도 틀림"],"t":"ORDER BY 안의 CASE는 화면에 보이는 값이 아니라 '정렬 키'만 바꿉니다. 결과에는 원래 값(999)이 그대로 나와요."},"1731":{"k":["GROUP BY가 있으면 SELECT·ORDER BY에는 **GROUP BY 컬럼, 집계함수, 별칭**만","GROUP BY가 없으면 SELECT에 없는 컬럼으로도 정렬 가능"],"w":["매출금액은 SELECT에서 SUM에 붙인 별칭이라 ORDER BY에서 쓸 수 있음","GROUP BY가 없어서 SELECT에 없는 '년' 컬럼으로도 정렬 가능","","COUNT(*)는 집계함수라 GROUP BY 쿼리의 ORDER BY에 올 수 있음"],"t":"GROUP BY 쿼리에서는 '그룹 하나에 값이 하나로 정해지나?'를 물어보세요. 지역별로 묶었는데 '년'은 여러 개라 정렬 기준이 될 수 없습니다."},"1732":{"k":["1/12 = **2시간** (하루 24시간 ÷ 12)","1/12/(60/30) = 2시간 ÷ 2 = **1시간**"],"w":["1/12(2시간)만 더한 값. (60/30) = 2로 한 번 더 나눠야 함","1시간 30분. 계산상 나올 수 없는 값","","30분. 2시간을 4로 나눈 값"],"t":"1/12, 1/24, 1/48 같은 분수는 '하루 24시간을 몇으로 나눴나'로 바꾸면 바로 시간이 나옵니다. 1/12 → 2시간, 1/48 → 30분."},"1733":{"k":["NULLIF(A, B): 같으면 **NULL**","COALESCE: 첫 NULL 아닌 값 / NVL(A, B): A가 NULL이면 B"],"w":["COALESCE(NULL, 'A')는 처음 나오는 NULL 아닌 값 'A'를 돌려줌","","NVL('A', NULL)은 첫 인자가 NULL이 아니라 그대로 'A'","NVL(NULL, 0)은 0, 0 + 10 = 10"],"t":"NULL 함수 결과 문제는 함수마다 '첫 인자가 NULL인가?'부터 확인하면 한 줄씩 금방 계산됩니다."},"1734":{"k":["실행 순서: **FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY**"],"w":["적는 순서일 뿐 실행 순서가 아님. SELECT는 거의 마지막","SELECT가 WHERE보다 먼저 실행되지 않음","ORDER BY는 SELECT 결과를 정렬하므로 SELECT 뒤에 와야 함",""],"t":"'프웨그해셀오'로 외우세요. 별칭·집계함수 위치 문제도 전부 이 순서로 풀립니다."},"1735":{"k":["테이블 N개 조인에 필요한 조건은 최소 **N − 1**개","조건이 빠지면 그 사이에 카티션 곱 발생"],"w":["2개면 테이블 3개만 이을 수 있음","3개면 테이블 4개만 이을 수 있음","","N − 1개면 충분. 5개는 최소가 아님"],"t":"테이블을 점, 조인 조건을 선이라고 생각하면 점 5개를 한 줄로 잇는 데 선 4개가 필요합니다."},"1736":{"k":["컬럼은 **실제로 있는 테이블**에서 가져와야 함","여러 테이블에 같은 이름 컬럼이 있으면 **테이블명(별칭) 필수**","출연 = 배우와 영화를 잇는 교차 테이블"],"w":["출연 테이블에는 영화명이, 영화 테이블에는 배우명이 없어 오류","영화번호 = 배우번호처럼 의미 없는 조인 조건. 결과가 틀림 (> 8888도 '이상' 조건과 다름)","영화번호·배우번호가 두 테이블에 동시에 있어 접두사 없이 쓰면 '열의 정의가 애매함' 오류",""],"t":"조인 보기 비교는 세 가지만 보세요. ① 컬럼이 그 테이블에 있나 ② 조인 조건이 PK-FK로 맞게 이어졌나 ③ 공통 컬럼에 접두사가 붙었나."},"1737":{"k":["조인은 일반적으로 **PK-FK** 관계로 성립","EQUI = '=' 조인, 그 외 비교 연산자는 NON EQUI","옵티마이저는 테이블이 몇 개든 **2개씩** 짝지어 조인"],"w":["(마) NON EQUI JOIN은 대부분 가능하지만 설계상 불가능할 때도 있다는 설명이 맞아서 포함돼야 함","(나)는 틀린 설명. 3개씩이 아니라 항상 2개씩 조인","(나)는 틀렸고 맞는 (마)가 빠짐",""],"t":"조인 처리 단위는 늘 '두 개씩'입니다. 3개, 여러 개를 한 번에 조인한다는 문장은 오답."},"1738":{"k":["LIKE도 조인 조건이 될 수 있음 → 조건을 만족하는 **모든 조합**이 결과","S% → S로 시작, %T% → T 포함"],"w":["조건에 맞는 조합이 있으므로 0건이 아님","규칙 하나(S%)만 계산한 값. %T%도 SMITH·SCOTT 두 건이 맞음","","3 × 2 = 6은 조건이 없는 CROSS JOIN 결과. ALLEN은 두 규칙 모두 안 맞음"],"t":"규칙 테이블 조인은 '사원 × 규칙' 표를 그려 O·X를 채우면 됩니다. 칸 6개 중 O 개수가 답."},"1739":{"k":["순수 관계 연산자: **SELECT · PROJECT · JOIN · DIVIDE**","일반 집합 연산자: UNION · INTERSECTION · DIFFERENCE · PRODUCT"],"w":["SELECT(σ)는 행을 고르는 순수 관계 연산자","","JOIN은 순수 관계 연산자","DIVIDE도 순수 관계 연산자 (SQL에 직접 대응하는 구문은 없음)"],"t":"관계대수 연산자 목록에 DML 명령(UPDATE, INSERT, DELETE)이 섞여 있으면 그게 답입니다. 관계대수는 '조회'만 다룹니다."},"1740":{"k":["'B에 있는 건 빼고' = **NOT EXISTS** (안티 조인)","NOT EXISTS 안에서는 빼야 할 대상과 **모든 키(고객ID + 컨텐츠ID)**를 맞춰야 함","LEFT JOIN으로 빼려면 `IS NULL`"],"w":["NOT EXISTS 안에 컨텐츠ID 조건이 없어서, 고객이 비선호를 하나라도 등록했으면 그 고객의 추천이 전부 빠짐","비선호컨텐츠 기준 RIGHT OUTER JOIN이라 비선호에 등록된 것 위주로 남음. 원하는 것과 반대","LEFT OUTER JOIN 후 `D.컨텐츠ID IS NOT NULL`이면 비선호로 등록된 컨텐츠만 남음. 제외하려면 IS NULL이어야 함",""],"t":"'제외하라'는 문제는 NOT EXISTS의 서브쿼리 WHERE에 바깥과 맞출 키가 전부 들어갔는지부터 확인하세요. 키 하나 빠지면 너무 많이 지워집니다."},"1741":{"k":["직접 연결하는 컬럼이 없는 두 테이블을 조인하면 **카티션 곱**","M:N은 교차 엔터티(생산제품)를 거쳐야 연결됨","필요한 정보가 어느 테이블에 있는지 보고 조인 수를 최소로"],"w":["생산제품은 제품과 한 번, 생산라인과 한 번 조인되니 WHERE에 최소 2번 나오면 됨","","생산제품 쪽 끝이 ○(선택)라 생산제품과 대응되지 않는 제품·생산라인이 있을 수 있음","라인번호는 생산제품에도 있으므로 제품 + 생산제품 두 개만 조인하면 제품명을 알 수 있음"],"t":"'몇 개 조인해야 하나'는 '찾는 컬럼'과 '조건 컬럼'이 각각 어느 테이블에 있는지만 표시하면 바로 보입니다."},"1742":{"k":["'구매 이력이 있는 고객만' → **INNER JOIN**","'구매 횟수' → **COUNT**, 그룹 조건 → **HAVING**"],"w":["SUM(구매번호)는 구매번호 값을 더한 것이지 횟수가 아님","","LEFT OUTER JOIN이면 구매 이력이 없는 고객도 붙고, SUM으로 횟수를 셀 수도 없음","WHERE는 GROUP BY 앞에 와야 하고 그룹 조건(횟수)을 걸 수 없음. '구매번호 >= 3'은 횟수와 무관"],"t":"'횟수·건수'는 COUNT, '금액·합계'는 SUM. 문제 문장의 명사로 집계함수를 고르세요."},"1743":{"k":["**NON EQUI 조인**: = 대신 범위 조건으로 짝 찾기","`B.사용시간대 BETWEEN C.시작시간대 AND C.종료시간대`","ANSI JOIN은 JOIN마다 ON이 하나씩"],"w":["부등호 방향이 반대. 사용시간대가 시작시간대 이상, 종료시간대 이하여야 함","INNER JOIN을 ON 없이 연달아 쓰고 ON 하나에 조건을 몰면 문법 오류","","'BETWEEN JOIN'이라는 구문은 없음"],"t":"급여 등급, 시간대 단가처럼 '구간 테이블'이 나오면 BETWEEN 조인입니다. BETWEEN 양쪽에 어느 컬럼이 오는지만 확인하세요."},"1744":{"k":["**USING (컬럼명)**: 이름만, 괄호 필수, **접두사·조건식 불가**","USING 컬럼은 SELECT에서도 접두사 없이 씀","ON, WHERE 방식은 접두사 필수"],"w":["","ANSI INNER JOIN ... ON으로 같은 조건. 정상","Oracle 방식 WHERE 등가 조인. 정상","테이블명을 그대로 접두사로 쓴 WHERE 조인. 정상"],"t":"USING과 NATURAL JOIN에는 '테이블명.컬럼'이 절대 붙지 않습니다. 점(.)이 보이면 오류 보기."},"1745":{"k":["조인 조건 없는 `FROM A, B` = **CROSS JOIN** (카티션 곱)","EMP 14 × DEPT 4 = 56행"],"w":["FULL OUTER JOIN은 ON 조건이 반드시 필요하고 결과도 다름","SELF JOIN은 같은 테이블을 두 번 쓰는 조인","NATURAL JOIN은 같은 이름 컬럼(DEPTNO)으로 등가 조인해 14행",""],"t":"조인 조건이 없는 쉼표 조인을 ANSI로 바꾸면 언제나 CROSS JOIN입니다."},"1746":{"k":["LEFT OUTER JOIN의 **ON 조건은 '붙일지'만** 정함 → 기준(왼쪽) 행은 전부 남음","기준 테이블 조건을 거르려면 WHERE에","고객번호 IN 조건이 ON에 있으니 6명 모두 출력"],"w":["","IN 조건을 WHERE에 둔 경우의 결과. ON에 있으면 고객 6명이 모두 남음","INNER JOIN처럼 짝 있는 행만 남긴 결과","ON의 IN 조건을 무시하고 모든 고객에게 단말기를 붙인 결과"],"t":"OUTER JOIN에서 기준 테이블 조건이 ON에 있으면 '걸러지지 않는다'가 핵심입니다. 행 수는 기준 테이블 그대로, 붙는 값만 줄어요."},"1747":{"k":["FULL OUTER = LEFT 결과 **∪** RIGHT 결과 (UNION으로 중복 제거)","= INNER + 왼쪽에만 있는 행 + 오른쪽에만 있는 행 (UNION ALL)"],"w":["(다)도 INNER + A만 있는 것 + B만 있는 것이라 FULL OUTER와 같음","(나)도 LEFT ∪ RIGHT라 FULL OUTER와 같음","(가)는 FULL OUTER 자체라 당연히 같음",""],"t":"FULL OUTER를 다른 방식으로 쓴 보기는 '양쪽 짝 있는 것, 왼쪽만, 오른쪽만' 세 부분이 모두 들어 있는지만 확인하면 됩니다."},"1748":{"k":["LEFT = 왼쪽 전부, RIGHT = 오른쪽 전부, FULL = 양쪽 전부","건수 = 매칭 행 + 기준 쪽 단독 행","매칭: EMP의 C = 'w' 2행 ↔ DEPT 'w' 1행 → 2행"],"w":["","LEFT는 EMP 3행이 기준. 4건이 될 수 없음","FULL은 매칭 2 + EMP 단독 1(y) + DEPT 단독 2(z, v) = 5건","RIGHT는 매칭 2 + DEPT 단독 2 = 4건. FULL은 5건"],"t":"외부 조인 건수 문제는 '매칭 수 / 왼쪽만 / 오른쪽만' 세 숫자를 먼저 구하세요. LEFT = 매칭 + 왼쪽만, RIGHT = 매칭 + 오른쪽만, FULL = 셋 다."},"1749":{"k":["'~이 없는 …도 출력' → 그 …가 **기준(보존) 테이블**","DEPT를 왼쪽에 두었으니 **LEFT** OUTER JOIN"],"w":["","RIGHT면 EMP가 기준이라 사원 없는 부서가 빠짐","FULL이면 부서가 없는 사원까지 나와 요구보다 많음","INNER면 짝이 없는 부서가 빠짐"],"t":"LEFT/RIGHT는 '살려야 하는 테이블이 JOIN 키워드의 왼쪽인가 오른쪽인가'로만 고르면 됩니다."},"1750":{"k":["LEFT JOIN의 ON에 오른쪽 조건(B.C2 BETWEEN 1 AND 3)을 두면 그 조건에 맞는 행만 **붙임**","왼쪽 TAB1 5행은 전부 남음"],"w":["D는 B.C2 = 4라 조건에 안 맞아 붙지 않고 NULL이어야 함","","ON 조건을 WHERE처럼 적용해 왼쪽 행까지 줄인 결과. LEFT JOIN은 왼쪽 행을 줄이지 않음","D에 TAB2가 붙었고 E도 빠짐. 둘 다 틀림"],"t":"LEFT JOIN 결과 행 수는 (짝이 여러 개가 아니라면) 왼쪽 테이블 행 수와 같습니다. 행 수부터 맞는 보기를 고르세요."},"1751":{"k":["(+)가 붙은 쪽 = NULL이 채워질 **Inner 쪽** (게시글)","Inner 쪽 조건(B.삭제여부(+) = 'N') → ANSI **ON** 절","Outer(기준) 쪽 조건(A.사용여부 = 'Y') → **WHERE** 절"],"w":["","기준(게시판) 조건을 ON에 넣으면 걸러지지 않아 사용여부 N인 게시판도 나옴","Inner 쪽 조건을 WHERE에 두면 게시글 없는 게시판(NULL 행)이 탈락 → INNER JOIN과 같아짐","RIGHT OUTER로 바꾸면 기준이 게시글이 되어 의미가 달라짐"],"t":"(+) → ANSI 변환은 '(+) 붙은 조건은 ON, 안 붙은 조건은 WHERE'로 기계적으로 옮기면 됩니다."},"1752":{"k":["**컬럼끼리 더하기**: NULL이 하나라도 있으면 그 행은 NULL","**SUM**: NULL 행은 빼고 더함","SUM(A + B) ≠ SUM(A) + SUM(B) (NULL이 있을 때)"],"w":["SUM(COL2)는 NULL을 빼고 20 + 70 = 90. NULL이 아님","앞 두 행은 NULL이 섞여 행 결과가 NULL → 세 번째 행 50 + 70 + 20 = 140만 남음","","SUM(COL2) = 90, SUM(COL3) = 20 → 110"],"t":"SUM(식) 문제는 '행마다 식을 먼저 계산 → NULL 행 버림 → 남은 것 합계' 순서로 표를 그려 푸세요."},"1753":{"k":["반환 형태로 나눈 서브쿼리: **단일 행 · 다중 행 · 다중 컬럼**","다중 컬럼: `(A, B) IN (SELECT A, B …)` — 개수·위치 일치, SQL Server 미지원"],"w":["단일 행 서브쿼리는 결과가 1건 이하인 것. 컬럼 수 이야기가 아님","","다중 행 서브쿼리는 결과 '행'이 여러 건인 것. 지문은 여러 '컬럼'","'단일 칼럼 서브쿼리'라는 분류는 따로 없음"],"t":"'여러 칼럼', '동시에 비교', '개수와 위치 동일' 세 표현이 나오면 다중 컬럼 서브쿼리입니다."},"1754":{"k":["ROLLUP(A) = A별 + **총계**","CUBE(A) = A별 + **총계** (인자 하나면 ROLLUP과 같음)","GROUPING SETS(A) = A별 **만** (총계 없음)"],"w":["COL1별 합계 + UNION ALL로 붙인 전체 합계. ROLLUP(COL1)과 같은 결과","","ROLLUP(COL1)은 COL1별 + 총계. ①과 같음","CUBE(COL1)도 인자가 하나라 COL1별 + 총계. ①과 같음"],"t":"GROUPING SETS는 괄호 안에 쓴 것만 나옵니다. 총계를 원하면 ()를 직접 넣어야 한다는 점이 ROLLUP·CUBE와 가장 큰 차이."},"1755":{"k":["UNION 합집합 · **INTERSECT 교집합** · MINUS(EXCEPT) 차집합"],"w":["UNION은 합집합","","MINUS는 Oracle의 차집합","EXCEPT는 SQL Server(표준)의 차집합"],"t":"INTERSECT = intersection(교차) = 교집합. 영어 뜻 그대로입니다."},"1756":{"k":["집합 연산의 **ORDER BY는 맨 끝에 한 번만**","각 SELECT에 WHERE·GROUP BY·HAVING은 사용 가능","UNION은 중복 제거, UNION ALL은 유지"],"w":["UNION은 합친 뒤 중복 행을 하나로 만듦. 맞음","애초에 겹치는 행이 없으면 중복 제거할 게 없어 UNION과 UNION ALL 결과가 같음. 맞음","각 SELECT 문 안에 GROUP BY를 쓰는 건 가능. 맞음",""],"t":"ORDER BY는 '최종 결과'를 정렬하는 절이라 집합 연산 전체에 한 번뿐입니다. 중간 SELECT에 ORDER BY가 보이면 오류."},"1757":{"k":["INTERSECT(전체 ∩ 이용) = 이용된 적 있는 서비스","같은 결과: `NOT EXISTS (전체 MINUS 이용)` = 이용 안 된 것이 아닌 것","1:N 조인은 N쪽 건수만큼 중복이 생김"],"w":["서비스와 서비스이용은 1:N이라 그냥 조인하면 이용 건수만큼 같은 서비스가 반복 출력됨. INTERSECT는 중복 없음","","LEFT JOIN 후 IS NULL이면 이용된 적 없는 서비스만 나와 반대 결과","MINUS 순서가 반대(이용 − 전체)라 서비스에 없는 서비스ID를 찾는 셈. 사실상 0건"],"t":"집합 연산을 EXISTS·조인으로 바꾼 보기는 '중복 행이 생기는가'와 '방향(A−B인지 B−A인지)'만 확인하세요."},"1758":{"k":["집합 연산자는 **위에서부터 차례로** 수행 (괄호 없으면 우선순위 없음)","마지막이 UNION이면 그때까지 쌓인 결과 전체에서 중복 제거"],"w":["","(TBL1 UNION ALL TBL2)까지만 계산하고 마지막 UNION의 중복 제거를 빠뜨린 결과","UNION ALL만 세 번 한 결과. 마지막 UNION이 중복을 모두 없앰","계산상 나올 수 없는 결과"],"t":"UNION ALL과 UNION이 섞이면 '마지막 연산자'가 결과를 결정하는 경우가 많습니다. 마지막이 UNION이면 결과에 중복이 하나도 없어요."},"1759":{"k":["ROLLUP(A, B) = (A,B) + (A) + **()**","A, ROLLUP(B) = (A,B) + (A) — **총계 없음**","A, CUBE(B) = (A,B) + (A) (B 하나라 ROLLUP과 같음)","GROUPING SETS(A, (B, A)) = (A) + (A,B)"],"w":["GROUPING SETS(grade, (job, grade))는 grade별 + (grade, job)별. 결과표와 같음","","grade를 바깥에 두면 모든 그룹에 grade가 들어가 (grade, job) + (grade)만 생김. 결과표와 같음","CUBE(job)도 인자가 하나라 (grade, job) + (grade). 결과표와 같음"],"t":"결과표 맨 아래에 전체 총계 행(GRADE·JOB 모두 NULL)이 있는지부터 보세요. 없는데 ROLLUP(전체)가 보기에 있으면 그게 다른 결과입니다."},"1760":{"k":["`SUM(…) OVER (PARTITION BY 부서)` = 부서 **전체** 합","`OVER (PARTITION BY 부서 ORDER BY …)` = **누적** 합 (기본 RANGE ~ CURRENT ROW)","RATIO_TO_REPORT = 파티션 합 대비 비율"],"w":["RATIO_TO_REPORT(급여) OVER (PARTITION BY 부서코드)는 부서 합 대비 비율이라 결과와 같음","급여 ÷ 부서 전체 합(PARTITION BY만 사용)이라 결과와 같음","부서별 합계를 인라인 뷰로 구해 조인한 방식. 결과와 같음",""],"t":"윈도우 함수에 ORDER BY가 붙는 순간 '전체'가 '누적'으로 바뀝니다. 비율·합계 문제에서 OVER 안에 ORDER BY가 있는 보기를 먼저 의심하세요."},"1761":{"k":["1:1 양쪽 필수 → 두 테이블의 회원ID **집합이 똑같음**","같은 집합이면: INTERSECT = UNION = 원래 집합, EXCEPT = 공집합","UNION ALL = 두 배"],"w":["두 집합이 같아서 EXCEPT 결과는 항상 0건. 상세정보 없는 회원은 존재할 수 없음","UNION ALL은 중복을 남기므로 회원기본정보 건수의 2배","","같은 집합끼리는 INTERSECT 결과와 UNION 결과가 같음"],"t":"'1:1 양쪽 필수'라는 단서는 '두 키 집합이 같다'는 뜻입니다. 이 한 줄로 집합 연산 결과를 전부 계산할 수 있어요."},"1762":{"k":["START WITH = 루트, CONNECT BY PRIOR 부모키 = 자식FK → 순방향","**ORDER SIBLINGS BY**: 트리 모양 유지, 같은 부모 아래 형제끼리만 정렬","깊이 우선: 자식을 끝까지 내려간 뒤 다음 형제"],"w":["A는 루트라 1번째","","C는 형제 중 DESC로 먼저 와서 2번째","D는 B의 자식이라 B 다음, 4번째"],"t":"계층 출력 순서는 손으로 트리를 그린 뒤 '왼쪽 가지부터 끝까지' 내려가며 번호를 붙이면 정확합니다."},"1763":{"k":["루트 노드 **LEVEL = 1** (0 아님)","START WITH 시작점 / ORDER SIBLINGS BY 형제 정렬 / 순방향 = 부모 → 자식"],"w":["START WITH로 계층 시작점(루트)을 지정. 맞음","ORDER SIBLINGS BY는 형제 노드끼리만 정렬. 맞음","부모에서 자식 방향으로 내려가는 것이 순방향 전개. 맞음",""],"t":"LEVEL, ROWNUM, SUBSTR 위치처럼 Oracle의 순번은 모두 1부터 시작합니다. 0이 나오면 의심하세요."},"1764":{"k":["START WITH로 고른 **루트는 조건과 상관없이 포함**","CONNECT BY의 추가 조건은 **자식을 펼칠 때만** 적용 → 안 맞으면 그 가지째 제외","WHERE 조건은 전개 후 그 행만 제외"],"w":["","루트 001(2012년 입사)이 빠짐. 루트는 CONNECT BY 조건과 무관하게 나옴","루트 005와 001의 자식 003, 004가 빠짐","입사일자 조건을 무시하거나 엉뚱한 쪽에 적용한 결과. 006~008은 2014년 입사라 붙을 수 없음"],"t":"계층형 문제에서 조건이 CONNECT BY에 있는지 WHERE에 있는지가 답을 가릅니다. CONNECT BY면 '가지치기', WHERE면 '그 줄만 지우기'."},"1765":{"k":["PRIOR는 **CONNECT BY, SELECT, WHERE** 절에서 사용 가능","'PRIOR 자식 = 부모' → 순방향","SQL Server는 재귀 CTE(앵커 멤버 → 재귀 멤버)로 계층 전개"],"w":["SQL Server는 CTE를 재귀 호출해 계층을 펼침. 맞음","앵커 멤버로 시작 집합을 만들고 재귀 멤버를 반복 실행. 맞음","Oracle 계층 질의의 WHERE는 전개가 끝난 뒤 필터로 동작. 맞음",""],"t":"'~에만 사용할 수 있다'처럼 범위를 한정하는 문장은 거의 오답입니다. 문장 뒷부분이 맞아도 앞부분 한정어를 보세요."},"1766":{"k":["위로(역방향) + 아래로(순방향)를 모두 보려면 두 계층 질의를 **UNION**","역방향: `CONNECT BY PRIOR 상위코드 = 코드` / 순방향: `CONNECT BY 상위코드 = PRIOR 코드`","LEVEL은 각 질의의 시작점 기준"],"w":["","100부터 순방향이라 아시아지부 아래 모든 지사·지점이 LVL 1~3으로 나옴","121부터 역방향이라 121, 120, 100만 나오고 122가 빠짐","최상위(100)를 찾아 다시 순방향으로 펼쳐 ②와 같은 결과"],"t":"결과표의 LVL 값이 단서입니다. 시작점(120)이 LVL 1이고 위아래가 모두 LVL 2면 '시작점에서 양방향'이라는 뜻이에요."},"1767":{"k":["INNER JOIN ON · USING · NATURAL JOIN은 같은 조건이면 같은 결과","**CROSS JOIN** = 모든 조합 (1 × 2 = 2건)"],"w":["INNER JOIN ON B.NO = A.NO. 원래 SQL과 같은 1건","USING(NO)로 같은 등가 조인. 1건","","NATURAL JOIN은 같은 이름 컬럼 NO로 조인. 1건"],"t":"조인 문법 변환 문제는 '조인 조건이 그대로 살아 있나'만 보면 됩니다. 조건이 사라진 CROSS JOIN이 보통 답."},"1768":{"k":["윈도우 함수 없이 누적 합: **셀프 조인** + `A.일자 >= B.일자` + A.일자로 GROUP BY + SUM(B.값)","A = 기준일, B = 기준일까지의 모든 날"],"w":["셀프 조인 없이 일자별로 묶으면 그날 매출만 나와 전부 1000","B.일자로 묶으면 각 날짜 '이후' 날짜들이 붙어 역순 누적(첫날 10000)이 됨","","B.일자 >= A.일자라 그날부터 끝날까지 합 = 남은 기간 합계(역순 누적)"],"t":"누적 셀프 조인은 '기준 쪽으로 묶고, 반대쪽 값을 더한다'입니다. 부등호 방향과 GROUP BY 쪽이 일치하는지 확인하세요."},"1769":{"k":["단일 행 서브쿼리 결과로 비교 (E = 'i' → D = 'x')","COUNT(DISTINCT 식) = 식 결과의 **종류 수**","|| = 문자 연결"],"w":["D = 'x'인 행이 두 개 있어 0건이 아님","B 값('a')만 보고 중복을 센 결과. A||B는 '1a', '2a'로 서로 다름","","EMP 전체 3건을 센 결과. WHERE 조건으로 D = 'y'인 행은 빠짐"],"t":"DISTINCT 뒤가 '연결된 식'이면 연결한 결과 문자열을 실제로 적어 보고 서로 다른 개수를 세세요."},"1770":{"k":["다중 행 결과에는 **IN · ANY · ALL · EXISTS**","서브쿼리 위치: SELECT · FROM · WHERE · HAVING · ORDER BY 등","연관 서브쿼리 = 메인쿼리 컬럼을 참조","다중 컬럼 서브쿼리는 **SQL Server 미지원**"],"w":["(마)는 SQL Server에서 다중 컬럼 비교를 지원하지 않아 틀림","","(다) 여러 행 결과를 =, <= 같은 단일 행 연산자로 비교하면 오류","(마)가 틀렸고, 맞는 (라)가 빠짐"],"t":"'오라클 및 SQL Server 등 모두'처럼 여러 DBMS를 한꺼번에 묶는 문장은 차이점 함정인 경우가 많습니다."},"1771":{"k":["**RATIO_TO_REPORT** = 값 / 파티션 합 (A그룹 합 100 → 10/100 = 0.1)","**NTILE(5)** = 정렬 후 5등분 번호 (10행 → 2개씩 1~5)","PERCENT_RANK는 0부터, RANK·DENSE_RANK는 1~n"],"w":["PERCENT_RANK는 첫 행이 0이라 0.1이 나올 수 없고, DENSE_RANK(VAL2)는 1~10이 나옴","CUME_DIST는 누적 비율이라 0.1, 0.2 패턴이 안 나오고, RANK도 1~10","PERCENT_RANK는 0부터 시작하고 RANK는 1~10",""],"t":"결과 숫자 패턴을 먼저 읽으세요. 1,1,2,2,3,3… 처럼 같은 숫자가 일정하게 반복되면 NTILE, 합이 1이 되는 비율이면 RATIO_TO_REPORT."},"1772":{"k":["'N이 하나라도 있는 회원' = EXISTS / IN / 조인 + GROUP BY 모두 가능","EXISTS·스칼라 서브쿼리에 **바깥과 연결하는 조건**이 빠지면 전체 테이블 기준으로 판단"],"w":["EXISTS + 회원번호 연관 조건으로 'N이 있는 회원'만 남김. 같은 결과","IN 서브쿼리로 'N이 있는 회원번호' 목록과 비교. 같은 결과","","조인 후 'N'인 행만 남기고 GROUP BY로 중복을 없앰. 같은 결과"],"t":"서브쿼리 보기 중 바깥 테이블 별칭(A.)이 서브쿼리 안에 하나도 안 나오는 보기를 찾으세요. 연관 조건이 빠진 그 보기가 대개 다른 결과입니다."},"1773":{"k":["EXISTS 안의 **HAVING**: GROUP BY가 없으면 서브쿼리 결과 전체가 한 그룹","`COUNT(*) < 전체 이벤트 수` = 회원별 받은 메일이 이벤트 수보다 적음 = **발송 누락 회원**","㉡ 연관 조건으로 회원마다 따로 셈"],"w":["모든 회원이 아니라 받은 메일 수가 이벤트 수보다 적은, 즉 발송이 누락된 회원만 뽑음","㉡을 빼면 회원별로 셀 수 없고 전체 발송 건수로 비교하게 되어 결과가 달라짐","","GROUP BY 없이 HAVING만 써도 결과 전체를 한 그룹으로 보고 정상 실행됨"],"t":"EXISTS 안에 HAVING이 보이면 '조건을 만족하는 그룹이 있나'로 읽으세요. 서브쿼리가 0행이면 거짓, 1행이면 참입니다."},"1774":{"k":["다중 행 연산자(IN, ANY, ALL, EXISTS)는 **단일 행 결과에도 사용 가능**","단일 행 연산자(=, <, >)는 다중 행 결과에 **사용 불가**","값을 넘겨주는 용도는 주로 비연관 서브쿼리"],"w":["단일 행 서브쿼리는 =, >, < 같은 단일 행 연산자를 씀. IN, ALL은 다중 행 연산자","","메인쿼리에 값을 제공하는 건 주로 비연관 서브쿼리. 연관 서브쿼리는 메인 행마다 조건 확인용","비연관 서브쿼리는 먼저 한 번 실행해 결과를 넘기기도 해서 '항상' 메인 먼저가 아님"],"t":"큰 그릇(다중 행 연산자)에는 작은 것(1행)도 담기지만, 작은 그릇(단일 행 연산자)에 큰 것(여러 행)은 안 담긴다고 생각하세요."},"1775":{"k":["FROM 절 서브쿼리 = **인라인 뷰(동적 뷰)**","SELECT 절 서브쿼리 = **스칼라 서브쿼리** (조인으로 바꿀 수 있음)","EXISTS는 '있느냐'만 확인 → 이미 걸러진 결과에 조건을 반복할 필요 없음"],"w":["EXISTS 안은 다중 행 연관, SELECT 절은 단일 행 연관, FROM 절은 인라인 뷰. 셋 다 쓰였음","스칼라 서브쿼리는 결과가 같도록 OUTER JOIN 등으로 바꿀 수 있음. 맞음","","인라인 뷰는 동적 뷰라고도 하며 테이블이 올 수 있는 자리에 씀. 맞음"],"t":"'조건을 추가해야 원하는 결과가 나온다'는 보기는 실제로 조건을 넣었을 때와 뺐을 때 결과가 달라지는지 확인해 보세요. 대개 차이가 없습니다."},"1776":{"k":["'항목별 **최종** 회차의 결과' = 연관 서브쿼리로 그 항목의 MAX(회차)를 구해 같은 행을 선택","컬럼별로 MAX를 따로 구하면 **서로 다른 행의 값**이 섞임"],"w":["평가결과 전체의 최대 회차 하나만 기준이라, 상품·항목마다 다른 최종 회차를 반영하지 못함","","회차·등급·일자를 각각 MAX로 구해 '마지막 회차의 등급'이 아니라 '가장 큰 등급'이 나올 수 있음","③과 같은 문제. 컬럼마다 MAX를 따로 구해 한 행의 값이 아님"],"t":"'최신 행 통째로'를 가져올 땐 MAX를 컬럼마다 쓰면 안 됩니다. MAX로 키를 찾은 뒤 그 키로 행을 다시 찾으세요."},"1777":{"k":["뷰: **정의만 저장**, 실행 시 재작성","장점: **독립성**(테이블이 바뀌어도 뷰만 수정) · 편리성 · 보안성","Materialized View처럼 데이터를 저장하는 뷰를 지원하는 DBMS도 있음"],"w":["뷰는 SQL 정의만 저장하고 실행할 때 원래 테이블에 대한 질의로 바꿔 수행. 맞음","","민감한 컬럼을 빼고 보여 주는 식으로 보안에 활용. 맞음","Oracle의 Materialized View처럼 실제 데이터를 저장하는 뷰도 있음. 맞음"],"t":"뷰의 장점 세 가지(독립성·편리성·보안성)를 거꾸로 서술한 보기를 찾으세요. '응용 프로그램을 바꿔야 한다'는 독립성을 뒤집은 문장입니다."},"1778":{"k":["뷰를 조회하면 **뷰 조건 AND 조회 조건**이 함께 적용","C1 = 'B' OR C1 IS NULL, 그리고 C2 >= 200 AND C1 = 'B' → ('B', 200) 한 행"],"w":["두 조건을 모두 만족하는 행이 있음","","C2 >= 200 조건을 빼고 'B' 행을 더한 값","C1 조건을 무시하고 C2 >= 200인 행을 모두 더한 값"],"t":"뷰 문제는 뷰 정의 조건과 바깥 조건을 AND로 이어 붙인 쿼리 하나로 생각하면 됩니다."},"1779":{"k":["ROW_NUMBER로 부서별 연봉 2등만 선택","SUM … ORDER BY 사원ID ROWS ~ CURRENT ROW = 부서별 **누적합**","ROWS CURRENT ROW = **자기 행만** → MAX도 자기 값"],"w":["COL3를 전체 최댓값(4500)으로 계산한 결과. ROWS CURRENT ROW라 자기 행만 봄","","COL2를 부서 전체 합으로 본 결과. ORDER BY 사원ID가 있어 누적합","COL2를 부서 전체 합으로 본 결과"],"t":"윈도우 문제는 OVER 안을 따로 해석하세요. ORDER BY가 있으면 누적, 범위가 CURRENT ROW뿐이면 자기 자신입니다."},"1780":{"k":["계층 소계(지역 → 월 → 전체) = **ROLLUP**","GROUPING(컬럼) = 소계로 생긴 NULL이면 **1**","지역ID로 묶었으면 지역명은 MIN(지역명)으로"],"w":["GROUPING = 0일 때 '지역전체'를 붙여 일반 행에 라벨이 잘못 붙음","","CUBE는 월별 전체 소계(지역 NULL, 월 있음)까지 만들어 행이 더 많음","GROUPING SETS는 지역별·월별 합계를 따로 만들 뿐 (지역, 월) 상세 행과 총계가 없음"],"t":"결과표에 소계가 '지역 안에서 월'로 계층적으로만 붙어 있으면 ROLLUP, 양쪽 방향으로 다 있으면 CUBE입니다."},"1781":{"k":["`>=` 같은 **단일 행 연산자**에 여러 행 서브쿼리 → ORA-01427 오류","'모두보다' = **ALL**, '하나라도' = **ANY**"],"w":["","서브쿼리가 부서별 MAX를 여러 행 돌려줘 실행 자체가 오류","'전부와 크거나 같은'은 >= ALL이어야 함. ANY로 쓰면 '하나라도'","'하나보다 크거나 같은'은 >= ANY여야 함. ALL로 쓰면 '전부'"],"t":"GROUP BY가 있는 서브쿼리는 거의 항상 여러 행을 돌려줍니다. 앞의 연산자가 단일 행용이면 바로 오류."},"1782":{"k":["ROLLUP(A, B) = (A,B) + A 소계 + **총계**","CUBE는 B 소계도 추가, GROUPING SETS·A, ROLLUP(B)는 총계 없음"],"w":["","CUBE면 JOB별 소계(DNAME이 NULL인 행)까지 나옴","GROUPING SETS((DNAME, JOB), DNAME)에는 전체 합계 행이 없음","DNAME, ROLLUP(JOB)은 DNAME이 항상 있어 전체 합계 행이 없음"],"t":"결과 맨 마지막 줄 (NULL, NULL, 총계)이 있으면 ROLLUP 또는 CUBE, 없으면 둘 다 아닙니다. 그다음 중간 소계 방향을 보세요."},"1783":{"k":["CUBE(A, B) = (A,B) + A 소계 + B 소계 + 총계 (**모든 조합**)","같은 그룹을 중복 지정하면 같은 행이 여러 번 나옴"],"w":["CUBE 안에서 (설비ID, 에너지코드) 조합을 또 넣어 같은 그룹이 중복 생성됨","","설비ID별 소계만 있고 에너지코드별 소계와 총계가 빠짐","총계(()) 행이 빠짐"],"t":"결과표에 '앞 컬럼 NULL'인 소계와 '뒤 컬럼 NULL'인 소계가 둘 다 있고 총계도 있으면 CUBE입니다."},"1784":{"k":["ROLLUP((A, B)): 괄호로 묶은 (A, B)를 **한 단위**로 → (A,B) + 총계만","ROLLUP(A, B)·ROLLUP((A),(B)) = (A,B) + A + 총계"],"w":["JOB별 소계 행까지 생김","","ROLLUP((JOB),(DEPTNO))는 ROLLUP(JOB, DEPTNO)와 같아 JOB 소계가 생김","JOB별 소계가 생기고 총계는 없음"],"t":"ROLLUP 안의 괄호는 '이건 쪼개지 마'라는 뜻입니다. 괄호 덩어리 개수 + 1이 그룹 수준 개수예요."},"1785":{"k":["GROUPING SETS((A, B)) = 그룹 하나만 지정 = **GROUP BY A, B**와 같음","소계·총계 없음"],"w":["GROUPING SETS(월, 상품ID)처럼 각각 따로 묶은 결과","","GROUPING SETS(월, 상품ID, ())처럼 총계까지 넣은 결과","GROUPING SETS((월, 상품ID), 월)처럼 월 소계를 넣은 결과"],"t":"GROUPING SETS 안의 괄호 개수를 세세요. 바깥 괄호 안에 묶음이 하나뿐이면 그냥 일반 GROUP BY입니다."},"1786":{"k":["윈도우 함수는 **행 수를 줄이지 않음** (행마다 값을 붙임)","PARTITION BY ≈ GROUP BY처럼 나누지만 결과는 그대로","적용 범위는 파티션 안"],"w":["데이터를 나눈다는 점에서 PARTITION BY와 GROUP BY는 의미상 비슷. 맞음","PARTITION BY가 없으면 전체가 하나의 파티션. 맞음","","윈도우 범위는 파티션 경계를 넘지 않음. 맞음"],"t":"'건수가 줄어든다'는 GROUP BY 이야기입니다. 윈도우 함수 설명에 나오면 오답."},"1787":{"k":["**RANK**: 동점 같은 순위, 다음 순위 건너뜀 (1, 1, 3)","DENSE_RANK는 안 건너뜀, ROW_NUMBER는 동점 없음"],"w":["","ROW_NUMBER 결과. 동점에도 다른 번호를 줌","DENSE_RANK 결과. 동점 뒤 순위를 건너뛰지 않음","오름차순으로 매긴 결과. DESC라 큰 값이 1위"],"t":"순위 함수 구분은 동점 다음 숫자만 보면 됩니다. 1,1,3 RANK / 1,1,2 DENSE_RANK / 1,2,3 ROW_NUMBER."},"1788":{"k":["결과 순위가 1, 2, 2, **3** → 동점 뒤에도 이어짐 = **DENSE_RANK**"],"w":["ROWNUM은 윈도우 함수가 아니라 OVER와 함께 쓸 수 없음","ROW_NUMBER면 FORD와 SCOTT가 2, 3처럼 서로 다른 번호","RANK면 공동 2위 다음이 4위가 됨",""],"t":"결과표에서 동점 바로 다음 행의 순위 숫자 하나만 확인하세요."},"1789":{"k":["`ROW_NUMBER() OVER (PARTITION BY 그룹 ORDER BY 값 DESC)` + `RNUM = 1` = **그룹별 최고 1건**","윈도우 함수는 인라인 뷰로 감싼 뒤 WHERE로 거름"],"w":["필터를 적용하지 않은 전체 결과","파티션 없이 전체 1등만 뽑은 결과","","ORDER BY를 오름차순으로 본 결과(그룹별 최저)"],"t":"그룹별 Top-1 패턴은 시험에 아주 자주 나옵니다. PARTITION BY가 '그룹', ORDER BY 방향이 '최고/최저'를 정합니다."},"1790":{"k":["GROUP BY 결과 위에 윈도우 함수 사용 **가능** (윈도우는 GROUP BY 뒤에 계산)","윈도우 ORDER BY에 집계함수 사용 가능","RANGE ±10000 = 값 기준 범위 안의 **행(그룹) 개수**"],"w":["GROUP BY와 윈도우 함수는 함께 쓸 수 있음. 윈도우 함수는 그룹화된 결과에 적용","윈도우 ORDER BY에 AVG 같은 집계함수를 쓸 수 있음","","비교 대상은 개별 상품이 아니라 GROUP BY로 만든 상품분류코드별 평균 행"],"t":"윈도우 함수가 GROUP BY와 같이 있으면 '묶인 결과 행' 위에서 계산된다고 보세요. 세는 대상도 묶인 행입니다."},"1791":{"k":["`MAX(…) OVER (PARTITION BY 부서)` = 행마다 **부서 최고값**을 붙임","연봉 = 부서 최고연봉인 행만 남기면 부서별 최고 연봉자"],"w":["","부서별 최저 연봉자. MAX가 아니라 MIN이어야 나오는 결과","100번 부서 최고(002)와… 결과에서 빠진 부서가 있음. 세 부서 모두 최고 연봉자가 있음","200번 부서만 나올 이유가 없음"],"t":"'그룹별 최대인 행'은 MAX OVER(PARTITION BY)를 붙인 뒤 원래 값과 같은 행을 고르는 패턴으로 기억하세요."},"1792":{"k":["**LAG**: 이전 행 값 (첫 행 NULL)","**LEAD**: 다음 행 값 (마지막 행 NULL)"],"w":["LEAD는 다음 행 값이라 첫 행에 값이 있고 마지막 행이 NULL","ROW_NUMBER는 순번을 매기는 함수. 인자를 받지 않음","RANK는 순위 함수",""],"t":"결과표에서 NULL이 첫 행에 있으면 LAG, 마지막 행에 있으면 LEAD입니다."},"1793":{"k":["객체 권한 + **WITH GRANT OPTION** → 회수하면 그 사용자가 남에게 준 권한도 **연쇄 회수**","시스템 권한 + WITH ADMIN OPTION → 연쇄 회수 없음","PUBLIC = 모든 사용자"],"w":["WITH GRANT OPTION으로 받으면 자기가 받은 권한을 다른 사용자에게 줄 수 있음. 맞음","GRANT … TO PUBLIC으로 모든 사용자에게 줄 수 있음. 맞음","","권한을 부여한 사용자가 REVOKE로 회수할 수 있음. 맞음"],"t":"GRANT OPTION은 '연쇄', ADMIN OPTION은 '연쇄 없음'. G-연, A-없 으로 짝지어 외우세요."},"1794":{"k":["권한 부여: `GRANT 권한 ON 객체 TO 사용자`","WHERE로 행을 찾는 UPDATE에는 **SELECT + UPDATE** 권한 필요"],"w":["ON 객체가 빠져 어느 테이블 권한인지 없음. 문법 오류","REVOKE는 권한 회수 명령","DENY는 SQL Server에서 권한을 '거부'하는 명령. 부여가 아님",""],"t":"GRANT는 ON(무엇을) + TO(누구에게), REVOKE는 ON + FROM. 전치사 짝만 맞는지 봐도 보기 대부분이 걸러집니다."},"1795":{"k":["**CASCADE**: 연관 객체까지 함께 삭제","**RESTRICT**: 비어 있을(참조가 없을) 때만 삭제"],"w":["NULL은 DROP 옵션이 아님","NOT NULL은 컬럼 제약조건이지 DROP 옵션이 아님","","RESTRICT는 스키마가 비어 있을 때만 삭제되므로 연관 객체까지 지우지 않음"],"t":"'연관된 것까지 모두' = CASCADE. ON DELETE CASCADE, DROP … CASCADE CONSTRAINTS에서도 같은 뜻입니다."},"1796":{"k":["`REVOKE … CASCADE` = 받은 사람이 다시 준 권한까지 회수","회수 후 남은 권한만 실행 가능"],"w":["","INSERT 권한은 CASCADE로 Kim과 Park 모두 회수됨","DELETE 권한도 CASCADE로 Park까지 회수됨","Kim의 INSERT 권한도 회수됨"],"t":"권한 문제는 사람별로 '가진 권한' 표를 만들고 REVOKE가 나올 때마다 지워 가면 정확합니다."},"1797":{"k":["CUBE(A, B) = GROUPING SETS((A,B), (A), (B), **()**)","ROLLUP(A, B) = GROUPING SETS((A,B), (A), ())"],"w":["ROLLUP은 col1별(뒤 컬럼) 소계가 없음","","keyb별, col1별만 있고 (keyb, col1) 상세와 총계가 없음","세 덩어리를 UNION ALL했지만 총계(()) 행이 빠짐"],"t":"CUBE를 다른 형태로 바꾼 보기는 '그룹 4종(둘 다, 앞, 뒤, 전체)'이 다 있는지 체크리스트로 확인하세요."},"1798":{"k":["**INTERSECT** = 교집합, 중복 행은 하나로"],"w":["중복 제거하는 합집합은 UNION","중복을 남기는 합집합은 UNION ALL","","차집합은 MINUS(Oracle) / EXCEPT(SQL Server)"],"t":"집합 연산자 설명은 '합/교/차' + '중복 처리' 두 가지만 맞추면 됩니다."},"1799":{"k":["`LAG(컬럼, n)`: **n칸 앞** 행 값, n 생략 시 1","PARTITION BY 안에서만 앞 행을 봄 (파티션 첫 행들은 NULL)"],"w":["0칸이면 자기 자신 값이 나옴","1칸이면 JONES는 바로 앞 CLARK(2450)가 나와야 함","","4칸 앞이면 MANAGER 파티션(3명)에서는 전부 NULL"],"t":"결과표에서 값이 처음 나오는 행이 파티션의 몇 번째인지 세면 n이 나옵니다. JONES가 3번째에서 처음 값 → n = 2."},"1800":{"k":["RANK: 동점 3명 공동 4위 → 다음은 **7위** (건너뜀)","DENSE_RANK면 다음이 5위"],"w":["DENSE_RANK면 300 다음 400이 5위","","ROW_NUMBER면 1~8로 동점이 없음","PERCENT_RANK는 0~1 사이 비율값"],"t":"동점 인원만큼 다음 순위가 밀렸는지(1,1,3) 바로 이어지는지(1,1,2)만 보세요."},"1801":{"k":["PK 지정: 컬럼 정의 안 `CONSTRAINT 이름 PRIMARY KEY (컬럼)` 또는 `ALTER TABLE … ADD CONSTRAINT 이름 PRIMARY KEY (컬럼)`","모델의 NOT NULL(* 필수)을 그대로 옮겨야 함"],"w":["`ADD PRIMARY KEY 이름 ON (컬럼)`은 없는 문법. ADD CONSTRAINT 이름 PRIMARY KEY (컬럼)","PK 지정은 맞지만 PROD_NM, REG_DT의 NOT NULL이 빠져 모델과 다름","CREATE TABLE 괄호 안에는 ADD를 쓰지 않음. 문법 오류",""],"t":"DDL 보기는 ① 키워드 순서(CONSTRAINT 이름 PRIMARY KEY) ② NOT NULL 누락 ③ ADD 위치 세 가지만 보면 됩니다."},"1802":{"k":["SQL Server: `ALTER TABLE … ALTER COLUMN 컬럼 타입 [NOT NULL]` **한 번에 하나**, 괄호 없이","NOT NULL을 다시 안 쓰면 **NULL 허용으로 바뀜**","Oracle은 MODIFY (괄호로 여러 개 가능)"],"w":["SQL Server는 ALTER COLUMN에 여러 컬럼을 괄호로 묶을 수 없음","괄호로 여러 컬럼을 묶어 문법 오류","분류명에 NOT NULL을 다시 안 써서 NULL 허용으로 바뀜",""],"t":"SQL Server ALTER COLUMN은 '한 줄에 한 컬럼, 제약은 다시 쓰기'. Oracle MODIFY와 구분하세요."},"1803":{"k":["**고립성(Isolation)**: 실행 중 트랜잭션이 다른 트랜잭션의 영향을 받지 않아야 함","커밋 전 값을 다른 트랜잭션이 덮어씀 → 갱신 손실"],"w":["원자성은 '전부 아니면 전무' 문제. 여기선 각 트랜잭션이 끝까지 수행됨","일관성은 무결성 규칙 위배 문제","","영속성(지속성)은 커밋한 결과가 장애에도 남는지의 문제"],"t":"시간표에 TX1, TX2가 번갈아 같은 데이터를 건드리면 거의 고립성 문제입니다."},"1804":{"k":["`ON DELETE CASCADE`: 부모가 지워지면 자식 행도 삭제","`ON DELETE SET NULL`: 부모가 지워지면 자식 FK를 NULL로","연쇄 효과는 단계별로 따라감 (T → S → R)"],"w":["S의 B = 2 행도 C = 1을 참조하므로 같이 삭제되어 R의 (2, 2)도 NULL이 됨","","R은 SET NULL이라 행이 삭제되지 않고 B만 NULL이 됨","R의 B는 NULL로 바뀌어야 함"],"t":"참조 옵션 문제는 화살표를 그려 부모에서 자식 쪽으로 한 단계씩 '삭제/NULL'을 적용하세요."},"1805":{"k":["SQL Server: `SAVE TRANSACTION 이름`, `ROLLBACK TRANSACTION 이름`","저장점 이후 작업만 취소, 이전 작업은 커밋 때 반영"],"w":["sp2 이후 삭제까지 반영되면 0건. 2건이 남는 경우는 없음","keya = 2 외에 한 건을 더 지운 셈","","sp1까지 롤백해야 5건"],"t":"Oracle은 SAVEPOINT / ROLLBACK TO, SQL Server는 SAVE TRANSACTION / ROLLBACK TRANSACTION. 문법만 다르고 동작은 같습니다."},"1806":{"k":["SELECT 결과 중복 제거 = **DISTINCT**","UNIQUE는 제약조건, ORDER BY는 정렬"],"w":["UNIQUE는 컬럼 값 중복을 막는 제약조건 키워드","SORT는 SQL 키워드가 아님","ORDER BY는 정렬만 하고 중복을 없애지 않음",""],"t":"'조회 결과'의 중복 = DISTINCT, '저장 값'의 중복 금지 = UNIQUE."},"1807":{"k":["테이블명: **단수형** 권고, 예약어 불가, 문자로 시작","한 테이블 안 컬럼명 중복 불가","컬럼마다 **데이터 타입 필수**"],"w":["복수형이 아니라 단수형을 권고","같은 테이블 안에서 칼럼명은 중복될 수 없음","","SELECT, TABLE 같은 예약어는 이름으로 쓸 수 없음"],"t":"테이블·컬럼 이름 규칙은 엔터티 명명 규칙(단수형, 유일)과 같은 방향입니다."},"1808":{"k":["MERGE: ON 일치 → UPDATE(+ WHERE) → 그 뒤 **DELETE WHERE**는 **UPDATE된 행**만 대상","불일치 → INSERT(+ WHERE)"],"w":["ADAMS INSERT(CLERK 조건 충족)를 빠뜨린 결과","","DELETE WHERE를 무시해 SMITH가 남았다고 본 결과","INSERT의 CLERK 조건을 무시해 SCOTT·ADAMS·FORD가 모두 들어간 경우"],"t":"MERGE 문제는 원본 행마다 '일치? → UPDATE 조건? → DELETE 조건?' / '불일치? → INSERT 조건?'을 표로 따라가세요. DELETE는 UPDATE된 행에만 걸립니다."},"1809":{"k":["COUNT(*) = 전체 행 수, COUNT(컬럼) = 그 컬럼 NULL 아닌 행 수","PK 컬럼은 NULL이 없으므로 COUNT(PK) = COUNT(*)"],"w":["COUNT(학번)은 학번 기준이라 장학금 NULL과 무관","PK라 NULL이 없어 항상 같음","","학번은 PK라 NULL이 들어갈 수 없음"],"t":"COUNT(컬럼)이 COUNT(*)와 달라질 수 있는지는 '그 컬럼에 NULL이 들어갈 수 있나?' 하나로 판단합니다."},"1810":{"k":["FK: 생성 시 또는 나중에 설정, 한 테이블에 여러 개 가능","FK 값은 **NULL 가능**(선택 관계), 있으면 부모에 존재해야 함(참조 무결성)"],"w":["CREATE TABLE 시 REFERENCES로 설정 가능. 맞음","","한 테이블이 여러 테이블을 참조할 수 있어 여러 개 생성 가능. 맞음","FK는 참조 무결성 제약을 받음. 맞음"],"t":"PK = NULL 불가·중복 불가, FK = NULL 가능·중복 가능. 둘을 대비해서 외우세요."},"1811":{"k":["**후보키**: 유일성 + 최소성을 만족하는 키 (NOT NULL + UNIQUE)","후보키 중 PK로 뽑히지 않은 것 = **대체키**"],"w":["PK는 SalesRepNo로 따로 지정됨","다른 테이블을 참조하는 제약이 없어 외래키 아님","","대리키는 업무 값이 아닌 인위적으로 만든 키(일련번호). RepName은 업무 값"],"t":"UNIQUE + NOT NULL인데 PK가 아니면 '후보키(대체키)'로 바로 연결하세요."},"1812":{"k":["컬럼 삭제: `ALTER TABLE 테이블 DROP COLUMN 컬럼`","컬럼 수정: Oracle MODIFY / SQL Server ALTER COLUMN"],"w":["","REMOVE COLUMN이라는 문법은 없음","MODIFY TABLE이라는 문법은 없음. 테이블 변경은 ALTER TABLE","둘 다 틀림"],"t":"테이블 구조 변경은 항상 ALTER TABLE로 시작합니다. 그 뒤에 ADD / MODIFY / DROP COLUMN / RENAME COLUMN."},"1813":{"k":["DISTINCT는 **SELECT한 컬럼 조합 전체**가 같을 때만 중복","(1, AAAA), (1, BBBB) → 2행"],"w":["DISTINCT 전 원본 4건을 센 값","","COL1 값 종류(1개)만 보고 센 값. DISTINCT는 (COL1, COL2) 조합 기준","원본 4건을 그대로 센 값"],"t":"DISTINCT 뒤에 컬럼이 여러 개면 '행 전체'를 비교한다고 생각하세요. 한 컬럼만 같아서는 중복이 아닙니다."},"1814":{"k":["Oracle 주요 타입: **CHAR · VARCHAR2 · NUMBER · DATE**","TEXT는 SQL Server·MySQL 쪽 타입"],"w":["","CHAR는 Oracle 고정 길이 문자 타입","VARCHAR2는 Oracle 가변 길이 문자 타입","NUMBER는 Oracle 숫자 타입"],"t":"Oracle 문자 타입은 이름에 CHAR가 들어갑니다(CHAR, VARCHAR2, CLOB). TEXT가 보이면 Oracle이 아니에요."},"1815":{"k":["입력(Insert) 참조동작: Automatic · Set Null · Set Default · **Dependent**(부모 PK가 있을 때만 입력)","삭제(Delete) 참조동작: Cascade · Set Null · Set Default · Restrict"],"w":["CASCADE는 부모 삭제·수정 시 자식에도 같이 적용하는 삭제 쪽 동작","RESTRICT도 삭제 쪽 동작. 자식이 있으면 부모 삭제를 막음","AUTOMATIC은 부모 PK가 없으면 부모를 먼저 만들어 주고 자식을 입력",""],"t":"'입력을 허용하지 않는다(부모가 있어야 의존해서 들어감)' = Dependent. 이름 그대로 '의존'입니다."},"1816":{"k":["컬럼 목록을 생략한 INSERT는 **모든 컬럼 값을 순서대로**","NOT NULL 컬럼은 반드시 값 필요","길이 초과(VARCHAR2(1)에 'AB')는 오류"],"w":["(가) 컬럼 생략 시 3개 값을 다 줘야 하는데 2개뿐. (나) VARCHAR2(1)에 'AB'는 길이 초과","(다) NOT NULL인 AMT를 넣지 않아 오류","(다)가 오류",""],"t":"INSERT 오류는 세 가지 체크: 값 개수, NOT NULL 누락, 길이·타입 초과. 보기마다 이 셋만 확인하세요."},"1817":{"k":["INSERT에서 빠진 컬럼은 DEFAULT, 없으면 **NULL** → NOT NULL 컬럼이면 오류","숫자 → 문자 컬럼은 자동 변환되어 들어감"],"w":["숫자 1은 VARCHAR2로 자동 변환되고 모든 컬럼에 값이 들어감. 정상","","존재하는 행의 USE_YN만 바꾸는 정상 UPDATE","200이 VARCHAR2로 자동 변환되어 정상 UPDATE"],"t":"컬럼 목록을 적은 INSERT는 목록에 '없는' 컬럼부터 보세요. 그중 NOT NULL이면서 DEFAULT 없는 게 있으면 오류입니다."},"1818":{"k":["DATE 컬럼에 **숫자**는 바로 넣을 수 없음 (오류)","문자열은 NLS 날짜 형식과 맞으면 자동 변환","날짜 연산 SYSDATE - 1 가능"],"w":["SYSDATE로 날짜를 넣은 정상 INSERT","문자 '20190301'은 날짜 형식이 맞으면 묵시적으로 DATE 변환","SYSDATE - 1은 어제 날짜로 정상",""],"t":"묵시적 변환은 문자 ↔ 숫자, 문자 ↔ 날짜는 되지만 숫자 → 날짜는 안 됩니다."},"1819":{"k":["산술 우선순위: **() → *, / → +, −** (수학과 같음)"],"w":["괄호가 가장 먼저","덧셈·뺄셈이 곱셈·나눗셈보다 먼저일 수 없음","","+, −가 *, / 보다 먼저일 수 없음"],"t":"산술은 학교 수학 순서 그대로입니다. 헷갈리는 건 산술이 아니라 NOT·AND·OR 쪽이에요."},"1820":{"k":["FK는 **자식 테이블**(참조하는 쪽)에 정의","`ON DELETE CASCADE`: 부모 삭제 시 자식도 삭제"],"w":["RESTRICT는 자식이 있으면 부모 삭제를 막음. 같이 삭제가 아님","FK는 Department가 아니라 자식인 Employee에 걸어야 함","","방향도 반대이고 RESTRICT라 삭제도 막힘"],"t":"FOREIGN KEY는 '내가 남을 참조한다'는 선언이라 항상 자식 테이블 CREATE 문에 들어갑니다."},"1821":{"k":["DELETE: 행 삭제, 구조 유지, 롤백 가능(사용자 COMMIT)","TRUNCATE: 전체 행 삭제, 구조 유지, UNDO 없음(빠름), 자동 커밋","DROP: **테이블 정의까지** 삭제, 자동 커밋"],"w":["","DROP은 테이블 정의 삭제, TRUNCATE는 처음 만든 상태로 초기화. 맞음","TRUNCATE는 UNDO를 만들지 않아 DELETE보다 빠름. 맞음","DROP·TRUNCATE는 DDL이라 자동 커밋, DELETE는 사용자가 COMMIT. 맞음"],"t":"세 명령 비교는 '지운 뒤 테이블이 남아 있나?'로 먼저 나누세요. DELETE·TRUNCATE는 남고 DROP만 사라집니다."},"1822":{"k":["지속성 = **성공적으로 완료(COMMIT)된** 결과가 영구 보존","취소된 트랜잭션은 반영되지 않음 (원자성)"],"w":["모두 실행되거나 전혀 실행되지 않음. 원자성 정의 맞음","실행 전후로 DB가 일관된 상태 유지. 일관성 정의 맞음","다른 트랜잭션의 영향을 받지 않음. 고립성 정의 맞음",""],"t":"ACID 정의 문제는 각 성질의 '조건'을 확인하세요. 지속성은 '커밋된' 결과에만 해당합니다."},"1823":{"k":["**Oracle**: DDL 실행 시 직전 DML까지 **자동 커밋**, DDL 자체도 확정","**SQL Server**: DDL도 트랜잭션 안에 포함 → ROLLBACK으로 함께 취소","(AUTO COMMIT FALSE 조건)"],"w":["Oracle은 CREATE TABLE 실행 시 묵시적 COMMIT이 일어나 UPDATE가 확정됨. 맞음","SQL Server는 DDL로 커밋되지 않아 ROLLBACK이 UPDATE를 취소함. 맞음","","SQL Server는 CREATE TABLE도 트랜잭션에 포함돼 함께 롤백. 맞음"],"t":"Oracle에서 DDL은 '커밋 버튼'과 같습니다. DDL 앞뒤로 무엇이 확정되는지만 따지면 됩니다."},"1824":{"k":["**트랜잭션** = DB의 논리적 연산(작업) 단위","뷰 = 가상 테이블, 프로시저 = 저장된 SQL 블록, 트리거 = 이벤트 시 자동 실행"],"w":["뷰는 SELECT를 저장해 둔 가상 테이블","","프로시저는 이름을 붙여 저장한 SQL 처리 블록","트리거는 INSERT·UPDATE·DELETE 같은 이벤트에 자동으로 실행되는 블록"],"t":"'논리적 작업 단위', '연산 단위'라는 말은 트랜잭션의 정의 문구입니다."},"1825":{"k":["SQL Server: 이름 없는 **ROLLBACK**은 중첩된 BEGIN TRAN까지 **커밋 안 된 작업 전부** 취소","이미 COMMIT한 작업은 그대로"],"w":["모든 행이 바뀌거나 삭제된 경우는 없음","002 삭제는 남고 UPDATE만 롤백됐다고 본 값. ROLLBACK은 바깥 트랜잭션까지 전부 취소","","ROLLBACK을 무시하고 UPDATE까지 반영한 값"],"t":"SQL Server의 ROLLBACK(이름 없음)은 가장 바깥 트랜잭션까지 한 번에 되돌립니다. 중첩 BEGIN이 몇 개든 상관없어요."},"1826":{"k":["`ROLLBACK TRANSACTION SP2` = SP2 **이후** 작업만 취소","SP2 이전 작업은 COMMIT 때 확정"],"w":["SP1로 롤백해야 원래 값 TV가 됨","","SP2 이후 '평면-TV' 변경은 취소됨","SAVE TRANSACTION은 SQL Server의 정상 문법이라 오류 아님"],"t":"저장점 문제는 '롤백 지점 바로 앞까지의 상태'가 최종 답입니다."},"1827":{"k":["**TOP(n) WITH TIES**: n번째와 같은 값까지 포함 (ORDER BY 필수)","Oracle은 FETCH FIRST n ROWS WITH TIES","ROWNUM은 정렬 전에 붙음"],"w":["WITH TIES가 없어 공동 3위(D팀, F팀) 중 한 팀만 나옴","ORDER BY가 없어 승리건수와 상관없는 아무 3건","ROWNUM이 정렬 전에 붙어 임의의 3건을 뽑은 뒤 정렬",""],"t":"'동점까지 함께'라는 말이 나오면 WITH TIES를 찾으세요. 그리고 WITH TIES 뒤에는 ORDER BY가 꼭 있어야 합니다."},"1828":{"k":["UPDATE … SET = (서브쿼리)에 **WHERE가 없으면 모든 행** 대상 → 짝 없는 행은 NULL로 바뀜","대상 제한: `WHERE 부서코드 IN (SELECT … FROM 부서임시)`","부서별 최신 = 연관 서브쿼리로 MAX(변경일자)"],"w":["WHERE가 없어 A007·A008 외 모든 부서 담당자가 NULL이 되고, 담당자 자리에 부서코드를 넣는 것도 틀림","WHERE EXISTS가 부서 테이블 자신을 보니 모든 행이 대상 → 나머지 부서 NULL, 부서코드를 넣는 문제도 그대로","","WHERE가 없어 나머지 부서가 NULL이 되고, 날짜를 고정값으로 박아 '가장 최근' 조건도 못 지킴"],"t":"서브쿼리로 값을 바꾸는 UPDATE는 항상 'WHERE로 대상 행을 제한했나'부터 보세요. 없으면 짝 없는 행이 NULL로 덮입니다."},"1":{"k":["모델링 3대 특징: **추상화 · 단순화 · 명확화** (단추명)","구체화는 모델링 단계가 내려갈수록(개념→물리) 높아지는 '수준'이지 특징이 아님"],"w":["단순화는 복잡한 현실을 제한된 표기법으로 쉽게 표현하는 것. 3대 특징 중 하나","추상화는 현실의 공통 성질만 뽑아 일정한 형식으로 표현하는 것. 3대 특징","명확화는 애매함 없이 한 가지 의미로 읽히게 하는 것. 3대 특징",""],"t":"특징 3개는 '단추명'. 보기에 '구체화', '정규화', '일반화'처럼 비슷한 '~화'가 섞여 나오니 세 단어를 정확히 외우세요."},"2":{"k":["유의사항: **중복 · 비유연성 · 비일관성**을 피하기","조회 성능을 위해 일부러 중복을 두는 건 반정규화(물리 단계)이지 모델링 원칙이 아님"],"w":["같은 데이터를 여러 곳에 저장하지 않는 것은 '중복' 유의사항의 올바른 대응","데이터 정의와 프로세스를 분리하는 것은 '비유연성' 유의사항의 대응","연관 관계를 명확히 정의하는 것은 '비일관성' 유의사항의 대응",""],"t":"'성능을 위해 중복 저장'은 유의사항이 아니라 반정규화 이야기입니다. 모델링 원칙 문제에서 나오면 오답."},"3":{"k":["모델링 3관점: **데이터(What) · 프로세스(How) · 상관(Interaction)**","성능은 물리 모델링에서 고려하는 요소"],"w":["","데이터 관점은 업무에 어떤 데이터가 있는지 보는 관점. 3대 관점","프로세스 관점은 업무가 실제로 무엇을 하는지 보는 관점. 3대 관점","상관 관점은 업무 처리에 따라 데이터가 어떻게 영향받는지 보는 관점. 3대 관점"],"t":"관점 문제의 오답은 거의 항상 '성능', '사용자', '기술' 관점입니다."},"4":{"k":["상관 관점 = 프로세스가 데이터를 어떻게 **생성·조회·수정·삭제**하는지","도구: **CRUD 매트릭스**"],"w":["정규화는 논리 모델링에서 중복을 없애는 작업. 데이터 구조 쪽 일","","인덱스 설계는 물리 설계 작업","반정규화는 성능을 위한 물리 단계 작업"],"t":"상관 관점 = CRUD 매트릭스. 이 짝은 거의 그대로 시험에 나옵니다."},"18":{"k":["모델링이 중요한 이유: **파급효과 · 간결한 표현 · 데이터 품질**","모델이 SQL 성능을 자동으로 보장하지는 않음"],"w":["나중에 모델을 바꾸면 영향이 크다는 파급효과(Leverage)는 실제 이유","","복잡한 요구사항을 간결하게 표현(Conciseness)하는 것도 중요한 이유","데이터 품질(Data Quality) 확보도 중요한 이유"],"t":"중요성 3가지는 영어 단어(Leverage, Conciseness, Data Quality)로도 나옵니다. '자동으로 보장'은 언제나 의심."},"20":{"k":["모델링은 시스템 구축의 기반이면서 **업무 분석·형상화** 도구"],"w":["현실 세계를 단순화해 표현하는 게 모델링의 정의","업무를 분석하고 형상화하는 데 쓰는 것이 모델링의 용도","정보시스템 구축의 기반이 된다는 것도 맞음",""],"t":"'~만을 위해'처럼 용도를 하나로 좁히는 문장은 오답 패턴입니다."},"479":{"k":["모델링 = 현실을 **필요한 만큼** 단순화·추상화해 약속된 표기법으로 표현"],"w":["모든 정보를 그대로 옮기는 게 아니라 필요한 것만 골라 단순화함","모델링은 DBMS 설치와 무관하게 업무 분석 단계부터 함","모델링은 설계 작업이지 프로그램 코드 작성 단계가 아님",""],"t":"'모든', '빠짐없이 그대로'는 추상화·단순화와 반대되는 말입니다."},"480":{"k":["**중복**: 같은 데이터를 여러 엔터티에 저장하는 문제"],"w":["비유연성은 업무가 바뀔 때 모델이 쉽게 흔들리는 문제","비일관성은 연관 데이터를 일부만 고쳐 서로 모순되는 문제","추상화는 유의사항이 아니라 모델링의 특징",""],"t":"'여러 곳에 같은 데이터' → 중복, '업무 변화에 약함' → 비유연성, '서로 모순' → 비일관성."},"481":{"k":["**비유연성**: 업무 규칙이 바뀔 때마다 모델을 크게 고쳐야 하는 문제","대응: 데이터 정의와 프로세스를 분리"],"w":["중복은 같은 데이터를 여러 곳에 저장하는 문제","명확화는 유의사항이 아니라 모델링 특징","비일관성은 연관 데이터 간 모순 문제",""],"t":"'변화', '유연하게', '자주 변경'이 나오면 비유연성입니다."},"482":{"k":["관점은 **데이터 · 프로세스 · 상관** 세 가지뿐"],"w":["데이터 관점 = 업무가 어떤 데이터와 관련 있는지. 맞는 연결","프로세스 관점 = 업무가 실제로 하는 일. 맞는 연결","상관 관점 = 업무 처리 방법에 따라 데이터가 받는 영향. 맞는 연결",""],"t":"연결 문제도 결국 '없는 관점'을 찾는 문제입니다. 성능 관점을 바로 고르세요."},"483":{"k":["단순화 = **쉽게** / 추상화 = **핵심(공통 성질)만** / 명확화 = **애매함 제거**"],"w":["약속된 규칙으로 쉽게 표현하는 건 단순화","일정한 형식으로 핵심만 표현하는 건 추상화","중복 없이 저장하는 건 특징이 아니라 유의사항(중복)",""],"t":"세 특징을 각각 한 단어로 바꿔 두세요. 단순화-쉽게, 추상화-핵심, 명확화-한 가지 뜻."},"542":{"k":["CRUD 매트릭스: 프로세스 × 엔터티 표에 C·R·U·D를 표시","용도: 어떤 엔터티가 어떤 프로세스에서 쓰이는지 **누락 없이 검증** (상관 관점)"],"w":["CRUD 매트릭스는 실행 속도를 보여 주지 않음","정규형 단계는 함수 종속으로 판단하는 것이라 무관","","사용자 권한 체계는 DCL·보안 설계 영역"],"t":"CRUD 매트릭스에서 C가 하나도 없는 엔터티는 '누가 만드는지 모르는' 엔터티라는 뜻입니다. 검증 도구라는 점을 기억하세요."},"1061":{"k":["데이터 정의를 사용 프로세스와 **분리** → **비유연성** 감소"],"w":["중복은 같은 정보를 여러 곳에 저장하는 문제라 대응책이 다름","비정형성은 모델링 유의점 용어가 아님","비일관성은 연관 데이터 간 불일치 문제",""],"t":"'프로세스와 분리'라는 대응책이 보이면 비유연성으로 연결하세요."},"1062":{"k":["상관 관점 = 업무 처리 **방법에 따라 데이터가 받는 영향** (Interaction)"],"w":["데이터 관점은 업무가 어떤 데이터와 관련 있는지(What)","프로세스 관점은 업무가 실제로 하는 일(How)","사용자 관점은 3대 관점이 아님",""],"t":"'~에 따라 데이터가 영향을 받는다'처럼 둘의 관계를 말하면 상관 관점입니다."},"1183":{"k":["3관점: 데이터(What) · 프로세스(How) · 상관(Interaction)"],"w":["데이터 관점은 3대 관점 중 하나","프로세스 관점은 3대 관점 중 하나","","상관 관점은 3대 관점 중 하나"],"t":"관점 문제는 '성능'을 찾으면 끝입니다."},"1184":{"k":["모델은 업무가 바뀌면 **함께 바뀜**","물리 단계에서는 용량 산정·저장 구조도 정함"],"w":["단순화·추상화로 현실을 표현한다는 건 모델링 정의 그대로","현업과 소통하는 커뮤니케이션 도구라는 것도 맞음","물리 모델링 단계에서 데이터 용량 산정을 하는 것도 맞음",""],"t":"'한 번 확정되면 수정하지 않는다' 같은 고정된 표현은 모델링 문제에서 거의 오답입니다."},"1324":{"k":["업무 규칙(주문은 반드시 고객이 있다 등)은 관계·선택사양으로 **모델에 반영**","모델은 현업과의 의사소통 도구"],"w":["","업무 규칙은 관계의 필수/선택 등으로 모델에 담아야 함","모델은 현업과 개발자가 함께 보는 소통 도구","필요한 것만 골라 단순화·추상화함. 모든 데이터를 그대로 옮기지 않음"],"t":"모델링 정의 문제의 정답은 대개 '업무 규칙 반영', '의사소통 도구', '단순화·추상화' 쪽입니다."},"1412":{"k":["프로세스 관점 = **How** (업무가 실제로 하는 일)"],"w":["","데이터 관점은 What(어떤 데이터인가)","상관 관점은 Interaction(처리에 따라 데이터가 받는 영향)","기술 관점은 3대 관점이 아님"],"t":"What-데이터, How-프로세스, Interaction-상관. 영어 한 단어씩 짝지어 두세요."},"1413":{"k":["같은 정보를 여러 곳에 저장 = **중복**(원인)","그 결과 일부만 수정돼 서로 달라짐 = 비일관성(결과)"],"w":["독립성은 모델링 유의점이 아님","비유연성은 업무 변화에 모델이 흔들리는 문제","비일관성은 결과로 나타난 증상. 문제의 원인은 중복 저장",""],"t":"'원인'을 묻는지 '현상'을 묻는지 보세요. 여러 곳에 저장한 게 원인(중복), 값이 어긋나는 게 결과(비일관성)."},"1460":{"k":["명확화 = 애매함 없이 **한 가지 의미**로 해석되게"],"w":["","단순화는 제한된 표기법으로 쉽게 표현하는 것","추상화는 공통 성질로 일반화하는 것","정규화는 모델링 특징이 아니라 논리 모델링 작업"],"t":"'한 가지 의미', '정확하게', '애매함 없이' → 명확화."},"5":{"k":["모델링 단계: **개념 → 논리 → 물리** (개논물)","추상적인 것에서 구체적인 것으로"],"w":["논리 모델은 개념 모델을 구체화한 다음 단계라 맨 앞일 수 없음","가장 구체적인 물리 모델이 맨 앞에 와서 순서가 거꾸로","","물리 설계는 논리 모델(키·정규화)이 확정된 뒤에 함"],"t":"'개논물' 세 글자만 외우면 순서 문제는 끝입니다."},"6":{"k":["추상화 수준: **개념 > 논리 > 물리**","물리가 가장 구체적"],"w":["","논리 모델은 키·속성·정규화까지 들어가 개념보다 구체적","물리 모델은 가장 구체적인 단계","단계마다 추상화 수준이 다름"],"t":"추상화는 '얼마나 뭉뚱그렸나'입니다. 처음(개념)이 가장 뭉뚱그려져 있어요."},"7":{"k":["**논리** 모델링: 키·속성·관계 확정 + **정규화**","개념: 핵심 엔터티·관계 / 물리: 저장 구조·반정규화"],"w":["개념 모델링은 핵심 엔터티와 관계만 잡는 단계","","물리 모델링은 정규화 이후 성능·저장 구조를 설계하는 단계(반정규화 쪽)","구현 단계는 모델링 단계에 포함되지 않음"],"t":"정규화-논리, 반정규화-물리. 이 짝은 반드시 외워 두세요."},"8":{"k":["**물리** 모델링: 테이블·인덱스·파티션 등 DBMS 저장 구조, 성능·용량 고려"],"w":["개념 모델링은 업무 핵심 엔터티 수준의 추상적 설계","논리 모델링은 키·속성·정규화까지이고 DBMS 저장 구조는 다루지 않음","외부 스키마는 사용자 관점의 데이터 정의(뷰)",""],"t":"'DBMS', '인덱스', '파티션', '용량'이라는 단어가 보이면 물리 단계입니다."},"9":{"k":["데이터 모델 3요소: **엔터티 · 속성 · 관계**","인덱스는 물리 설계 대상"],"w":["","엔터티는 3요소 중 하나","속성은 3요소 중 하나","관계는 3요소 중 하나"],"t":"3요소는 '어떤 것(엔터티) – 그 성격(속성) – 서로의 관계'. 물리 객체(인덱스, 뷰)가 섞이면 그게 답."},"10":{"k":["ERD 순서: 엔터티 **도출** → 배치 → 관계 설정 → 관계명 → 관계차수 → **선택사양** (도배설명차선)"],"w":["첫 단계는 배치가 아니라 엔터티 도출","관계 설정은 세 번째, 관계차수는 다섯 번째 단계","","관계 설정은 마지막이 아니라 세 번째"],"t":"처음과 끝만 물으면 '도'와 '선'. 도출로 시작해서 선택사양으로 끝납니다."},"11":{"k":["도배설명차선: **도**출 → **배**치 → 관계 **설**정 → 관계**명** → 관계**차**수 → **선**택사양"],"w":["","엔터티를 도출해야 배치할 수 있으므로 도출이 먼저","관계를 설정해야 이름을 붙일 수 있고, 차수 다음이 선택사양","엔터티 배치를 마친 뒤에 관계를 설정함"],"t":"논리로 풀어도 됩니다. 뽑고(도출) → 놓고(배치) → 잇고(설정) → 이름 붙이고 → 몇 개인지 → 필수인지."},"421":{"k":["정규화 = 논리 단계, 논리 모델은 재사용성 높음","물리로 갈수록 **구체화**","ERD는 **개념** 단계에서 처음 작성"],"w":["개념 단계는 핵심 엔터티와 관계만 잡고 정규화는 하지 않음","","물리로 갈수록 추상화 수준은 낮아지고 구체적이 됨","ERD는 개념 단계부터 작성함"],"t":"단계 설명 문제는 '정규화-논리', '구체화-물리 쪽', 'ERD 시작-개념' 세 가지로 대부분 걸러집니다."},"484":{"k":["**개념적** 모델링: 전사적 관점, 핵심 엔터티·관계 도출, 추상화 수준 최고"],"w":["운영 단계는 모델링 단계가 아님","논리 모델링은 키·속성 확정과 정규화 단계","물리 모델링은 저장 구조 설계 단계",""],"t":"'전사적', '핵심 엔터티', 'EA'가 나오면 개념적 모델링입니다."},"485":{"k":["논리 모델링: 식별자 확정 · 정규화 · 재사용성 높음","인덱스·파티션 같은 저장 구조는 **물리**"],"w":["식별자(키)를 확정하는 것은 논리 모델링의 일. 맞음","정규화를 수행하는 것도 논리 모델링. 맞음","특정 DBMS에 묶이지 않아 재사용성이 높음. 맞음",""],"t":"논리 단계 설명에 DBMS 종속적인 단어(인덱스, 파티션, 저장 공간)가 섞이면 그게 오답입니다."},"486":{"k":["개념 → 논리 → 물리로 갈수록 **구체화↑ · 추상화↓**","DBMS 고려는 물리에서 가장 많고, 재사용성은 논리가 가장 높음"],"w":["추상화 수준은 개념 단계가 가장 높고 물리로 갈수록 낮아짐","물리로 갈수록 특정 DBMS 특성을 더 많이 반영함","재사용성은 DBMS에 묶이지 않는 논리 모델이 높고 물리는 낮아짐",""],"t":"물리 쪽으로 갈수록 '구체화, DBMS 종속, 재사용성↓' 세 가지가 함께 움직인다고 묶어 두세요."},"487":{"k":["도배설명차선: 도출 → 배치 → 관계 **설**정 → 관계**명** → 차수 → 선택사양"],"w":["엔터티 배치는 관계 설정보다 앞 단계","선택사양은 맨 마지막 단계","관계차수는 관계명을 붙인 다음 단계",""],"t":"'설' 다음은 '명'. 관계를 이었으면 바로 이름부터 붙인다고 기억하세요."},"488":{"k":["배치 원칙: 핵심(중심) 엔터티를 **왼쪽 위**, 관련 엔터티를 주변·오른쪽·아래로","읽는 흐름(왼→오, 위→아래)과 가독성을 고려"],"w":["배치의 목적 자체가 가독성. 무관하지 않음","이름순 배치라는 원칙은 없음","관계가 많은 핵심 엔터티는 구석이 아니라 왼쪽 위 중심에 둠",""],"t":"ERD도 글처럼 왼쪽 위에서 읽기 시작합니다. 그래서 가장 중요한 엔터티를 거기에 둡니다."},"541":{"k":["테이블스페이스·인덱스·파티션·용량 = **물리** 모델링","논리 = DBMS 비종속, 키·속성·정규화"],"w":["개념 모델링은 업무 중심이고 포괄적. 맞는 설명","논리 모델링은 특정 DBMS에 종속되지 않음. 맞는 설명","물리 모델링은 성능·저장 공간·보안을 고려. 맞는 설명",""],"t":"'테이블스페이스'는 DBMS 저장 단위라서 논리 단계 설명에 나오면 무조건 틀린 문장입니다."},"1063":{"k":["논리 모델링 대표 활동: **정규화**, 식별자 확정, 속성·관계 상세화","용량·테이블스페이스·인덱스·파티션은 물리"],"w":["저장 용량 산정은 물리 모델링 활동","테이블스페이스 설계는 물리 모델링 활동","인덱스·파티션 설계는 물리 모델링 활동",""],"t":"보기 셋이 같은 성격(물리)이고 하나만 다르면 그 하나가 답인 경우가 많습니다."},"1141":{"k":["물리 모델링: **DBMS 특성 + 성능** 고려, 테이블·인덱스·저장 구조 설계"],"w":["추상화 수준 최고·업무 중심은 개념 모델링","핵심 엔터티와 관계만 뽑는 건 개념 모델링","정규화는 논리 모델링에서 수행",""],"t":"단계별 키워드: 개념-추상화·핵심, 논리-정규화·키, 물리-DBMS·성능·저장."},"1227":{"k":["DBMS 특성·성능·저장 구조 = **물리적** 데이터 모델링"],"w":["개념적 모델링은 핵심 엔터티와 관계를 추상적으로 표현","논리적 모델링은 키·속성·관계를 정확히 표현(DBMS 비종속)","","업무 프로세스 모델링은 데이터 모델링 3단계에 속하지 않음"],"t":"'실제 구현할 수 있게'라는 표현은 물리 단계를 가리킵니다."},"12":{"k":["ANSI/SPARC 3단계: **외부 · 개념 · 내부** 스키마","논리·물리·관계 스키마는 3단계 이름이 아님"],"w":["외부 스키마는 사용자 관점 단계","","개념 스키마는 전체 통합 관점 단계","내부 스키마는 저장 장치 관점 단계"],"t":"3단계 이름 세 개(외·개·내)를 외워 두면, 그 외의 '~스키마'는 전부 오답입니다."},"13":{"k":["외부 스키마 = 사용자·응용 프로그램별 관점(뷰), **여러 개**","개념·내부 스키마는 DB당 **하나**"],"w":["","개념 스키마는 DB 전체를 통합한 구조라 하나뿐","내부 스키마는 물리 저장 구조라 하나뿐","메타 스키마는 3단계 스키마 용어가 아님"],"t":"'여러 개 존재'는 외부 스키마만 해당합니다. 사용자마다 보는 화면이 다르기 때문이에요."},"14":{"k":["개념 스키마 = 모든 사용자 관점을 **통합**한 전체 논리 구조, DB당 하나"],"w":["외부 스키마는 사용자별 관점이라 여러 개","내부 스키마는 저장 장치 관점의 물리 구조","","서브 스키마는 외부 스키마의 다른 이름"],"t":"'통합', '전체', '조직 전체', 'DBA 관점' → 개념 스키마."},"15":{"k":["내부 스키마 = 저장 장치 관점: 레코드 구조, 인덱스, 저장 위치"],"w":["외부 스키마는 사용자가 보는 관점","","개념 스키마는 전체 논리 구조로 저장 방식은 다루지 않음","사용자 스키마는 외부 스키마 쪽 개념"],"t":"'디스크', '물리적 저장', '레코드 형식', '인덱스' → 내부 스키마."},"16":{"k":["**논리적 독립성**: 개념 스키마가 바뀌어도 외부 스키마(응용)는 그대로","**물리적 독립성**: 내부 스키마가 바뀌어도 개념 스키마는 그대로"],"w":["물리적 독립성은 내부 스키마 변경이 개념 스키마에 영향을 주지 않는 성질","","외부적 독립성이라는 용어는 없음","개념적 독립성이라는 용어는 없음"],"t":"독립성은 '논리적', '물리적' 두 개뿐입니다. 바뀐 쪽이 개념이면 논리적, 내부면 물리적."},"17":{"k":["저장 장치·인덱스 변경(내부 스키마) → 응용·개념 무영향 = **물리적 독립성**"],"w":["논리적 독립성은 개념 스키마 변경으로부터 외부를 보호하는 성질","개념적 독립성이라는 용어는 없음","","외부적 독립성이라는 용어는 없음"],"t":"'저장', '디스크', '인덱스'가 바뀌는 상황이면 물리적 독립성입니다."},"19":{"k":["데이터 독립성의 목적: 한 계층의 변경이 다른 계층에 **번지지 않게** → 유지보수 비용 감소","중복 저장·속도 향상과는 무관"],"w":["사용자마다 독립적인 뷰를 주는 것은 3단계 구조의 목적","저장 구조가 바뀌어도 응용 수정이 적은 건 물리적 독립성의 목적","","변경 영향이 줄어 유지보수 비용이 줄어드는 것도 목적"],"t":"독립성 문제에서 '중복 저장', '조회 속도'가 보이면 오답입니다. 독립성은 '변경 영향 차단' 이야기예요."},"422":{"k":["외부 ↔ 개념 사상 = **논리적** 독립성","개념 ↔ 내부 사상 = **물리적** 독립성"],"w":["논리적 독립성은 외부↔개념 사이 사상이 보장","","외부적 독립성이라는 용어는 없음","개념적 독립성이라는 용어는 없음"],"t":"사상(매핑)은 경계마다 하나씩, 총 두 개입니다. 아래쪽 경계(개념-내부)가 물리적."},"489":{"k":["저장 위치·인덱스 변경 = 내부 스키마 변경 → 그래도 SQL·프로그램 무수정 = **물리적 독립성**"],"w":["논리적 독립성은 개념 스키마(테이블 구조)가 바뀌는 상황","외부적 독립성은 없는 용어","개념적 독립성은 없는 용어",""],"t":"상황 문제는 '무엇이 바뀌었나'만 찾으세요. 디스크·인덱스면 물리적."},"490":{"k":["전사 데이터 구조(엔터티·속성) 변경 = 개념 스키마 변경 → 사용자 뷰 그대로 = **논리적 독립성**"],"w":["물리적 독립성은 저장 구조가 바뀌는 상황","내부적 독립성은 없는 용어","","저장 독립성은 없는 용어"],"t":"엔터티·속성·컬럼이 추가되는 건 개념 스키마 변화입니다. 그래서 논리적 독립성."},"491":{"k":["DBA 관점 · DB 전체를 통합한 논리 구조 = **개념 스키마**"],"w":["외부 스키마는 개별 사용자 관점","서브 스키마는 외부 스키마의 다른 이름","내부 스키마는 저장 장치 관점",""],"t":"관점 주체로 외워도 됩니다. 사용자-외부, DBA(통합)-개념, 저장 장치-내부."},"492":{"k":["외부 **여러 개** · 개념 **하나** · 내부 = 물리 저장 구조","개념 스키마가 가운데서 외부와 내부를 분리 → 독립성"],"w":["외부 스키마는 사용자마다 있어 여러 개","개념 스키마는 통합 구조라 하나","","외부와 내부는 개념 스키마를 사이에 두고 분리돼 독립성이 생김"],"t":"개수 문제가 자주 나옵니다. 외부만 여러 개, 나머지는 하나."},"555":{"k":["데이터 독립성 = 한 계층 변경이 다른 계층에 주는 **영향 차단**"],"w":["여러 곳에 저장하는 것(중복)과 독립성은 무관","","SQL 문법 단순화와 무관","DBMS 종류 통일과 무관"],"t":"독립성의 정답 키워드는 '변경 영향 최소화', '유지보수 비용 감소'입니다."},"1064":{"k":["외부 = 사용자별(서브 스키마) / 개념 = **조직 전체 통합** / 내부 = 물리 저장"],"w":["","외부 스키마는 사용자별 관점이라 통합 구조가 아님","내부 스키마는 물리 저장 구조","서브 스키마는 외부 스키마의 다른 이름"],"t":"서브 스키마 = 외부 스키마. 이 동의어가 보기로 자주 섞여 나옵니다."},"1140":{"k":["컬럼 추가 = 테이블 구조 변경 = **개념 스키마** 변경","그래도 사용자 뷰·프로그램이 그대로 = **논리적 독립성**","파티션·인덱스 변경이면 내부 스키마 → 물리적 독립성"],"w":["컬럼 추가는 저장 구조가 아니라 논리 구조 변경이라 내부 스키마가 아님","변경된 건 외부가 아니라 개념 스키마. 외부는 그대로 유지됨","개념 스키마 변경으로 보장되는 건 논리적 독립성",""],"t":"독립성 문제는 '변경된 스키마'와 '보호된 스키마'를 구분하세요. 개념이 바뀌고 외부가 보호되면 논리적."},"1274":{"k":["외부 = 사용자·응용별 데이터 정의","개념 = 조직 전체 통합 구조","내부 = 물리 저장 구조와 접근 방법 (사용자 관점 아님)"],"w":["라(내부 스키마=물리 저장 구조)도 맞는 설명이라 빠지면 안 됨","다는 외부 스키마 설명을 내부에 붙인 틀린 문장","","다는 틀린 설명이라 들어가면 안 됨"],"t":"'모두 고른 것' 문제는 틀린 문장 하나(다)를 먼저 찾고, 그게 빠진 보기 중 가장 많이 담은 걸 고르세요."},"1323":{"k":["3단계 = 외부 · 개념 · 내부","'논리/물리'는 **모델링 단계** 이름"],"w":["외부 스키마는 3단계 중 하나","","내부 스키마는 3단계 중 하나","개념 스키마는 3단계 중 하나"],"t":"모델링 단계(개념·논리·물리)와 스키마 단계(외부·개념·내부)를 섞어서 내는 함정입니다. '개념'만 겹쳐요."},"1364":{"k":["테이블스페이스·인덱스·파티션 = **내부**","부서별 VIEW = **외부**","전사 통합 ERD = **개념**"],"w":["","㉠은 저장 구조라 개념이 아니라 내부, ㉢은 통합 구조라 개념","㉠과 ㉡이 뒤바뀜. 저장 설계서는 내부, VIEW는 외부","㉡ VIEW는 외부, ㉢ 통합 ERD는 개념"],"t":"VIEW는 대표적인 외부 스키마 예시입니다. 시험에 자주 나와요."},"1554":{"k":["내부 스키마 = 저장 장치에 **실제로 저장되는 물리 구조**, DB당 하나"],"w":["사용자마다 다른 관점은 외부 스키마","여러 개 존재하는 건 외부 스키마","","조직 전체 통합 관점은 개념 스키마"],"t":"세 스키마 정의 문제는 키워드 대응으로 끝납니다: 사용자-외부, 통합-개념, 저장-내부."},"21":{"k":["엔터티 6특징: 업무 필요 · 식별자 · **인스턴스 2개 이상** · 속성 2개 이상 · 업무 프로세스에서 사용 · 관계 1개 이상"],"w":["업무에서 관리할 정보여야 한다는 건 엔터티의 특징","유일한 식별자로 구분돼야 한다는 것도 특징","","다른 엔터티와 관계가 최소 하나 있어야 함 (통계성·코드성 엔터티는 예외)"],"t":"숫자가 나오는 특징은 '인스턴스 2개 이상', '속성 2개 이상', '관계 1개 이상'. 숫자를 바꿔서 함정을 냅니다."},"22":{"k":["유무형 분류: **유형 · 개념 · 사건**","발생 시점 분류: **기본 · 중심 · 행위**"],"w":["유형 엔터티는 유무형 분류(물리적 형태 있음: 사원, 상품)","개념 엔터티는 유무형 분류(형태 없음: 보험상품, 조직)","사건 엔터티는 유무형 분류(업무 중 발생: 주문, 청구)",""],"t":"분류 기준이 두 개라 섞어서 냅니다. '유개사' / '기중행'으로 묶어 두세요."},"23":{"k":["**행위** 엔터티: 2개 이상의 부모에서 발생, 자주 바뀌고 양이 많음 (주문내역, 이력)","기본 → 중심 → 행위 순으로 생겨남"],"w":["기본 엔터티는 부모 없이 독립적으로 생성됨 (사원, 상품)","중심 엔터티는 기본에서 발생해 업무의 중심이 됨 (주문, 계약)","","개념 엔터티는 유무형 분류로, 발생 시점 분류가 아님"],"t":"'이력', '내역', '변경'이 이름에 들어가면 행위 엔터티로 보면 됩니다."},"24":{"k":["**기본(키)** 엔터티: 다른 엔터티에서 주식별자를 상속받지 않고 **독립 생성** (사원, 부서, 상품)"],"w":["","중심 엔터티는 기본 엔터티로부터 발생","행위 엔터티는 두 개 이상의 부모에서 발생","사건 엔터티는 유무형 분류로, 업무 수행 중 발생하는 것"],"t":"'독립적', '자신의 고유한 주식별자'가 보이면 기본 엔터티입니다."},"25":{"k":["**중심** 엔터티: 기본 엔터티에서 발생, 업무의 중심, 행위 엔터티를 많이 만들어 냄 (주문, 계약)"],"w":["기본 엔터티는 부모 없이 독립 생성되는 엔터티","","행위 엔터티는 중심 엔터티에서 파생된 내역·이력","유형 엔터티는 유무형 분류로 물리적 형태가 있는 것"],"t":"흐름으로 외우세요. 고객·상품(기본) → 주문(중심) → 주문상세·배송이력(행위)."},"26":{"k":["**개념** 엔터티: 물리적 형태 없이 관리할 개념 정보 (보험상품, 조직, 계좌상품)","유형: 사원·물품 / 사건: 주문·청구"],"w":["사원은 손에 잡히는 실체가 있는 유형 엔터티","","주문은 업무 수행 중 발생하는 사건 엔터티","물품은 형태가 있는 유형 엔터티"],"t":"'보험상품'은 개념 엔터티 예시로 거의 고정 출제됩니다. 상품이라는 말에 속아 유형으로 고르지 마세요."},"27":{"k":["엔터티 명명: **현업 용어 · 약어 지양 · 단수 명사 · 유일한 이름 · 생성 의미대로**"],"w":["현업에서 쓰는 용어를 쓰는 건 명명 원칙","","단수 명사 사용은 명명 원칙","모든 엔터티에서 이름이 유일해야 함. 명명 원칙"],"t":"명명 원칙의 오답은 '약어 사용', '복수 명사', '물리 테이블명(TB_)' 셋 중 하나로 나옵니다."},"40":{"k":["엔터티 = **테이블**, 인스턴스 = **행**(튜플), 속성 = **컬럼**, 속성값 = 값"],"w":["","인스턴스와 속성의 대응이 바뀜. 인스턴스=행, 속성=컬럼","엔터티가 테이블이고 인스턴스가 행인데 순서가 뒤바뀜","엔터티는 테이블이지 컬럼이 아님"],"t":"인스턴스는 '한 건'이니 한 줄(행), 속성은 '항목'이니 한 칸 세로줄(컬럼)입니다."},"423":{"k":["유무형 분류: 유형(실체) · 개념(형태 없음) · **사건**(업무 중 발생: 주문, 수강, 예약)"],"w":["유형 엔터티는 물리적 형태가 있는 것 (사원, 물품)","개념 엔터티는 형태 없는 정보 (보험상품, 조직)","","기본 엔터티는 발생 시점 분류라 기준이 다름"],"t":"'특정 시점에 발생한 일'은 사건입니다. 문제의 분류 기준(유무형/발생 시점)을 먼저 확인하세요."},"493":{"k":["엔터티는 **인스턴스가 2개 이상**이어야 함","1건뿐이면 집합으로 관리할 의미가 없음"],"w":["고객은 여러 명을 관리하는 정상 엔터티","상품도 여러 건을 관리하는 정상 엔터티","주문은 계속 쌓이는 사건 엔터티",""],"t":"'단 하나', '1건뿐'이라는 말이 보이면 엔터티 특징(인스턴스 2개 이상) 위반입니다."},"494":{"k":["엔터티는 다른 엔터티와 **관계 1개 이상**","예외: 코드성·통계성·내부 필요 엔터티"],"w":["관계가 하나도 없으면 정상이라 보기 어려움","식별자가 있어도 관계 조건은 따로 지켜야 함","","속성 개수와 관계 조건은 별개"],"t":"관계 없는 엔터티는 '재검토' 대상입니다. 단 코드·통계성 엔터티는 예외라는 단서가 붙으면 맞는 문장."},"495":{"k":["사건 엔터티 = 업무 수행 중 **발생하는 일** (주문, 청구, 수강, 예약)"],"w":["상품은 형태가 있는 유형 엔터티","부서는 유형(또는 개념) 쪽으로 보는 엔터티로 사건이 아님","보험상품은 형태 없는 개념 엔터티",""],"t":"사건 엔터티 이름은 대개 동사에서 나온 명사입니다. 주문하다→주문, 청구하다→청구."},"496":{"k":["주문내역·주문상세는 두 부모(주문, 상품)에서 생기는 **행위** 엔터티","기본 엔터티는 독립 생성(고객, 상품)"],"w":["사원은 형태가 있는 유형 엔터티. 맞는 짝","조직은 형태 없는 개념 엔터티. 맞는 짝","","주문은 업무 중 발생하는 사건 엔터티. 맞는 짝"],"t":"'~내역', '~상세', '~이력'이 붙으면 행위 엔터티. 기본으로 짝지은 보기는 틀립니다."},"497":{"k":["엔터티 이름: **단수 명사**, 현업 용어, 약어·물리명 지양, 업무 행위(관리·처리) 붙이지 않음"],"w":["복수형('~들')은 쓰지 않음","CUST_TB 같은 약어·물리 테이블명은 피함","'관리' 같은 업무 행위를 이름에 붙이지 않음",""],"t":"가장 짧고 현업이 그대로 부르는 이름이 정답인 경우가 많습니다."},"543":{"k":["엔터티는 **관계 1개 이상**이 원칙 → '독립적으로 혼자 존재'는 오히려 반대"],"w":["업무에서 관리가 필요한지 확인하는 건 맞는 확인 사항","","인스턴스가 두 개 이상인지 확인하는 건 맞음","유일하게 식별할 수 있는지 확인하는 것도 맞음"],"t":"'다른 엔터티 없이 독립적으로'라는 표현은 엔터티 특징(관계 존재)과 충돌합니다."},"1065":{"k":["엔터티 = 영속적으로 존재하는 **인스턴스의 집합** → 2개 이상","속성 2개 이상, 업무 프로세스에서 사용"],"w":["업무에서 필요하고 관리할 정보여야 함. 맞는 특징","유일한 식별자로 식별돼야 함. 맞는 특징","관계가 최소 하나 있어야 함. 맞는 특징",""],"t":"엔터티는 '집합'입니다. 집합이라는 단어가 나오면 '하나뿐이어도 된다'는 바로 틀린 말이에요."},"1066":{"k":["**행위** 엔터티: 2개 이상 부모에서 발생, 자주 변경, 양 증가 (주문상세, 이력)"],"w":["기본 엔터티는 부모 없이 독립 생성 (고객, 상품)","중심 엔터티는 기본에서 발생한 업무 중심 (주문, 계약)","","개념 엔터티는 유무형 분류로 기준이 다름"],"t":"'두 개 이상의 부모'와 '자주 바뀜, 양이 늘어남' 조합은 행위 엔터티 정의 문구입니다."},"1067":{"k":["**개념** 엔터티 = 형태 없는 개념 정보 (조직, 보험상품)"],"w":["유형 엔터티는 물리적 형태가 있음 (사원, 물품)","행위 엔터티는 발생 시점 분류라 기준이 다름","사건 엔터티는 업무 수행 중 발생하는 것 (주문, 청구)",""],"t":"'물리적 형태는 없지만'이라는 말이 나오면 개념 엔터티입니다."},"1142":{"k":["**중심** 엔터티: 기본에서 발생 · 업무 중심 · 데이터 양 많음 · 행위 엔터티를 만들어 냄"],"w":["기본 엔터티는 독립 생성되는 부모 역할","개념 엔터티는 유무형 분류","행위 엔터티는 중심에서 파생되는 쪽",""],"t":"'행위 엔터티를 만들어 낸다'는 중심 엔터티의 정의 문구입니다. 만들어지는 쪽이 아니라 만드는 쪽."},"1185":{"k":["기본: 고객·상품 / 중심: 주문 / 행위: 주문상세·**이력**"],"w":["고객은 독립 생성되는 기본 엔터티. 맞는 분류","주문은 기본에서 발생한 중심 엔터티. 맞는 분류","주문상세는 두 부모에서 생기는 행위 엔터티. 맞는 분류",""],"t":"'이력'은 업무가 일어날 때마다 쌓이는 행위 엔터티입니다. 기본이라 하면 틀려요."},"1228":{"k":["엔터티 특징: 업무 필요 · 식별자 · 인스턴스 2+ · 업무 프로세스 사용 · **속성 2+** · 관계 1+"],"w":["속성이 두 개 이상 있어야 엔터티","인스턴스는 두 개 이상 있어야 함","관계는 하나 이상 필요 (코드성 제외 단서와 상관없이 원칙 위반)",""],"t":"숫자가 들어간 특징 세 개(인스턴스 2+, 속성 2+, 관계 1+)는 꼭 같이 외우세요."},"1275":{"k":["엔터티 이름은 **단수 명사** (고객들 ✕ → 고객)"],"w":["현업 용어 사용은 맞는 원칙","","약어를 쓰지 않는 것은 맞는 원칙","이름이 유일해야 하는 것은 맞는 원칙"],"t":"엔터티 자체가 집합이라 이름에 복수형을 또 붙이지 않습니다."},"1276":{"k":["기본(키) 엔터티: 원래 존재, **독립 생성**, 자기 주식별자 보유","부모 식별자를 상속받는 건 중심·행위 쪽"],"w":["업무에 원래 존재하는 정보. 맞는 설명","다른 엔터티와의 관계로 생기지 않고 독립 생성. 맞는 설명","자기만의 주식별자를 가짐. 맞는 설명",""],"t":"기본 엔터티 = '부모가 없다'. 상속받는다는 말이 붙으면 틀린 설명입니다."},"1325":{"k":["발생 시점: 기본 · 중심 · 행위","유무형: 유형 · 개념 · **사건**"],"w":["기본 엔터티는 발생 시점 분류","중심 엔터티는 발생 시점 분류","행위 엔터티는 발생 시점 분류",""],"t":"'사건'과 '행위'가 비슷하게 들리지만 기준이 다릅니다. 사건-유무형, 행위-발생 시점."},"1326":{"k":["주문상품 = 주문과 상품의 M:N을 푸는 엔터티, 두 부모에서 발생 → **행위** 엔터티"],"w":["고객은 기본 엔터티. 맞는 분류","상품은 기본 엔터티. 맞는 분류","","주문은 중심 엔터티. 맞는 분류"],"t":"M:N을 풀려고 만든 엔터티(주문상품, 수강신청내역)는 부모가 둘이라 행위 엔터티입니다."},"1365":{"k":["유무형 분류: 유형 · 개념 · 사건","중심 엔터티는 발생 시점 분류"],"w":["유형 엔터티는 유무형 분류","개념 엔터티는 유무형 분류","사건 엔터티는 유무형 분류",""],"t":"'유개사'(유형·개념·사건)에 없는 이름을 고르면 됩니다."},"1410":{"k":["기본 엔터티 = 원래 존재 (고객, 상품, 부서)","주문은 고객·상품에서 발생하는 **중심** 엔터티"],"w":["고객은 원래 존재하는 기본 엔터티","상품은 원래 존재하는 기본 엔터티","","부서는 원래 존재하는 기본 엔터티"],"t":"'이게 없어도 이 엔터티가 생길 수 있나?'를 물어 보세요. 주문은 고객·상품 없이는 못 생깁니다."},"1510":{"k":["기본(학생, 강좌)에서 발생 + 다른 엔터티(출석, 성적)의 부모 = **중심** 엔터티"],"w":["기본 엔터티는 다른 엔터티 없이 독립 생성","개념 엔터티는 유무형 분류","","유형 엔터티는 유무형 분류"],"t":"중심 엔터티는 '자식이기도 하고 부모이기도 한' 가운데 위치입니다."},"1513":{"k":["서비스이용 = 고객이 서비스를 쓸 때마다 쌓임 → **행위** 엔터티","개념 엔터티는 조직·보험상품처럼 형태 없는 개념"],"w":["고객은 기본 엔터티. 맞는 분류","서비스는 원래 존재하는 기본 엔터티. 맞는 분류","청구는 이용에서 파생되는 행위 엔터티. 맞는 분류",""],"t":"분류 짝 문제에서 기준이 다른 이름(개념, 사건)이 섞여 있으면 그 보기부터 의심하세요."},"1556":{"k":["발생 시점 분류에 **사건**은 없음 (사건은 유무형 분류)"],"w":["","중심 엔터티는 발생 시점 분류","행위 엔터티는 발생 시점 분류","기본 엔터티는 발생 시점 분류"],"t":"'기중행' 세 글자 밖의 이름이 답입니다."},"1603":{"k":["상품·고객·부서 = 기본 / 주문상세 = **행위**"],"w":["상품은 기본 엔터티","","부서는 기본 엔터티","고객은 기본 엔터티"],"t":"'성격이 다른 하나' 문제는 셋이 같은 분류인지 먼저 확인하면 금방 보입니다."},"1604":{"k":["엔터티: 유일한 식별자 · 인스턴스 2+ · 속성 2+ · 업무 프로세스 사용 · 관계 1+"],"w":["","업무 프로세스에서 쓰이지 않으면 엔터티로 둘 이유가 없음","식별자는 엔터티의 필수 조건","인스턴스는 두 개 이상이어야 함"],"t":"'~없어도 된다', '~하나면 충분하다'처럼 조건을 느슨하게 만드는 보기는 대부분 오답입니다."},"28":{"k":["속성 = 업무에 필요한 **더 이상 분리되지 않는 최소 단위**","한 속성은 **한 값**만, 주식별자에 **함수적 종속**"],"w":["한 속성에 여러 값이 들어가면 1정규형 위반으로 분리 대상","속성은 주식별자에 함수적으로 종속돼야 함","더 분리할 수 있다면 속성이 아니라 여러 속성으로 나눠야 함",""],"t":"속성 정의 문제는 '최소 단위', '한 개의 값', '주식별자에 종속' 세 문구를 찾으세요."},"29":{"k":["특성 분류: 기본 · 설계 · **파생**","파생 속성 = 다른 속성에서 **계산·변형** (총금액, 재고수량)"],"w":["기본 속성은 업무에서 바로 나오는 원래 속성 (단가, 수량)","설계 속성은 모델러가 새로 만든 코드·일련번호","","복합 속성은 구성 방식 분류로 여러 세부 속성으로 나뉘는 것 (주소)"],"t":"파생 속성은 원본이 바뀌면 같이 바꿔야 해서 가급적 적게 두는 게 좋습니다. 이 문장도 자주 나와요."},"30":{"k":["**설계** 속성 = 업무에 원래 없지만 설계하면서 새로 만든 속성 (일련번호, 코드값)"],"w":["","기본 속성은 업무에 원래 있던 속성","파생 속성은 다른 속성에서 계산된 값","단일 속성은 더 쪼갤 수 없는 속성(구성 방식 분류)"],"t":"'새로 만든', '부여한', '내부 관리용 코드'면 설계 속성입니다."},"31":{"k":["파생 속성: 원본이 바뀌면 같이 고쳐야 함 → **정합성 위험** → 꼭 필요한 것만"],"w":["업무에서 바로 나오는 일반적인 속성은 기본 속성","","식별에 쓰이는 건 식별자 속성","관계로 들어온 속성은 FK 속성"],"t":"파생 속성 문제의 정답 문구는 거의 '가급적 적게 정의한다'입니다."},"32":{"k":["구성 방식 분류: **PK · FK · 일반** 속성","관계로 들어온 속성 = FK 속성"],"w":["PK 속성은 엔터티를 식별하는 속성","일반 속성은 PK·FK가 아닌 나머지","복합 속성은 세부 속성으로 나뉘는 속성(분해 여부 분류)",""],"t":"속성 분류 기준은 셋입니다. 특성(기본·설계·파생), 구성 방식(PK·FK·일반), 분해 여부(단일·복합·다중값·단순)."},"33":{"k":["**복합** 속성 = 세부 속성으로 쪼갤 수 있음 (주소 → 시·구·동)","**다중값** 속성 = 값이 여러 개 (전화번호 2개)"],"w":["단일 속성은 더 이상 쪼갤 수 없는 속성","","다중값 속성은 '쪼개지는' 게 아니라 '값이 여러 개'인 것","파생 속성은 계산으로 만든 속성"],"t":"쪼개지면 복합, 여러 개면 다중값. 둘을 섞어서 내니 동사 하나로 구분하세요."},"34":{"k":["**도메인** = 속성이 가질 수 있는 값의 타입·크기·허용 범위 (성별 M/F, 나이 0~120)"],"w":["","인스턴스는 엔터티의 개별 건(한 행)","카디널리티는 관계에 참여하는 개수(1:1, 1:M)","식별자는 인스턴스를 구분하는 속성"],"t":"'값의 범위', '허용 값', '타입과 길이' → 도메인. 제약조건 CHECK로 구현됩니다."},"424":{"k":["다중값 속성 = 한 인스턴스에 값 여러 개 → **1정규형 위반** → 별도 엔터티로 분리"],"w":["단일 속성은 값이 하나","복합 속성은 세부로 쪼개지는 것이지 값이 여러 개인 게 아님","","파생 속성은 계산된 값"],"t":"'여러 개를 가질 수 있다' + '분리' 조합은 다중값 속성입니다."},"498":{"k":["파생 속성 = 다른 속성으로 **계산** (주문금액 = 수량 × 단가)"],"w":["주문수량은 업무에서 바로 나오는 기본 속성","단가는 기본 속성","","주문일자는 기본 속성"],"t":"보기에 '=', '×', '합계', '총~'이 붙은 속성이 파생 속성입니다."},"499":{"k":["한 속성 = 한 값 (원자값)","여러 값이면 **1정규형** 위반 → 정규화 대상"],"w":["한 속성은 한 값만 가짐. 맞는 설명","속성은 엔터티를 설명하는 세부 항목. 맞는 설명","주식별자에 함수적으로 종속됨. 맞는 설명",""],"t":"'정규화와 무관하다'는 말은 속성·정규형 문제에서 거의 늘 틀린 문장입니다."},"500":{"k":["값의 범위를 0~50%로 **제한** = 도메인"],"w":["식별자는 인스턴스를 구분하는 속성","","인스턴스는 엔터티의 개별 건","카디널리티는 관계에 참여하는 수"],"t":"범위·제한·허용 값이라는 말이 나오면 다른 보기는 볼 필요 없이 도메인입니다."},"501":{"k":["**기본** 속성 = 업무 분석으로 바로 도출되는 가장 일반적인 속성"],"w":["복합 속성은 분해 여부 기준 분류","설계 속성은 모델러가 새로 만든 속성","파생 속성은 계산으로 만든 속성",""],"t":"특성 분류 셋 중 '가장 일반적', '바로 도출'은 기본 속성입니다."},"544":{"k":["설계 속성 예: 내부 관리용 **코드**, 일련번호","총주문금액은 파생, 주문일자·고객명은 기본"],"w":["","주문일자는 업무에 원래 있는 기본 속성","고객명은 기본 속성","총주문금액은 계산으로 얻는 파생 속성"],"t":"괄호 속 '새로 부여'가 결정적 힌트입니다. 이런 단서를 놓치지 마세요."},"1068":{"k":["파생 = 계산·변형 (총주문금액) / 설계 = 새로 만듦 (코드, 일련번호) / 기본 = 업무에서 바로"],"w":["","설계 속성은 코드·일련번호처럼 새로 만든 것","기본 속성은 업무에서 바로 도출된 원래 속성","복합 속성은 분해 여부 기준 분류"],"t":"'총~', '합계', '~금액(계산)'은 파생 속성의 단골 예시입니다."},"1069":{"k":["엔터티 ⊃ 인스턴스(2개+) ⊃ 속성(2개+)","한 인스턴스의 한 속성 = **값 하나**"],"w":["엔터티는 인스턴스가 두 개 이상","인스턴스는 속성을 두 개 이상 가짐","한 인스턴스에서 한 속성은 값 하나만 가짐",""],"t":"관계 서술 문제는 숫자를 확인하세요. '한 개만'이 붙는 건 '속성값' 하나뿐입니다."},"1143":{"k":["다중값(취미 여러 개) → 별도 엔터티(회원취미)로 분리, 회원과 **1:M**","쉼표 이어 붙이기·반복 컬럼(취미1·2·3) 모두 1정규형 위반"],"w":["한 칸에 여러 값을 넣으면 원자값 원칙 위반","취미1, 취미2처럼 반복 컬럼을 만드는 것도 1정규형 위반","업무에 필요한 정보를 버리는 건 해결이 아님",""],"t":"반복 컬럼(전화1·전화2)도 1정규형 위반이라는 점이 함정입니다."},"1229":{"k":["파생 속성 = 계산값, 정합성 관리 부담 → 가급적 적게"],"w":["업무에서 자연스럽게 나오는 건 기본 속성","","설계 단계에서 새로 만든 코드는 설계 속성","파생 속성이 많을수록 원본과 어긋날 위험이 커져 무결성은 오히려 나빠짐"],"t":"'많을수록 좋다'는 말은 파생 속성과 반대 방향입니다."},"1282":{"k":["큰 → 작은: **엔터티 → 인스턴스 → 속성 → 속성값**","테이블 → 행 → 컬럼 → 값"],"w":["인스턴스는 엔터티 안의 한 건이라 엔터티보다 작음","속성과 인스턴스 순서가 바뀜. 인스턴스가 속성을 가짐","","속성은 가장 큰 단위가 아님"],"t":"표를 떠올리세요. 표(엔터티) 안에 줄(인스턴스), 줄 안에 칸(속성), 칸 안에 값."},"1327":{"k":["금액 = 단가 × 수량 → **파생** 속성"],"w":["주문번호는 식별에 쓰이는 속성","","수량은 업무에서 바로 나오는 기본 속성","단가는 기본 속성"],"t":"CODE 블록에 '='가 붙은 속성이 바로 정답입니다."},"1328":{"k":["다중값 속성은 1정규형을 깨므로 **별도 엔터티로 분리**","단순(나이) · 다중값(연락처) · 복합(주소)"],"w":["","나이처럼 쪼갤 수 없는 속성은 단순 속성. 맞는 설명","연락처처럼 여러 값이면 다중값 속성. 맞는 설명","주소처럼 쪼개지면 복합 속성. 맞는 설명"],"t":"'원칙이다'라고 단정하는 보기가 원칙과 반대면 정답(틀린 것)입니다."},"1367":{"k":["설계 속성 = 모델링 과정에서 새로 만든 코드·일련번호"],"w":["기본 속성은 업무에서 바로 도출","","파생 속성은 계산된 값","복합 속성은 분해 여부 기준 분류"],"t":"특성 분류: 기본(원래), 설계(만든), 파생(계산). 동사 하나씩 붙여 두세요."},"1461":{"k":["이자율 = 업무에서 정해 **입력**하는 값 → 기본 속성","월이자 = 원금·이자율로 계산 → 파생"],"w":["원금은 기본 속성. 맞는 설명","이자율은 기본 속성. 맞는 설명","월이자는 계산값이라 파생 속성. 맞는 설명",""],"t":"값이 '정해져서 들어오는지', '계산돼서 나오는지'로 판단하세요. 이자율은 계산 결과가 아닙니다."},"1462":{"k":["도메인 = 속성 값의 범위 (타입, 길이, 허용 값)"],"w":["식별자는 인스턴스를 구분하는 것","인스턴스는 개별 건","","관계는 엔터티 간 연결"],"t":"도메인은 시험에서 정의 그대로 묻는 문제가 대부분입니다. '값의 범위' 하나만 기억하세요."},"1511":{"k":["부가세 = 단가 × 0.1 → **파생** 속성, 나머지는 기본"],"w":["상품코드는 기본 속성","","단가는 기본 속성","상품명은 기본 속성"],"t":"'성격이 다른 하나'는 계산식이 붙은 속성을 찾으면 됩니다."},"1512":{"k":["한 인스턴스의 한 속성 = **값 하나**","인스턴스 2개 이상, 속성 2개 이상"],"w":["","엔터티는 인스턴스가 두 개 이상 필요","인스턴스가 가지는 값의 수는 속성 개수만큼이지 항상 두 개가 아님","엔터티는 속성 두 개 이상 필요"],"t":"'항상 두 개'처럼 숫자를 고정한 보기는 의심하세요."},"1555":{"k":["\"성별은 M, F만\" = 값의 범위 = **도메인**"],"w":["식별자는 인스턴스를 구분하는 속성","","인스턴스는 개별 건","카디널리티는 관계에 참여하는 수"],"t":"도메인 문제는 예시만 바뀌어 반복 출제됩니다. 범위 제한 예시면 도메인."},"1605":{"k":["속성명: 현업 용어 · 약어 지양 · **유일** · 서술형 대신 **명사형으로 간결하게** (가입일자)"],"w":["현업 용어 사용은 맞는 원칙","약어를 쓰지 않는 건 맞는 원칙","전체 모델에서 유일하게 짓는 건 맞는 원칙",""],"t":"속성명은 '~하는 ~' 같은 서술식이 아니라 짧은 명사여야 합니다."},"35":{"k":["**존재적** 관계: 존재 자체로 연결 (부서-사원)","**행위적** 관계: 특정 행위가 있어야 생김 (고객-주문)"],"w":["존재적 관계는 행위 없이 존재만으로 연결되는 관계","식별 관계는 부모 PK 상속 방식에 따른 분류","","재귀 관계는 자기 자신을 참조하는 관계"],"t":"'~한다'라는 동작이 있어야 생기면 행위적, 그냥 소속돼 있으면 존재적."},"36":{"k":["관계 표기 3요소: **관계명 · 관계차수 · 관계선택사양** (관차선)"],"w":["","관계명은 표기 요소","관계차수(1:1, 1:M, M:N)는 표기 요소","관계선택사양(필수/선택)은 표기 요소"],"t":"관계에는 인덱스가 없습니다. 인덱스는 물리 설계 대상이에요."},"37":{"k":["M:N은 관계형 DB에서 직접 표현 불가 → **교차(연관) 엔터티**로 1:M 두 개로 분해","예: 학생 – 수강 – 과목"],"w":["슈퍼타입은 공통 속성을 묶는 상속 구조용","","파생 속성은 계산값이라 관계 해소와 무관","보조 식별자는 대체 식별 수단으로 관계 해소와 무관"],"t":"M:N이 보이면 가운데에 엔터티 하나를 끼운다고 생각하세요. 그게 교차 엔터티입니다."},"38":{"k":["ERD는 존재적·행위적 관계를 **구분하지 않음** (같은 관계선)","UML 클래스 다이어그램은 **연관(실선)·의존(점선)**으로 구분"],"w":["ERD는 두 관계를 구분하지 않음","주체가 반대. 구분하지 않는 쪽이 ERD, 구분하는 쪽이 UML","","UML은 연관·의존으로 구분함"],"t":"'ERD는 구분 안 함, UML은 구분함' 한 줄로 끝나는 단골 문제입니다."},"39":{"k":["관계 정의 체크: 연관 규칙 존재 · 정보 조합 발생 · 업무기술서에 규칙 서술 · **연결 동사** 존재","인스턴스 개수와는 무관"],"w":["연관 규칙이 있는지 보는 건 실제 체크 항목","정보 조합이 발생하는지 보는 것도 체크 항목","업무기술서에 관계 규칙이 서술됐는지도 체크 항목",""],"t":"관계는 '두 엔터티를 잇는 동사가 있나'가 핵심입니다. 개수 비교는 관계 판단 기준이 아니에요."},"425":{"k":["관계 표기: **관계명 · 관계차수 · 관계선택사양** (관차선)"],"w":["관계명은 표기 구성요소","관계차수는 표기 구성요소","관계선택사양은 표기 구성요소",""],"t":"관계 표기 요소 문제는 '관차선' 세 개 밖의 그럴듯한 이름(정규성, 인덱스, 정렬순서)이 답입니다."},"502":{"k":["관계**차수**(Cardinality) = 몇 대 몇 (1:1, 1:M, M:N)","관계**선택사양**(Optionality) = 필수/선택"],"w":["관계의 이름은 관계명","필수인지 선택인지는 관계선택사양","","속성 개수는 관계와 무관"],"t":"차수는 '숫자', 선택사양은 '반드시냐 아니냐'. 영어 이름(Cardinality, Optionality)도 같이 외우세요."},"503":{"k":["'반드시', '모든 ~은' = **필수 참여** → 관계선택사양"],"w":["관계차수는 몇 대 몇인지를 나타냄","","관계명은 관계의 이름","식별자는 인스턴스를 구분하는 속성"],"t":"업무 문장에 '반드시'가 있으면 선택사양(필수), '여러', '하나'가 있으면 차수입니다."},"504":{"k":["관계명: **애매한 동사 금지**(관계된다, 관련있다), **현재형**, 양쪽 관점에서 각각 이름"],"w":["애매한 동사를 피하는 건 맞는 지침","현재형으로 표현하는 건 맞는 지침","","양쪽 엔터티 관점에서 각각 이름을 붙이는 건 맞는 지침"],"t":"'관계된다'는 아무 정보도 주지 않는 동사입니다. 구체적인 동사(소속된다, 주문한다)를 써야 해요."},"505":{"k":["M:N 해소 = 교차 엔터티(수강) 추가 → 학생 1:M 수강, 과목 1:M 수강"],"w":["과목1·과목2 같은 반복 컬럼은 1정규형 위반","관계를 없애면 수강이라는 업무를 표현할 수 없음","두 엔터티를 합치면 중복이 크게 생김",""],"t":"M:N 해소 후엔 교차 엔터티 쪽이 항상 M(다) 쪽입니다."},"545":{"k":["관계선택사양 = 한쪽 인스턴스가 관계에 **반드시 참여해야 하는지** (필수/선택)"],"w":["참여 인스턴스 수는 관계차수","식별 관계 여부는 관계 종류(식별/비식별)","관계 이름은 관계명",""],"t":"Optionality = 옵션(선택)이냐 아니냐. 이름에 답이 들어 있습니다."},"1057":{"k":["IE 표기: 원(○) = 0(선택), 막대(|) = 1(필수), 까마귀발(<) = 多","기호는 **상대편 쪽 끝**에 그림 → 사원 쪽 끝 기호가 '부서 하나당 사원 수'"],"w":["","부서 쪽이 ○1이면 사원이 부서 없이도 존재 가능, 사원 쪽 1<은 부서마다 사원 1명 이상이라는 뜻","사원 쪽 1<은 부서에 사원이 최소 1명 있어야 한다는 뜻이라 '없을 수도 있다'와 충돌","까마귀발이 부서 쪽에 붙어 부서가 다(多)가 됨. 방향이 뒤집힘"],"t":"IE 표기는 '반대편 끝을 읽는다'만 기억하면 됩니다. 사원 쪽 끝 = 부서 1개에 사원이 몇 명?"},"1070":{"k":["관계 정의 체크 4가지: 연관 규칙 · 정보 조합 · 업무기술서 규칙 · **관계 동사(Verb)**"],"w":["연관 규칙이 있는지는 실제 확인 사항","정보의 조합이 발생하는지는 확인 사항","","업무기술서에 연결 규칙이 서술됐는지는 확인 사항"],"t":"개수(속성 수, 인스턴스 수)를 비교하는 보기는 관계 체크 항목이 아닙니다."},"1071":{"k":["**존재**에 의한 관계 = 존재 자체로 연결 (부서-사원)","**행위**에 의한 관계 = 행위가 있어야 생김 (고객-주문)"],"w":["","행위에 의한 관계는 주문처럼 행위가 일어나야 생기는 관계","상호배타적 관계는 여러 부모 중 하나만 선택하는 관계","재귀적 관계는 자기 자신을 참조하는 관계"],"t":"부서-사원은 존재 관계의 대표 예시입니다. 사원은 부서에 '있을' 뿐 무슨 행위를 하는 게 아니에요."},"1146":{"k":["엔터티 수 + **M:N 관계 수**(교차 테이블) = 최소 테이블 수","3 + 2 = 5"],"w":["엔터티 3개만 세고 교차 테이블 2개를 빠뜨린 값","교차 테이블을 하나만 센 값","필요 이상으로 센 값",""],"t":"M:N 하나당 테이블이 하나씩 늘어납니다. 1:M은 FK로 해결되니 테이블이 늘지 않아요."},"1281":{"k":["**계층형**: 트리 구조, 부모-자식 **1:M**, 자식은 부모 하나","**네트워크형**: 자식이 여러 부모 가능 (M:N 표현)","**관계형**: 테이블 + 키로 관계 표현"],"w":["M:N 표현은 네트워크형 쪽","자식이 여러 부모를 갖는 건 네트워크형","","같은 레벨끼리 자유롭게 관계를 맺는 건 계층형이 아님"],"t":"계층형=나무(1:M), 네트워크형=그물(M:N). 이름 모양 그대로입니다."},"1283":{"k":["관계명 = 이름 / 관계차수 = 1:1·1:M·M:N / **관계선택사양** = 필수/선택"],"w":["관계명은 관계의 이름","","관계차수는 몇 대 몇인지","관계유형은 관계 표기 요소가 아님"],"t":"'필수/선택' → Optionality(선택사양). 영문 표기로 내도 같은 답입니다."},"1369":{"k":["역할이 다른 엔터티(고객 vs 납부자)는 **업무 규칙 전체**를 보고 통합 여부 결정","일부 경우만 보고 합치면 예외 상황(다른 사람이 납부)을 표현 못 함"],"w":["계약이 고객과 납부자 사이에서 발생한다고 본 건 맞는 설명","고객과 납부자가 같을 수도 다를 수도 있다는 건 맞는 설명","납부자가 바뀔 수 있으니 관계로 연결하는 건 맞는 설명",""],"t":"'무조건', '많으니까'로 결론 내는 보기는 모델링 문제에서 대부분 오답입니다."},"1463":{"k":["관계 표기 = 관계명 · 관계차수 · 관계선택사양"],"w":["관계명은 표기 요소","","관계선택사양은 표기 요소","관계차수는 표기 요소"],"t":"'관계정렬순서'처럼 그럴듯하게 지어낸 이름이 매번 바뀌어 나옵니다. '관차선' 셋만 진짜."},"1558":{"k":["관계선택사양 = 필수/선택, **업무 규칙**에 따라 정함","관계차수 = 참여 수 (1:1, 1:M, M:N)"],"w":["나(업무 규칙에 따라 정함)와 다(차수 정의)도 맞는 설명","다(관계차수 = 참여 수)도 맞는 설명","","가(선택사양 = 필수/선택)도 맞는 설명"],"t":"세 문장 모두 정의를 그대로 옮긴 것이라 전부 맞습니다. '모두 맞는' 경우도 겁내지 마세요."},"1559":{"k":["ERD는 존재·행위 관계를 **구분하지 않음**","ERD의 실선/점선 = **식별/비식별** 관계 구분"],"w":["관계를 존재·행위로 나누는 건 맞는 설명","ERD에서 두 관계를 같은 표기로 쓰는 건 맞는 설명","UML이 연관(실선)·의존(점선)으로 구분하는 건 맞는 설명",""],"t":"실선·점선이 나오면 무엇을 구분하는지 확인하세요. ERD는 식별/비식별, UML은 연관/의존."},"41":{"k":["주식별자 4특징: **유일성 · 최소성 · 불변성 · 존재성** (유최불존)"],"w":["유일성은 주식별자 특징","최소성은 주식별자 특징","","존재성은 주식별자 특징"],"t":"'유최불존' 네 글자를 외우면 나머지 '~성'은 전부 오답입니다."},"42":{"k":["**최소성** = 유일성을 만족하는 범위에서 속성 수 최소"],"w":["","유일성은 모든 인스턴스를 중복 없이 구분하는 것","불변성은 값이 자주 바뀌지 않는 것","존재성은 NULL 없이 반드시 값이 있는 것"],"t":"'속성의 수가 최소' → 최소성. 이름 그대로 나오니 키워드 매칭으로 풀립니다."},"43":{"k":["**불변성** = 주식별자 값은 자주 바뀌지 않아야 함"],"w":["유일성은 인스턴스를 유일하게 구분하는 것","존재성은 반드시 값이 있어야 한다는 것","최소성은 속성 수가 최소여야 한다는 것",""],"t":"주식별자가 바뀌면 그걸 참조하는 자식 FK까지 다 고쳐야 합니다. 그래서 불변성이 중요해요."},"44":{"k":["**존재성** = 주식별자에는 반드시 값이 있어야 함 (NULL 불가)"],"w":["유일성은 중복 없이 구분되는 것","","불변성은 값이 바뀌지 않는 것","최소성은 속성 수가 최소인 것"],"t":"PK 제약은 UNIQUE + NOT NULL입니다. 존재성이 NOT NULL에 해당해요."},"45":{"k":["생성 여부 분류: **내부**(스스로 만듦) / **외부**(관계로 받아옴 = FK)"],"w":["내부 식별자는 엔터티 스스로 만든 식별자","보조 식별자는 대표성 여부 분류","","본질 식별자는 대체 여부 분류(업무로 생긴 식별자)"],"t":"식별자 분류 기준은 4개입니다. 대표성(주/보조), 생성(내부/외부), 속성 수(단일/복합), 대체(본질/인조)."},"46":{"k":["**내부** 식별자 = 엔터티 내부에서 스스로 만들어진 식별자"],"w":["","외부 식별자는 다른 엔터티와의 관계로 받아온 식별자","복합 식별자는 속성 수 기준 분류(2개 이상)","보조 식별자는 대표성 기준 분류"],"t":"'스스로' → 내부, '관계를 통해' → 외부."},"47":{"k":["대체 여부 분류: **본질**(업무로 생김) / **인조**(인위적으로 만듦: 일련번호)"],"w":["본질 식별자는 업무 흐름에서 자연히 만들어진 식별자","","보조 식별자는 대표성 여부 분류","외부 식별자는 관계로 받아온 식별자"],"t":"'인위적', '일련번호', 'SEQ'가 보이면 인조 식별자입니다."},"48":{"k":["인조 식별자 단점: **중복 데이터** 가능 (같은 내용이 번호만 다르게 여러 번)","본래 업무 키에 대한 **인덱스가 추가로** 필요"],"w":["인조 식별자는 보통 짧은 일련번호라 오히려 짧음","업무 규칙 반영 문제는 인조 식별자 단점으로 꼽지 않음","인조 식별자도 자식으로 상속할 수 있음",""],"t":"일련번호는 같은 주문이 두 번 들어와도 번호만 달리 붙여 받아 줍니다. 그래서 중복이 생겨요."},"49":{"k":["대표성 분류: **주식별자**(참조 연결에 사용) / **보조식별자**(식별은 되지만 참조에 안 씀)"],"w":["주식별자는 대표 식별자라 참조 관계 연결에 쓰임","외부 식별자는 생성 여부 분류로 관계에서 받아온 것","","인조 식별자는 대체 여부 분류"],"t":"보조 식별자 예: 사원 엔터티의 주민번호(주식별자는 사번). 식별은 되지만 FK로 넘기지 않습니다."},"60":{"k":["속성 수 분류: **단일**(1개) / **복합**(2개 이상)"],"w":["단일 식별자는 속성 하나로 구성","보조 식별자는 대표성 기준 분류","인조 식별자는 대체 여부 기준 분류",""],"t":"괄호 속 속성이 둘 이상이면 복합 식별자입니다."},"506":{"k":["보조 식별자 = 유일 식별 가능, 하지만 **대표성 없음** → 참조 관계에 안 씀"],"w":["참조 관계에 쓰이는 대표 식별자는 주식별자","단일 속성으로도 보조 식별자가 될 수 있음","","NULL 허용 여부는 보조 식별자의 정의 요소가 아님"],"t":"보조 식별자의 핵심은 딱 하나, '참조 관계 연결에 쓰지 않는다'입니다."},"507":{"k":["주식별자 지정: 불변 · 최소 · NOT NULL · 유일","이름은 **중복**될 수 있어 부적절"],"w":["자주 변하지 않는 값을 고르는 건 맞음(불변성)","","속성 수를 적게 하는 건 맞음(최소성)","NULL이 될 수 있는 속성을 피하는 건 맞음(존재성)"],"t":"동명이인이 있으니 이름은 식별자가 될 수 없습니다. '알아보기 쉬움'은 식별자 기준이 아니에요."},"508":{"k":["여러 속성을 묶은 식별자 = **복합** 식별자"],"w":["단일 식별자는 속성 하나","인조 식별자는 대체 여부 분류","보조 식별자는 대표성 분류",""],"t":"'여러 속성을 묶어'라는 말이 나오면 속성 수 분류의 복합 식별자입니다."},"509":{"k":["본질 = 업무로 생김 / 인조 = 인위적","본질 식별자가 너무 복잡하면 인조로 **대체**하기도 함 (단, 중복 위험)"],"w":["반대. 일련번호처럼 인위적인 건 인조 식별자","반대. 업무로 자연스럽게 생기는 건 본질 식별자","인조 식별자는 오히려 중복 데이터 위험이 생김",""],"t":"본질·인조는 서로 설명을 바꿔치기한 보기가 자주 나옵니다. '인조=인위'만 붙들고 있으면 안 헷갈려요."},"556":{"k":["**최소성** 위배 = 빼도 유일한 속성이 끼어 있음","(사번, 이름)에서 이름은 불필요 → 슈퍼키"],"w":["","사번 하나로 유일하므로 최소성 만족","주민번호 하나로 유일하므로 최소성 만족","이메일 하나로 유일하므로 최소성 만족"],"t":"보기 중 속성이 여러 개 묶인 것부터 보세요. 하나를 빼도 유일하면 최소성 위배입니다."},"1054":{"k":["휴대폰번호는 **바뀔 수 있음** → 불변성 위배","주식별자가 바뀌면 참조하는 FK까지 모두 수정 → 회원번호 같은 값을 따로 둠"],"w":["번호는 사람마다 달라 유일성은 만족","단일 속성이라 최소성은 만족","","필수 입력이면 존재성은 만족"],"t":"휴대폰·이메일·주소처럼 '바뀔 수 있는 값'이 주식별자 후보로 나오면 불변성 문제입니다."},"1055":{"k":["업무에 없던 시퀀스 번호 = **인조** 식별자","주의: 번호만 다르면 같은 주문이 **중복 입력** 가능"],"w":["업무에 원래 있던 값이 아니라 본질 식별자가 아님. 성능이 '항상' 좋아지는 것도 아님","","관계로 받아온 값이 아니라 외부 식별자가 아님","주식별자로 썼으므로 보조 식별자가 아님"],"t":"분류와 주의점이 같이 나오면 둘 다 맞아야 합니다. 인조 ↔ 중복 위험이 한 쌍이에요."},"1072":{"k":["보조 식별자 = 유일하게 구분 가능, **참조 관계 연결에는 안 씀**","외부 = 관계로 받아옴 / 인조 = 만들어 붙임"],"w":["대표 식별자로 참조 관계를 맺는 건 주식별자","","관계로 받아온 식별자는 외부 식별자","업무에 없던 값을 만들어 붙인 건 인조 식별자"],"t":"식별자 문제의 보기 4개가 각각 다른 분류 정의를 하나씩 들고 나오는 경우가 많습니다. 정의-이름 짝만 맞추세요."},"1073":{"k":["(주문번호, 주문순번) = 순번은 인조 → 같은 상품이 **중복 입력** 가능","막으려면 (주문번호, 상품코드)에 별도 UNIQUE 인덱스 → 인덱스 증가"],"w":["순번은 시스템이 채우므로 NULL이 될 일이 없음","주문번호는 여전히 PK에 포함돼 있음","주문번호로 주문과 조인할 수 있음",""],"t":"인조 식별자의 두 단점(중복 데이터, 인덱스 추가)이 그대로 상황 문제로 나온 경우입니다."},"1138":{"k":["교차(관계) 엔터티 = **양쪽 부모 주식별자를 조합**해 식별","그래서 주식별자를 따로 정의하지 않아도 되는 예외로 꼽힘"],"w":["교차 엔터티는 새 본질 식별자를 반드시 정의할 필요가 없음","한쪽 부모 식별자만으로는 유일하지 않음 (한 학생이 여러 과목 수강)","식별자 없는 엔터티는 없음",""],"t":"수강(학번, 과목코드)처럼 부모 두 개의 키를 합친 모양을 떠올리세요."},"1187":{"k":["인조 식별자 = 본질 식별자가 복잡할 때 **일련번호 등을 만들어 대신** 씀","부작용: 중복 데이터 위험"],"w":["속성 수에 따라 반드시 인조 식별자를 쓴다는 규칙은 없음","인조 식별자는 오히려 중복 데이터 위험을 만듦","","업무에서 쓰던 값 그대로면 본질 식별자"],"t":"'위험이 사라진다'는 인조 식별자 문제의 단골 오답 문구입니다."},"1230":{"k":["유일성(구분) · 최소성(속성 수) · **불변성**(안 바뀜) · 존재성(NOT NULL)"],"w":["유일성은 인스턴스를 유일하게 구분하는 것","최소성은 속성 수가 최소인 것","","존재성은 NULL이 없는 것"],"t":"네 특징 각각을 두 글자로 바꿔 두면 정의 문제는 바로 풀립니다: 구분·최소·고정·필수."},"1329":{"k":["**본질** 식별자 = 업무에서 원래 쓰던 값 (주민번호, 사업자번호)"],"w":["인조 식별자는 편의상 새로 만든 값","보조 식별자는 대표성 기준 분류","외부 식별자는 관계로 받아온 것",""],"t":"본질 = 원래 있던 값, 인조 = 새로 만든 값."},"1368":{"k":["주식별자 값은 **자주 바뀌면 안 됨** (불변성)"],"w":["","속성 수 최소는 최소성. 맞는 특징","인스턴스 유일 구분은 유일성. 맞는 특징","NULL 불가는 존재성. 맞는 특징"],"t":"'~해도 된다'처럼 조건을 풀어 주는 보기를 먼저 의심하세요."},"1371":{"k":["관계로 받아온 식별자(FK) = **외부** 식별자","스스로 만든 것 = 내부"],"w":["내부 식별자는 엔터티 스스로 만든 것","","본질 식별자는 대체 여부 분류","보조 식별자는 대표성 분류"],"t":"주문의 고객번호처럼 '다른 엔터티 것'이면 외부 식별자입니다."},"1468":{"k":["분류 기준은 서로 **독립**: 대표성(주/보조) · 생성(내부/외부) · 속성 수(단일/복합) · 대체(본질/인조)"],"w":["","두 개 이상 속성이면 복합 식별자. 맞는 설명","시스템이 부여한 일련번호는 인조 식별자. 맞는 설명","업무에서 자연스럽게 생긴 건 본질 식별자. 맞는 설명"],"t":"속성 수가 많다고 보조가 되지는 않습니다. 기준이 다른 두 분류를 엮은 문장은 틀립니다."},"1517":{"k":["빼도 유일하게 구분되는 속성이 들어 있음 = **최소성** 위배 (슈퍼키)"],"w":["유일하게 구분되므로 유일성은 만족","NULL 여부와 관계없는 상황","값 변경 여부와 관계없는 상황",""],"t":"'~를 빼도 유일하다'라는 문장은 최소성 문제의 정형화된 신호입니다."},"1519":{"k":["업무에서 원래 쓰던 값 = **본질**, 인조는 새로 만든 값"],"w":["본질 식별자는 업무 흐름에서 파악됨. 맞는 설명","","인조 식별자는 중복을 막는 별도 장치(UNIQUE 등)가 필요할 수 있음. 맞는 설명","본질 식별자가 있어도 편의상 인조를 만들 수 있음. 맞는 설명"],"t":"본질·인조 정의를 맞바꾼 보기가 정답(틀린 것)인 경우가 대부분입니다."},"1560":{"k":["주식별자 후보 검사: 유일(이름 ✕) · NOT NULL(이메일 ✕) · 불변(휴대폰 ✕) → **회원번호**"],"w":["","변경이 잦아 불변성 위배","NULL 허용이라 존재성 위배","중복 가능해 유일성 위배"],"t":"표가 나오면 후보마다 네 특징을 체크해서 지워 나가세요. 남는 하나가 답입니다."},"1610":{"k":["불변성: 주식별자 값은 **수시로 바꾸지 않음**"],"w":["모든 인스턴스를 유일하게 구분. 맞는 설명","속성 수를 가능한 적게. 맞는 설명","","NULL을 가질 수 없음. 맞는 설명"],"t":"주식별자 특징 문제의 오답은 대부분 불변성을 뒤집은 문장입니다."},"50":{"k":["**식별** 관계: 부모 PK → 자식 **PK 일부**로 상속, 강한 연결, IE **실선**"],"w":["","일반 속성으로 상속되는 건 비식별 관계","점선은 비식별 관계 표기","부모 없이 생성 가능한 건 비식별 관계 쪽 성격"],"t":"식별 = 실선 = PK로 상속. 셋을 한 묶음으로 외우세요."},"51":{"k":["**비식별** 관계: 부모 PK → 자식 **일반 속성(FK)**으로 상속, 약한 연결, IE **점선**"],"w":["자식 PK로 상속되면 식별 관계","","PK 속성 수가 계속 늘어나는 건 식별 관계만 쓸 때의 문제","부모 없이 존재할 수 없는 강한 종속은 식별 관계"],"t":"비식별 = 점선 = 일반 속성(FK). 부모 없이도 자식이 생길 수 있어 FK가 NULL일 수도 있습니다."},"52":{"k":["식별 관계만 쓰면 자손으로 갈수록 **PK 속성 수 증가** → 조인 조건 복잡, SQL 길어짐","적당히 비식별로 끊어 줌"],"w":["식별 관계는 연결이 오히려 더 강해짐","식별 관계에서도 자식 PK 일부가 곧 FK","부모 엔터티의 속성은 변하지 않음",""],"t":"식별 관계의 문제 = PK가 길어짐, 비식별 관계의 문제 = 조인이 늘어남. 짝으로 외우세요."},"53":{"k":["비식별 기준: 관계가 약함 · 자식에 독립 PK 필요 · 부모 없이 자식 생성 가능 · PK 속성이 너무 많아짐","강한 종속(부모 없이 존재 불가) = **식별**"],"w":["관계가 약하면 비식별이 적절. 맞는 기준","자식에 독립 PK가 필요하면 비식별. 맞는 기준","","부모 없이 자식이 먼저 생길 수 있으면 비식별. 맞는 기준"],"t":"'강하게 종속'이라는 말이 나오면 식별 관계로 가는 기준입니다."},"426":{"k":["식별 = 실선, 비식별 = 점선","비식별: 부모 PK가 자식 **일반 속성**으로","식별만 쓰면 자식 PK **증가**, 인조 식별자는 **중복 위험**"],"w":["식별 관계는 실선으로 표현","","식별 관계만 계속 쓰면 자식 PK 속성 수가 늘어남","인조 식별자는 오히려 중복 데이터 위험이 생김"],"t":"한 문제에 여러 개념이 섞여 있어도 각 보기는 반대 방향으로 뒤집은 것뿐입니다."},"510":{"k":["부모 없이 자식이 먼저 생성 가능 = FK가 NULL 가능 = **비식별** 관계"],"w":["식별 관계는 부모 PK가 자식 PK에 들어가 부모 없이 생성 불가","재귀 관계는 자기 자신을 참조하는 관계","","배타 관계는 여러 부모 중 하나만 선택하는 관계"],"t":"PK에는 NULL이 못 들어가니, 부모 없이 생길 수 있다면 부모 키는 PK가 아니라 일반 속성이어야 합니다."},"511":{"k":["비식별로 끊으면 상위 정보를 얻으려 **조인이 더 필요**해질 수 있음 (줄지 않음)"],"w":["식별 관계는 부모 PK가 자식 PK에 포함. 맞는 설명","","식별 관계를 계속 쓰면 자식 PK가 길어짐. 맞는 설명","비식별 관계는 부모 PK가 자식 일반 속성이 됨. 맞는 설명"],"t":"조인이 줄어드는 쪽은 식별 관계입니다. 부모 키가 자식 PK에 다 들어 있으니까요."},"512":{"k":["부모 PK(주문번호)가 자식 PK(주문번호+상품번호)에 **포함** = 식별 관계"],"w":["","부모 PK가 자식 PK에 들어 있으므로 비식별이 아님","자기 자신을 참조하지 않으므로 재귀가 아님","부모가 하나뿐이라 배타 관계가 아님"],"t":"자식 PK 안에 부모 PK가 보이면 식별, 일반 컬럼 쪽에 보이면 비식별."},"557":{"k":["IE 표기: **실선 = 식별**, **점선 = 비식별**"],"w":["실선은 식별 관계","선 굵기로 관계 종류를 구분하지 않음","이중선은 IE 표기 기호가 아님",""],"t":"약한 연결이라 점선, 이렇게 연결하면 안 잊힙니다."},"1056":{"k":["비식별이 적절: 부모 없이 자식 생성 가능 · 자식에 독립 PK 필요 · 관계가 약함","강한 종속·함께 생성/삭제·조인 줄이기 = 식별 쪽"],"w":["","부모 PK를 자식 PK에 넣는 건 식별 관계","부모 없이 존재할 수 없으면 식별 관계","강하게 종속돼 함께 생성·삭제되면 식별 관계"],"t":"보기 셋이 같은 방향(식별)이고 하나만 반대면, 그 하나가 정답일 확률이 높습니다."},"1074":{"k":["비식별 과다 → 상위 PK가 안 내려와서 **중간 엔터티를 거치는 조인** 증가","식별 과다 → PK 속성 수 증가"],"w":["PK 속성 수가 늘어나는 건 식별 관계를 계속 쓸 때의 문제","","부모 없이 생성 불가는 식별 관계의 성격","비식별 관계에도 FK는 만들 수 있음"],"t":"식별/비식별 '지나치게 쓰면' 문제는 반대쪽 단점을 섞어서 냅니다. 어느 쪽 과다인지 먼저 확인하세요."},"1145":{"k":["IE 실선 = **식별** 관계 → 부모 PK가 자식 PK 일부 (주문상세 PK = 주문번호 + 상품번호)"],"w":["비식별 관계는 점선","M:N이면 양쪽 끝 모두 까마귀발","관계선이 그려져 있으므로 정의된 관계",""],"t":"그림 문제는 선 모양(실선/점선)과 끝 기호(까마귀발 개수) 두 가지만 읽으면 됩니다."},"1231":{"k":["비식별: 부모 PK → 자식 일반 속성, 관계가 **선택적**일 수 있어 자식이 독립 생성 가능"],"w":["부모 PK가 자식 PK 일부가 되는 건 식별 관계","부모 없이 생성 불가는 식별 관계","","자식 PK 속성이 계속 늘어나는 건 식별 관계의 문제"],"t":"세 보기가 같은 쪽(식별) 설명이면 나머지 하나가 답입니다."},"1279":{"k":["식별 관계 차수: 자식 PK = **부모 PK만** → **1:1**","부모 PK + 다른 속성(순번 등) → **1:M**"],"w":["식별 관계도 1:1이 될 수 있음","","반대. 부모 PK만으로 자식 PK를 만들면 1:1","식별 관계도 1:M이 될 수 있음"],"t":"자식 PK가 부모 PK와 똑같으면 부모 하나당 자식도 하나밖에 못 만듭니다. 그래서 1:1."},"1415":{"k":["부모와 **생명주기를 같이** 함(부모 삭제 시 자식도 삭제) = 강한 종속 = **식별** 관계","독립 생명주기 · 별도 PK · FK NULL 허용 = 비식별"],"w":["자식이 독립적인 생명주기를 가지면 비식별이 적합","","자식에 별도 주식별자를 두려면 비식별이 적합","FK가 NULL이어도 되면 비식별이 적합"],"t":"'함께 사라져야 한다'는 강한 종속 신호입니다. 비식별 '아닌' 경우를 찾는 문제라 이게 답이에요."},"1465":{"k":["비식별로 끊으면 상위 키가 아래로 **안 내려감** → 상위 정보 조회 시 **조인 증가**","대신 자식 PK는 짧아짐"],"w":["배송 PK에 상위 키가 더 이상 포함되지 않음. 맞는 설명","고객 조건을 쓰려면 위 테이블과 조인이 더 필요함. 맞는 설명","배송은 주문상세 키를 일반 속성(FK)으로 가짐. 맞는 설명",""],"t":"비식별 전환의 득실: PK는 짧아지고, 조인은 늘어난다. 반대로 말한 보기가 틀린 것."},"1515":{"k":["비식별: 자식은 **독립 PK** 가능, 부모 PK는 일반 속성(FK)","자식 PK = 부모 PK 그대로인 건 식별 관계(1:1)"],"w":["부모 PK가 자식의 일반 속성(FK)이 됨. 맞는 설명","","자식은 독립적인 주식별자를 가질 수 있음. 맞는 설명","부모와 자식의 생성 시점이 다를 수 있음. 맞는 설명"],"t":"'항상 같다'처럼 단정하는 표현이 비식별 설명에 붙으면 거의 틀립니다."},"1557":{"k":["식별 유지 = 자식이 부모에 **강하게 종속**, 부모 없이는 의미 없음","PK 너무 길어짐 · 부모 없이 생성 · 독립 PK 필요 = 비식별로 바꿀 이유"],"w":["자식 PK가 너무 길어진 건 비식별로 바꿀 이유","부모 없이 생성돼야 하면 비식별로 바꿀 이유","","독립 일련번호 PK를 두려면 비식별로 바꿀 이유"],"t":"식별/비식별 선택 문제는 '강한 종속이냐'만 보면 됩니다. 강하면 식별, 아니면 비식별."},"1607":{"k":["IE 표기: 식별 = **실선**, 비식별 = **점선**"],"w":["식별 관계에서 부모 식별자가 자식 주식별자에 포함됨. 맞는 설명","","식별 관계는 실선. 맞는 설명","비식별 관계에서 부모 식별자는 자식 일반 속성. 맞는 설명"],"t":"실선이 둘 다에 붙어 있으면 하나는 틀린 겁니다. 점선은 비식별 몫이에요."},"54":{"k":["**슈퍼키** = 유일성만 (최소성 X)","후보키 = 유일성 + 최소성 → 그중 하나가 기본키, 나머지가 대체키"],"w":["","후보키는 유일성과 최소성을 모두 만족","기본키는 후보키 중 선택된 것이라 최소성 만족","대체키도 후보키이므로 최소성 만족"],"t":"키 포함 관계: 슈퍼키 ⊃ 후보키 = 기본키 + 대체키."},"55":{"k":["**후보키** = 유일성 + 최소성 모두 만족"],"w":["슈퍼키는 유일성만 만족하고 최소성은 보장 안 됨","","외래키는 참조용이라 유일성 요건이 없음","복합 속성은 속성 분류이지 키 분류가 아님"],"t":"유일성+최소성 = 후보키. 이게 키 문제의 기준점입니다."},"56":{"k":["후보키 = **기본키** + **대체키**","대체키 = 기본키로 뽑히지 않은 후보키"],"w":["슈퍼키는 유일성만 만족하는 속성 집합","외래키는 다른 테이블 PK를 참조하는 키","보조 속성은 키 분류 용어가 아님",""],"t":"'선택되지 않은', '남은'이라는 말이 나오면 대체키입니다."},"57":{"k":["FK = 다른 테이블 PK(또는 UNIQUE) 참조, **중복 가능 · NULL 가능 · 여러 개 정의 가능**","참조 무결성 담당"],"w":["FK는 1:M의 M쪽이라 같은 값이 여러 행에 들어감","FK는 NULL을 허용할 수 있음","","한 테이블에 FK를 여러 개 정의할 수 있음"],"t":"FK에 붙는 '반드시', '절대', '하나만'은 전부 틀린 말입니다."},"58":{"k":["학번만으로 유일 → {학번, 이름}은 최소성 위반 → **슈퍼키**"],"w":["","이름을 빼도 학번만으로 유일해 최소성 위반이라 후보키가 아님","대체키는 후보키 중 하나라 최소성이 필요함","외래키는 다른 테이블을 참조하는 키"],"t":"PK에 다른 속성을 하나라도 덧붙이면 그건 무조건 슈퍼키입니다."},"59":{"k":["**식별자** = 논리 모델링 용어 / **키** = 물리 모델링 용어 (서로 대응)"],"w":["반대. 식별자가 논리, 키가 물리","","식별자와 키는 논리↔물리로 대응되는 개념","키는 물리 모델링 용어"],"t":"엔터티↔테이블, 속성↔컬럼, 식별자↔키. 논리↔물리 짝입니다."},"427":{"k":["PK + 다른 속성(수량) = 유일하지만 최소성 X → **슈퍼키**"],"w":["수량이 없어도 유일해 최소성 위반이라 후보키가 아님","PK는 (주문번호, 상품번호)","대체키도 최소성이 필요함",""],"t":"슈퍼키 판별은 '하나 빼도 유일한가?' 한 줄이면 됩니다."},"513":{"k":["후보키 = 유일 + 최소 → 사번, 주민번호, 이메일 각각 = **3개**","이름은 중복 가능 → 제외"],"w":["유일한 속성이 셋이라 1개가 아님","하나를 빠뜨린 값","중복 가능한 이름까지 센 값",""],"t":"단일 속성 각각이 유일하면 각각이 후보키입니다. 조합(사번+이메일)은 최소성 위반이라 세지 않아요."},"514":{"k":["FK는 테이블당 **여러 개** 정의 가능","PK/UNIQUE 참조, NULL 가능, 중복 가능"],"w":["참조 테이블의 PK나 UNIQUE 키를 참조함. 맞는 설명","NULL을 가질 수 있음. 맞는 설명","","같은 값이 여러 행에 들어갈 수 있음. 맞는 설명"],"t":"주문 테이블 하나에 고객번호 FK, 상품번호 FK가 같이 있는 걸 떠올리면 됩니다."},"515":{"k":["슈퍼키 = 유일성만 만족하면 됨 → **유일한 속성이 하나라도 포함**돼 있어야 함","{이름, 학과}는 둘 다 중복 가능 → 유일성 X"],"w":["학번은 PK라 당연히 슈퍼키","","주민번호(UNIQUE)가 포함돼 유일하므로 슈퍼키","학번이 포함돼 유일하므로 슈퍼키"],"t":"슈퍼키 판별은 조합 안에 PK나 UNIQUE 속성이 들어 있는지만 보면 됩니다."},"546":{"k":["**기본키** = 후보키 중 선택된 대표 키"],"w":["외래키는 다른 테이블 참조용","대체키는 선택되지 않은 후보키","","슈퍼키는 최소성이 보장되지 않음"],"t":"후보키 중 '선택한' = 기본키, '남은' = 대체키."},"1075":{"k":["후보키 = 회원번호, 주민번호, 이메일 (유일 + NOT NULL + 단일)","기본키 = 회원번호 → **대체키 = 주민번호, 이메일**"],"w":["회원번호는 기본키로 선택됨","이름은 중복 가능해 후보키가 아님","","(회원번호, 이메일)은 최소성을 깨는 슈퍼키"],"t":"대체키는 '후보키 – 기본키'로 계산하면 실수가 없습니다."},"1144":{"k":["후보키 중 기본키로 선택되지 않은 나머지 = **대체키**"],"w":["슈퍼키는 유일성만 만족하는 속성 집합","외래키는 다른 엔터티 기본키를 참조하는 키","복합키는 속성 수 기준 이름",""],"t":"대체키(Alternate Key)는 PK의 '대안'이라는 뜻입니다."},"61":{"k":["정규화 목적: **이상현상 제거 · 중복 최소화 · 구조 유연성**","테이블이 쪼개져 **조인 증가** → 조회 성능 향상은 반정규화의 목적"],"w":["이상현상 제거는 정규화의 핵심 목적","","중복 최소화는 정규화의 목적","구조 유연성 확보도 정규화의 목적"],"t":"정규화 = 쪼개기, 반정규화 = 합치기. 조회 속도를 올리는 쪽은 합치기입니다."},"62":{"k":["이상현상 3가지: **삽입 · 삭제 · 갱신**"],"w":["삽입 이상은 실제 이상현상","삭제 이상은 실제 이상현상","갱신 이상은 실제 이상현상",""],"t":"조회는 데이터를 바꾸지 않으니 이상현상이 생기지 않습니다. 이상현상은 데이터를 바꿀 때만 생겨요."},"63":{"k":["**1NF** = 모든 속성이 **원자값** (다중값·반복 컬럼 제거)"],"w":["","부분 함수 종속은 2NF에서 제거","이행 함수 종속은 3NF에서 제거","결정자가 후보키가 아닌 문제는 BCNF에서 해결"],"t":"정규형 순서 '두부이겨다줘': 도메인 원자값(1) → 부분 종속(2) → 이행 종속(3) → 결정자(BC) → 다치(4) → 조인(5)."},"64":{"k":["**2NF** = **부분 함수 종속** 제거 (PK 일부에만 종속된 속성 분리)","복합 PK일 때만 생김"],"w":["다중값 속성(원자값 위반)은 1NF에서 해결","이행 함수 종속은 3NF에서 제거","","조인 종속은 5NF에서 제거"],"t":"PK가 컬럼 하나면 부분 종속이 생길 수 없습니다. 2NF 문제는 복합 PK부터 확인하세요."},"65":{"k":["**3NF** = **이행 함수 종속** 제거 (PK → A → B에서 A → B 분리)"],"w":["부분 함수 종속은 2NF에서 제거","","다치 종속은 4NF에서 제거","원자값 문제는 1NF에서 해결"],"t":"이행 = 일반 속성이 다른 일반 속성을 결정하는 것. '부서코드 → 부서명'이 대표 예시."},"66":{"k":["**BCNF** = 모든 결정자가 **후보키** (후보키 아닌 결정자 제거)"],"w":["1NF는 원자값만 보장","2NF는 부분 함수 종속 제거","3NF는 이행 종속까지만 보고 결정자 조건은 따지지 않음",""],"t":"'결정자'라는 단어가 문제에 나오면 BCNF입니다."},"67":{"k":["**4NF** = **다치 종속** 제거 / **5NF** = **조인 종속** 제거"],"w":["","5NF는 조인 종속 제거","BCNF는 후보키가 아닌 결정자 제거","3NF는 이행 함수 종속 제거"],"t":"'다'치는 4, '조'인은 5. '두부이겨다줘'의 마지막 두 글자 '다·줘(조)'."},"68":{"k":["복합 PK (학번, 과목코드)의 **일부(과목코드)** → 과목명 = **부분 함수 종속** → 2NF 위배","해결: 과목(과목코드, 과목명) 분리"],"w":["모든 값이 원자값이라 1NF는 만족","BCNF 이전에 2NF부터 깨져 있음","","3NF는 2NF를 만족한 다음 단계의 문제"],"t":"'PK 일부만으로 결정된다'는 문장 = 2NF 위배. 정형화된 문구입니다."},"69":{"k":["단일 PK(사번) → 부분 종속 없음","사번 → 부서코드 → 부서명 = **이행 종속** → 3NF 위배"],"w":["원자값이라 1NF는 만족","","PK가 한 컬럼이라 부분 종속이 생길 수 없어 2NF는 만족","다치 종속 문제가 아님"],"t":"PK가 단일 컬럼이면 2NF는 자동 통과입니다. 바로 3NF를 보세요."},"70":{"k":["한 칸에 값 두 개 = 원자값 위배 = **1NF** 위배"],"w":["","1NF부터 깨져 있어 2NF 이전 문제","이행 종속이 아니라 원자값 문제","결정자 문제가 아니라 원자값 문제"],"t":"쉼표로 이어 붙인 값이 보이면 1NF입니다. 가장 쉽게 점수 따는 유형이에요."},"71":{"k":["A → B: **A = 결정자**, B = 종속자","A 값 하나 → B 값 **하나**로 정해짐"],"w":["화살표 출발점(A)이 결정자","A 값 하나에 B 값은 하나만 대응됨","PK일 필요 없음. 어떤 속성 사이에도 성립",""],"t":"화살표는 '정해 준다'는 뜻입니다. 왼쪽이 정해 주는 쪽(결정자)."},"80":{"k":["정규화 → 중복 감소로 **입력·수정·삭제 성능 향상** 경향","테이블 분리로 **조인 증가** → 조회 성능 저하 가능"],"w":["","조인이 늘어 조회 성능은 오히려 떨어질 수 있음","중복이 줄어 입력 성능은 오히려 좋아지는 편","테이블 구조가 바뀌니 성능에 영향이 있음"],"t":"'항상'이 붙은 성능 보기는 거의 틀립니다. 정규화가 조회 성능을 올리는 경우도 있어요(테이블이 작아져서)."},"428":{"k":["단일 PK → 2NF 자동 만족","사원번호 → 부서번호 → 부서명 = **이행 종속** → **3NF** 위배"],"w":["값이 모두 원자값이라 1NF는 만족","PK가 단일 컬럼이라 부분 종속이 없음","","BCNF 이전에 3NF부터 깨져 있음"],"t":"'부서번호 → 부서명'은 3NF 위배의 대표 예시입니다. 거의 그대로 나와요."},"429":{"k":["번호만 바꾼 반복 컬럼(상품코드1·2·3) = **반복 그룹** → **1NF** 위배","해결: 상품을 행으로 분리"],"w":["","반복 그룹은 2NF 이전, 1NF 단계 문제","반복 그룹은 3NF 이전 문제","반복 그룹은 BCNF 이전 문제"],"t":"쉼표로 이어 붙인 값뿐 아니라 '컬럼1, 컬럼2'처럼 늘어선 반복 컬럼도 1NF 위배입니다."},"516":{"k":["X → Y: X 값이 정해지면 Y 값이 **하나로** 정해짐, **X = 결정자**"],"w":["","방향이 반대. Y가 정해져도 X가 하나로 정해진다는 보장은 없음","같은 값일 필요 없음","결정자는 화살표 출발점인 X"],"t":"함수 종속은 일방통행입니다. 학번 → 이름은 성립해도 이름 → 학번은 동명이인 때문에 성립 안 해요."},"517":{"k":["PK 일부(상품번호)에만 종속 = **상품명, 단가** → 상품 테이블로 분리","수량은 PK 전체(주문번호+상품번호)에 종속 → 남김"],"w":["수량은 PK 전체에 종속되므로 남겨 둠","수량은 PK 전체에 종속되므로 떼어내면 안 됨","주문번호는 PK의 일부라 떼어낼 대상이 아님",""],"t":"2NF 분해 = 'PK 일부만으로 정해지는 속성'을 그 일부와 함께 새 테이블로 옮기는 것."},"518":{"k":["교수 → 과목인데 **교수는 후보키 아님** = 결정자가 후보키가 아님 → **BCNF** 위배"],"w":["원자값이라 1NF는 만족","일반 속성이 PK 일부에 종속된 게 아니라 일반 속성(교수)이 PK 일부(과목)를 결정하는 구조","","이행 종속이 아니라 결정자 문제"],"t":"일반 속성이 PK 쪽 속성을 결정하는 화살표가 보이면 BCNF입니다. (학생, 과목, 교수) 예시는 거의 고정이에요."},"519":{"k":["**삽입 이상** = 원치 않는 정보가 없으면 넣을 수 없음 (주문 없이 상품 등록 불가)"],"w":["삭제 이상은 지울 때 다른 정보까지 사라지는 것","","갱신 이상은 일부만 수정돼 불일치하는 것","조회 이상이라는 이상현상은 없음"],"t":"넣을 때 막히면 삽입, 지울 때 같이 날아가면 삭제, 고칠 때 어긋나면 갱신."},"520":{"k":["**갱신 이상** = 중복 저장된 값 중 일부만 수정돼 **불일치**"],"w":["","삭제 이상은 지울 때 생기는 문제","삽입 이상은 넣을 때 생기는 문제","조인 이상이라는 이상현상은 없음"],"t":"'일부만 수정', '불일치'가 보이면 갱신 이상입니다."},"521":{"k":["정규화의 근거 = **함수 종속**"],"w":["인덱스는 물리 설계 요소","뷰는 논리 객체로 정규화 기준이 아님","트랜잭션은 작업 단위",""],"t":"정규형 정의(부분 종속, 이행 종속, 결정자)가 전부 함수 종속 용어라는 걸 떠올리세요."},"547":{"k":["정규화 = 중복↓ · 이상현상↓ · 함수 종속 기반","조회는 조인 증가로 **느려질 수도** 있음"],"w":["중복이 줄어든다는 건 맞는 설명","","이상현상을 줄인다는 건 맞는 설명","함수 종속을 근거로 분해한다는 건 맞는 설명"],"t":"정규화 + '항상 조회 성능 향상' 조합은 단골 오답입니다."},"1052":{"k":["학번 → 학생이름, 과목코드 → 과목명 = **PK 일부**에만 종속 → **부분 함수 종속(2NF)**","1NF는 이미 만족 → 가장 먼저 해소할 건 2NF 문제"],"w":["","값이 원자값이라 반복 그룹 문제는 없음","이행 종속보다 부분 종속이 먼저 해결할 단계","BCNF는 그 뒤 단계"],"t":"'가장 먼저 해소할' 문제는 만족 못 하는 가장 낮은 정규형부터 찾으면 됩니다."},"1053":{"k":["교수(일반 속성) → 과목(PK 일부): 부분·이행 종속은 없음 → 3NF까지 만족","결정자(교수)가 후보키가 아님 → **BCNF** 위배"],"w":["원자값이라 1NF는 만족","일반 속성이 PK 일부에 종속되는 부분 종속은 없음","일반 속성끼리 종속(이행)도 없음",""],"t":"3NF와 BCNF의 차이는 '일반 속성이 키 속성을 결정하는가'입니다. 결정하면 3NF는 통과해도 BCNF는 실패."},"1076":{"k":["상품명은 PK 일부(상품번호)로 결정 = **부분** 함수 종속","수량은 PK 전체에 종속 = 완전 함수 종속"],"w":["","완전 종속은 PK 전체가 있어야 정해질 때(수량)","이행 종속은 일반 속성을 거쳐 종속될 때","다치 종속은 4NF 문제"],"t":"속성 하나씩 'PK 전체가 필요한가?'를 물어 보세요. 일부로 충분하면 부분 종속."},"1077":{"k":["정규화 = 변경 이상↓, 조회 시 조인↑ (느려질 수 있음)","논리 모델링 단계, 중복을 **줄이는** 기법"],"w":["'항상'은 틀림. 조인이 늘어 조회가 느려질 수 있음","정규화는 논리 모델링 단계에서 수행","정규화는 중복을 줄이는 기법. 중복을 늘리는 건 반정규화",""],"t":"정규화 = 논리 단계, 반정규화 = 물리 단계. 단계 바꿔치기 보기도 자주 나옵니다."},"1147":{"k":["1NF 원자값 → **2NF 부분 종속** 제거 → **3NF 이행 종속** 제거 → BCNF 결정자 = 후보키","앞 단계를 만족해야 다음 단계"],"w":["1NF는 모든 속성이 원자값. 맞는 설명","앞 단계 정규형을 만족해야 다음 단계로 감. 맞는 설명","BCNF는 모든 결정자가 후보키. 맞는 설명",""],"t":"2NF와 3NF의 제거 대상을 맞바꾼 보기가 가장 흔한 함정입니다."},"1186":{"k":["완전 함수 종속 만족 = 2NF 만족","일반 속성끼리 종속(A → B → C) = **이행 종속** → **3정규화**"],"w":["원자값 문제가 아님","부분 종속은 이미 없어 2정규형은 만족한 상태","","다치 종속 문제가 아님"],"t":"'완전 함수 종속'이라는 말 자체가 '2NF는 끝났다'는 뜻입니다."},"1188":{"k":["상품명은 PK 일부(상품번호)에만 종속 → **부분 함수 종속** 해결(2정규화)"],"w":["값은 원자값이라 1NF 문제가 아님","이행 종속은 일반 속성을 거쳐 종속될 때. 여기는 PK 일부에 직접 종속","","다치 종속 문제가 아님"],"t":"분리한 속성이 PK의 '일부'에 붙어 있었으면 2NF, PK가 아닌 '일반 속성'에 붙어 있었으면 3NF."},"1233":{"k":["2NF = 일반 속성이 PK **전체에 완전 함수 종속**","함수 종속은 방향이 있어 A → B여도 B → A는 보장 안 됨"],"w":["부분 종속 제거는 2NF","이행 종속 제거는 3NF","함수 종속은 방향이 있어 역이 항상 성립하지 않음",""],"t":"정규형 이름과 제거 대상의 짝을 하나씩 어긋나게 만든 보기들입니다. 짝만 정확히 기억하세요."},"1277":{"k":["학생명이 PK 일부(학번)에만 종속 → 학생 테이블 분리 = **2정규화**"],"w":["원자값 문제가 아님","결정자 문제가 아님","이행 종속이 아님 (PK 일부에 직접 종속)",""],"t":"분리된 새 테이블의 PK(학번)가 원래 PK의 일부면 2정규화입니다."},"1278":{"k":["1NF = **원자값**, 반복 그룹 없음","완전 종속 = 2NF, 이행 종속 없음 = 3NF, 결정자 = 후보키 = BCNF"],"w":["완전 함수 종속은 2정규형 설명","","이행 종속 없음은 3정규형 설명","모든 결정자가 후보키는 BCNF 설명"],"t":"정규형 설명 보기는 1~BCNF 정의를 하나씩 들고 나옵니다. 물어본 단계 정의만 고르면 돼요."},"1330":{"k":["완전 함수 종속 → 2NF 만족","일반 속성끼리 종속(이행) 남음 → 3NF 불만족 → **최대 2NF**"],"w":["부분 종속이 없으니 2NF 이상","이행 종속이 남아 있어 3NF는 아님","","3NF도 못 되니 BCNF는 불가능"],"t":"'최대 몇 정규형'은 처음 깨진 단계의 바로 앞 단계입니다."},"1366":{"k":["1정규화 = 값 하나씩 **행으로 분해** (주문번호, 상품코드)","반복 컬럼·구분자 바꾸기는 여전히 1NF 위배"],"w":["","상품코드1·2·3 반복 컬럼도 1NF 위배","주문번호 삭제는 업무 정보를 버리는 것","구분자만 바꿔도 한 칸에 여러 값이라 여전히 위배"],"t":"1NF 해결의 정답은 언제나 '행으로 나눈다' 또는 '별도 엔터티로 분리'입니다."},"1411":{"k":["3NF = 1·2NF 만족 + **이행 종속**(일반 속성끼리 종속) 제거"],"w":["2NF를 만족해야 3NF가 될 수 있음","","부분 종속 제거만으로는 2NF","모든 결정자가 후보키는 BCNF"],"t":"정규형은 계단입니다. 아래 칸을 밟지 않고 위 칸에 갈 수 없어요."},"1416":{"k":["**2정규화** = 부분 함수 종속 제거"],"w":["","1정규화는 원자값","3정규화는 이행 종속 제거","BCNF는 결정자가 후보키"],"t":"부분 = 2, 이행 = 3. 숫자와 단어 하나씩만 짝지으면 끝납니다."},"1466":{"k":["사번 → 부서코드 → 부서명 = 이행 종속 → **3정규화**로 부서 테이블 분리"],"w":["원자값 문제가 아님","PK가 단일 컬럼이라 부분 종속이 아님","","결정자 문제 이전에 이행 종속 문제"],"t":"단일 PK + 일반 속성끼리 종속 = 3정규화. 이 공식으로 대부분 풀립니다."},"1480":{"k":["정규화 = 중복은 **줄이고**, 유연성은 **높임**"],"w":["데이터 중복을 최소화. 맞는 설명","","1NF, 2NF, 3NF, BCNF 등이 있음. 맞는 설명","모델의 유연성을 높임. 맞는 설명"],"t":"1번과 4번을 같이 보면 2번이 모순인 게 보입니다. 보기끼리 충돌하는지도 확인하세요."},"1518":{"k":["2NF(PK 일부 종속), BCNF(결정자 = 후보키)는 **식별자**와 관련","3NF는 **일반 속성끼리**의 이행 종속"],"w":["1정규화는 원자값 문제","2정규화는 PK 일부 종속이라 식별자와 관련","","BCNF는 결정자가 후보키여야 해서 식별자와 관련"],"t":"3NF만 '키가 아닌 속성끼리'의 문제라는 점을 기억해 두세요."},"1561":{"k":["쿠폰코드는 PK 전체에 종속, 쿠폰명은 **일반 속성(쿠폰코드)**에 종속 = 이행 종속 → **3NF** 위배"],"w":["값이 모두 원자값이라 1NF 만족","PK 일부에만 종속된 속성이 없어 2NF 만족","이행 종속이 있어 위배가 있음",""],"t":"표 문제는 같은 쿠폰코드(C10)마다 쿠폰명이 같은지 보세요. 같으면 쿠폰코드 → 쿠폰명 종속입니다."},"1611":{"k":["다중값(취미 여러 개) → **별도 엔터티로 분리** (회원 1:M 회원취미)"],"w":["취미1·2·3 반복 컬럼도 1NF 위배","","쉼표로 이어 붙이면 원자값 위배","업무 요구를 무시하는 해결책"],"t":"다중값 해결 문제의 정답은 '분리' 하나뿐입니다."},"72":{"k":["반정규화 = **조회 성능**을 위해 의도적으로 중복 허용, **무결성 저하** 위험 감수","정규화 → 반정규화 순서"],"w":["반정규화는 무결성을 희생하는 쪽","정규화를 먼저 하고 그다음 반정규화","","중복이 생겨 입력·수정은 오히려 부담이 늘 수 있음"],"t":"반정규화는 '성능 vs 정합성' 거래입니다. 정합성이 좋아진다는 보기는 전부 틀려요."},"73":{"k":["반정규화 절차: **대상 조사 → 다른 방법 검토 → 적용**","다른 방법: 뷰, 인덱스, 클러스터링, 파티셔닝, 응용 로직 변경"],"w":["","적용이 맨 앞일 수 없음. 조사가 먼저","대상 조사가 가장 먼저","다른 방법 검토는 적용 전에 해야 함"],"t":"반정규화는 '마지막 수단'입니다. 그래서 '다른 방법 검토'가 반드시 적용 앞에 옵니다."},"74":{"k":["**테이블** 반정규화: 병합 · 분할(수직/수평) · 테이블 추가(중복·통계·이력·부분)","**컬럼** 반정규화: 중복 · 파생 · 이력 · PK에 의한 컬럼 추가 · 오류 복구용","**관계** 반정규화: 중복 관계 추가"],"w":["테이블 병합은 테이블 반정규화","","수직 분할은 테이블 반정규화","통계 테이블 추가는 테이블 반정규화"],"t":"이름 끝이 '테이블'이면 테이블 반정규화, '컬럼'이면 컬럼 반정규화. 이름 끝 단어로 거의 분류됩니다."},"75":{"k":["컬럼 반정규화 = **컬럼**을 추가 (중복·파생·이력·PK 의미값·오류 복구)","통계 **테이블** 추가는 테이블 반정규화"],"w":["중복 컬럼 추가는 컬럼 반정규화","파생 컬럼 추가는 컬럼 반정규화","이력 테이블 컬럼 추가는 '컬럼'을 넣는 것이라 컬럼 반정규화",""],"t":"'이력 테이블 컬럼 추가'는 이름에 테이블이 들어 있어도 컬럼 반정규화입니다. 끝 단어를 보세요."},"76":{"k":["**관계** 반정규화 = **중복 관계 추가** (조인 경로 단축)"],"w":["테이블 병합은 테이블 반정규화","파생 컬럼 추가는 계산값을 저장하는 컬럼 반정규화","","수평 분할은 행 단위로 테이블을 나누는 것"],"t":"관계 반정규화는 기법이 '중복 관계 추가' 딱 하나라 '관계'라는 말이 나오면 바로 이겁니다."},"77":{"k":["**수직 분할** = 컬럼 단위로 세로로 자름 (자주 쓰는 컬럼 / 드물게 쓰는 컬럼)","**수평 분할** = 행 단위로 자름 (연도별, 지역별)"],"w":["","수평 분할은 행 단위(연도별 등)로 나누는 것","병합은 테이블을 합치는 것","부분 테이블 추가는 기존 테이블은 두고 일부 컬럼만 가진 테이블을 추가"],"t":"표를 세로선으로 자르면 컬럼이 나뉘니 수직, 가로선으로 자르면 행이 나뉘니 수평."},"97":{"k":["조인 과다로 조회가 느릴 때 → (인덱스·뷰 등 검토 후) **반정규화**"],"w":["정규화를 더 하면 테이블이 더 쪼개져 조인이 늘어남","FK를 지워도 조인 횟수는 줄지 않고 무결성만 약해짐","격리 수준은 동시성 제어라 조회 구조와 무관",""],"t":"'조인이 많아 느리다'는 반정규화를 부르는 전형적인 상황 설명입니다."},"430":{"k":["수직·수평 **분할**은 **테이블** 반정규화","컬럼 반정규화 = 중복·파생·이력 컬럼 추가 등"],"w":["중복 컬럼 추가는 컬럼 반정규화","파생 컬럼 추가는 컬럼 반정규화","이력 컬럼 추가는 컬럼 반정규화",""],"t":"분할·병합은 테이블 모양 자체를 바꾸는 일이라 테이블 반정규화입니다."},"522":{"k":["반정규화 전 대안: **인덱스 · 뷰 · 클러스터링 · 파티셔닝 · 응용 로직**","중복 컬럼 추가는 반정규화 그 자체"],"w":["인덱스 조정은 반정규화 전에 검토할 대안","뷰 생성은 반정규화 전 대안","","클러스터링은 반정규화 전 대안"],"t":"대안은 '중복을 만들지 않는' 방법들입니다. 중복이 생기면 이미 반정규화예요."},"523":{"k":["매번 대량 집계가 느림 → 미리 집계해 둔 **통계 테이블 추가**"],"w":["수직 분할은 컬럼 단위로 나누는 것","","중복 관계 추가는 조인 경로를 줄이는 것","테이블 병합은 테이블을 합치는 것"],"t":"'합계', '월별 집계', '매번 계산'이 나오면 통계 테이블입니다."},"524":{"k":["연도별로 행을 나눔 = **수평 분할**"],"w":["","수직 분할은 컬럼 단위로 나누는 것","병합은 테이블을 합치는 것","부분 테이블 추가는 일부 컬럼만 가진 테이블 추가"],"t":"연도·월·지역별 = 행 단위 = 수평. DBMS 파티셔닝(Range)과 같은 발상입니다."},"525":{"k":["반정규화 = 조회 성능 목적, 무결성 위험, 정규화 후 적용","중복 관리 때문에 **변경 작업은 부담 증가**"],"w":["데이터 무결성이 깨질 위험이 있음. 맞는 설명","조회 성능 향상이 주 목적. 맞는 설명","정규화가 끝난 모델에 적용. 맞는 설명",""],"t":"반정규화 + '항상 좋아진다'는 조합은 언제나 틀립니다."},"548":{"k":["이력 테이블에 최신여부·시작/종료일자 같은 기능성 컬럼 추가 = **이력 테이블 컬럼 추가**"],"w":["","파생 컬럼은 계산값을 저장하는 컬럼","중복 컬럼은 다른 테이블 값을 복사해 둔 컬럼","PK에 의한 컬럼은 복합 의미를 가진 PK 값을 쪼개 별도 컬럼으로 둔 것"],"t":"'최신여부', '시작일자·종료일자'가 이력 테이블에 붙으면 이력 테이블 컬럼 추가입니다."},"1058":{"k":["반정규화 전 대안: 뷰 · 인덱스 · 클러스터링 · 파티셔닝 · 응용 로직 (중복 없이 성능↑)","테이블 병합은 반정규화 기법 자체"],"w":["뷰 생성은 반정규화 전 대안","인덱스 조정은 반정규화 전 대안","","클러스터링은 반정규화 전 대안"],"t":"보기 중 '반정규화 기법 이름'이 하나 섞여 있으면 그게 답입니다."},"1078":{"k":["자주 쓰는 컬럼과 나머지를 나눔 = 컬럼 단위 = **수직 분할**"],"w":["수평 분할은 행 단위로 나누는 것","병합은 테이블을 합치는 것","","중복 테이블 추가는 같은 데이터를 담은 테이블을 추가하는 별도 기법"],"t":"컬럼이 너무 많다 → 컬럼을 나눈다 → 수직 분할."},"1079":{"k":["MAX(변경일자) 부담을 줄이려 '최신여부' 추가 = **이력 테이블 컬럼 추가** (컬럼 반정규화)"],"w":["","중복 테이블 추가는 테이블 반정규화","병합은 테이블 반정규화","수평 분할은 행 단위 분할"],"t":"이력 테이블 + 최신 데이터 조회 부담 = 이력 테이블 컬럼 추가. 상황 설명만 바뀌어 반복 출제돼요."},"1331":{"k":["정규화 = 중복↓, **유연성↑**, 변경 이상 방지 (대가: 조인 증가)","반정규화 = 중복 허용, 무결성 관리 부담"],"w":["중복을 줄여 변경 이상을 막음. 맞는 설명","","반정규화는 무결성 유지를 위한 추가 관리가 필요. 맞는 설명","반정규화는 조회 성능을 위해 중복 허용. 맞는 설명"],"t":"정규화의 대가는 '조인'이지 '유연성'이 아닙니다."},"78":{"k":["서브타입별 **개별 처리** → **One to One**(각각 테이블)","**전체 통합 처리** → **Single/All in One**","슈퍼+서브 공통 처리 → **Plus Type**"],"w":["All in One은 전체를 한꺼번에 처리할 때 적합","","Plus Type은 슈퍼와 서브를 함께 처리하는 경우가 많을 때","뷰만으로는 물리 테이블 변환이 아님"],"t":"트랜잭션이 어떻게 일어나는지가 기준입니다. 따로면 따로(One to One), 같이면 하나로(All in One)."},"79":{"k":["**배타적**(Exclusive) = 서브타입 중 **하나에만** 속함","**포괄적**(Inclusive) = 여러 서브타입에 **동시에** 속할 수 있음"],"w":["포괄적 관계는 여러 서브타입에 동시에 속할 수 있음","재귀 관계는 자기 자신을 참조하는 관계","","식별 관계는 PK 상속 방식 분류"],"t":"배타 = 둘 중 하나, 포괄 = 여러 개 동시에. '개인 또는 법인' 고객이 배타의 대표 예시입니다."},"526":{"k":["All in One = 하나로 통합 → 조인↓, 테이블 수↓, **NULL 증가**(다른 서브타입 컬럼은 비어 있음)"],"w":["하나로 합치니 조인은 줄어듦","테이블이 하나로 줄어듦","","서브타입별 처리에는 One to One이 유리"],"t":"개인고객 행에는 법인 전용 컬럼(사업자번호 등)이 비어 있게 됩니다. 그래서 NULL이 많아져요."},"527":{"k":["업무 대부분이 **고객 전체** 대상 → **Single Type(All in One)**"],"w":["One to One은 서브타입별 개별 처리가 많을 때","","Plus Type은 공통 처리와 개별 처리가 섞일 때","서브타입만 테이블로 만들면 전체 처리 때 매번 합쳐야 해 불리"],"t":"'전체를 대상으로'가 키워드입니다. 전체 처리면 한 테이블에 모아 두는 게 유리해요."},"549":{"k":["서브타입마다 별도 테이블 = **One to One Type**","All in One = Single Type (같은 말)"],"w":["All in One은 하나로 통합","Plus Type은 슈퍼+서브 테이블","Single Type은 All in One과 같은 방식",""],"t":"Single Type = All in One. 두 이름이 동시에 보기에 나오면 둘 다 오답일 가능성이 큽니다."},"1060":{"k":["서브타입별 **따로 처리** + 서브타입마다 속성 많음 → **One to One**(각각 테이블)"],"w":["통합 방식은 전체를 같이 처리하는 일이 많을 때 적합","모두 NULL 허용으로 합치면 NULL이 너무 많아짐","서브타입 속성을 지우면 정보 손실",""],"t":"속성이 많은데 하나로 합치면 NULL 범벅이 됩니다. 개별 처리 + 속성 많음 = 나눈다."},"1082":{"k":["서브타입 중 **하나에만** 속함 = **배타적**(Exclusive) 관계"],"w":["포괄적 관계는 여러 서브타입에 동시에 속할 수 있음","재귀적 관계는 자기 자신을 참조","","식별 관계는 PK 상속 방식 분류"],"t":"'하나에만'이 보이면 배타, '동시에'가 보이면 포괄."},"81":{"k":["ACID: **원자성 · 일관성 · 고립성 · 지속성**"],"w":["원자성(Atomicity)은 ACID의 A","일관성(Consistency)은 ACID의 C","","지속성(Durability)은 ACID의 D"],"t":"영문 머리글자가 A·C·I·D인지 확인하면 됩니다. Dependency(종속성)는 D지만 Durability가 아니에요."},"82":{"k":["**원자성** = All or Nothing (전부 반영 or 전부 취소)"],"w":["","일관성은 실행 전후 무결성 규칙 유지","고립성은 다른 트랜잭션의 간섭 방지","지속성은 커밋 후 영구 보존"],"t":"원자 = 더 쪼갤 수 없는 것. 트랜잭션은 반만 실행될 수 없다는 뜻입니다."},"83":{"k":["**지속성** = 커밋된 결과는 장애가 나도 **영구 보존**"],"w":["원자성은 All or Nothing","고립성은 동시 실행 간 간섭 방지","일관성은 무결성 규칙 유지",""],"t":"'커밋된', '영구', '장애가 나도'가 보이면 지속성입니다."},"84":{"k":["**고립성**(Isolation) = 동시 실행 트랜잭션이 서로의 중간 결과에 간섭하지 않음","격리 수준(Isolation Level)과 연결"],"w":["일관성은 무결성 규칙 유지","","원자성은 All or Nothing","지속성은 커밋 결과의 영구 보존"],"t":"'동시에', '중간 결과', '간섭'은 고립성 키워드입니다."},"85":{"k":["**일관성** = 실행 전후 DB가 **무결성 규칙**을 만족하는 상태 유지"],"w":["원자성은 All or Nothing","지속성은 커밋 후 영구 보존","","고립성은 다른 트랜잭션 간섭 방지"],"t":"'규칙', '무결성', '일관된 상태'가 보이면 일관성입니다."},"100":{"k":["출금 + 입금은 **한 묶음** → 하나라도 실패하면 전부 취소 = **원자성**"],"w":["지속성은 커밋된 결과의 영구 보존","고립성은 다른 트랜잭션 간섭 방지","","일관성은 규칙 유지. 묶음 전체 취소는 원자성"],"t":"계좌이체 예시는 거의 항상 원자성 문제입니다. 다만 '잔액 합계가 유지된다'고 물으면 일관성이에요."},"432":{"k":["원자성 = 전부 or 전무 / 일관성 = 규칙 유지 / **고립성 = 간섭 없음** / 지속성 = 커밋 후 영구"],"w":["원자성은 전부 반영 또는 전부 취소","일관성은 무결성 규칙 유지","","지속성은 커밋 결과의 영구 보존"],"t":"ACID 네 개를 각각 한 단어로: 전부·규칙·간섭·영구."},"528":{"k":["**일관성** = 실행 전후 무결성 규칙 만족 상태 유지"],"w":["","전부 실행 or 전부 취소는 원자성","커밋 후 영구 보존은 지속성","다른 트랜잭션이 끼어들지 못하는 건 고립성"],"t":"보기 네 개가 ACID 네 정의를 하나씩 들고 있는 전형적 유형입니다."},"529":{"k":["COMMIT된 거래가 장애 후에도 남아 있음 = **지속성**","DBMS는 로그(redo)로 복구해 지속성 보장"],"w":["원자성은 All or Nothing","일관성은 무결성 규칙 유지","고립성은 다른 트랜잭션 간섭 방지",""],"t":"'서버가 꺼졌다 켜져도', '장애 후에도' + '커밋' = 지속성."},"550":{"k":["트랜잭션 = 논리적 작업 단위, 여러 SQL을 묶어 COMMIT/ROLLBACK","핵심은 **데이터를 바꾸는 DML**"],"w":["논리적 작업 단위. 맞는 설명","COMMIT으로 확정, ROLLBACK으로 취소. 맞는 설명","","여러 SQL을 하나로 묶음. 맞는 설명"],"t":"'SELECT만'처럼 범위를 이상하게 좁힌 보기는 의심하세요. 트랜잭션의 주인공은 INSERT·UPDATE·DELETE입니다."},"1080":{"k":["실행 중 중간 결과를 다른 트랜잭션이 볼 수 없음 = **고립성(Isolation)**"],"w":["","일관성은 실행 전후 모순 없는 상태 유지","원자성은 All or Nothing","지속성은 커밋 후 영구 반영"],"t":"'중간 결과를 볼 수 없다' = 고립성. Dirty Read를 막는 것과 같은 이야기예요."},"1154":{"k":["커밋된 결과는 장애가 나도 사라지지 않음 = **지속성(Durability)**"],"w":["원자성은 All or Nothing","일관성은 모순 없는 상태 유지","고립성은 다른 트랜잭션의 간섭 방지",""],"t":"Durability = 내구성. 오래 버틴다는 뜻에서 '영구 보존'을 떠올리세요."},"1190":{"k":["모델링 단계에서도 **함께 처리되는 데이터 범위(트랜잭션)**를 분석 → 모델 구조에 영향"],"w":["논리적 작업 단위. 맞는 설명","여러 작업을 하나의 커밋 단위로 묶음. 맞는 설명","","모두 성공하거나 모두 실패. 맞는 설명"],"t":"트랜잭션은 SQL만의 주제가 아니라 모델링 1과목에도 나옵니다. '고려 대상이 아니다'는 틀린 말."},"1238":{"k":["분리할 수 없는 논리적 업무 처리 단위 = **트랜잭션**"],"w":["레코드는 데이터 한 건","세션은 DB 접속 단위","","블록은 저장 단위"],"t":"'논리적 작업(연산) 단위'는 트랜잭션 정의 문구 그대로입니다."},"1280":{"k":["출금 후 입금 실패 → 출금까지 취소 = **원자성**"],"w":["","일관성은 무결성 규칙 유지","고립성은 다른 트랜잭션 간섭 방지","지속성은 커밋 후 영구 보존"],"t":"'~까지 취소되어야 한다'는 묶음 처리 = 원자성."},"1419":{"k":["실행 전후 무결성 제약을 만족 = **일관성(Consistency)** (예: 잔액은 음수 불가)"],"w":["원자성은 All or Nothing","지속성은 커밋 후 영구 보존","고립성은 간섭 방지",""],"t":"'전과 후 모두', '제약을 만족' → 일관성."},"1467":{"k":["ACID = Atomicity · Consistency · **Isolation**(고립성) · Durability","Independence(독립성)는 ACID 용어가 아님"],"w":["원자성은 ACID의 A","","일관성은 ACID의 C","지속성은 ACID의 D"],"t":"I는 Isolation입니다. 한글로 '독립성', '격리성'이라고 바꿔 쓰는 함정에 주의하세요(격리성은 고립성의 다른 번역)."},"1563":{"k":["수행 전후 규칙 만족 = **일관성**"],"w":["원자성은 All or Nothing","","고립성은 간섭 방지","지속성은 영구 반영"],"t":"'규칙'이라는 단어 하나로 일관성을 고르면 됩니다."},"1612":{"k":["모델링에서 트랜잭션 고려 = **함께 처리될 데이터 범위**를 정해 무결성 유지","예: 주문·주문상세는 함께 생성 → 관계를 필수로 설계"],"w":["","백업 주기는 운영 정책 문제","테이블 이름과 무관","인덱스 개수와 무관"],"t":"모델링 관점의 트랜잭션 = '같이 생기고 같이 사라지는 데이터 묶음'으로 이해하세요."},"86":{"k":["**Dirty Read** = 다른 트랜잭션이 수정하고 **커밋하지 않은** 데이터를 읽음"],"w":["","Non-Repeatable은 커밋된 수정 때문에 같은 행 값이 바뀌는 것","Phantom은 없던 행이 새로 나타나는 것","Deadlock은 서로 락을 기다리는 교착 상태"],"t":"Dirty = 아직 확정 안 된(더러운) 값. '커밋 전'이 키워드입니다."},"87":{"k":["**Non-Repeatable Read** = 같은 행을 다시 읽었더니 **값**이 바뀜 (다른 트랜잭션의 수정·커밋)"],"w":["Dirty Read는 커밋 안 된 데이터를 읽는 것","Phantom은 행 '개수'가 바뀌는 것","Lost Update는 갱신 결과가 덮어써져 사라지는 것",""],"t":"값이 바뀌면 Non-Repeatable(UPDATE), 행이 생기면 Phantom(INSERT)."},"88":{"k":["**Phantom Read** = 같은 조건 재조회 시 **없던 행**이 나타남 (INSERT)"],"w":["Dirty Read는 커밋 전 데이터를 읽는 것","","Non-Repeatable은 같은 행 '값'이 바뀌는 것","Deadlock은 교착 상태"],"t":"Phantom = 유령. 없던 행이 유령처럼 나타납니다."},"89":{"k":["**Read Uncommitted** = 세 현상 모두 발생 (가장 낮은 수준)"],"w":["Serializable은 세 현상 모두 막음","Repeatable Read는 Phantom만 발생 가능","","Read Committed는 Dirty Read를 막음"],"t":"격리 수준 표: RU(DNP 다 발생) → RC(NP) → RR(P) → S(없음). 한 단계 올라갈 때마다 하나씩 막힙니다."},"90":{"k":["**Repeatable Read** = Dirty·Non-Repeatable 막음, **Phantom만** 남음"],"w":["","Read Committed는 Non-Repeatable·Phantom 모두 발생","Read Uncommitted는 세 현상 모두 발생","Serializable은 Phantom까지 막음"],"t":"이름이 '반복해서 읽어도 같다(Repeatable)'이니 Non-Repeatable을 막는 수준입니다."},"91":{"k":["**Serializable** = 세 현상 모두 막음, 동시성 **가장 낮음** (순서대로 실행한 것처럼)"],"w":["Read Uncommitted는 세 현상 모두 허용","Read Committed는 Dirty Read만 막음","Repeatable Read는 Phantom이 남음",""],"t":"Serial = 일렬로. 트랜잭션을 한 줄로 세워 처리하니 안전하지만 느립니다."},"92":{"k":["격리 수준↑ → **일관성↑, 동시성↓** (락 범위 확대, 대기 증가)"],"w":["격리를 높이면 대기가 늘어 동시 처리 성능은 떨어짐","","격리를 높이면 일관성은 높아짐","락 범위가 넓어지는 변화가 생김"],"t":"일관성과 동시성은 시소입니다. 하나가 오르면 하나가 내려가요."},"93":{"k":["Oracle·SQL Server 기본 격리 수준 = **Read Committed**"],"w":["Oracle은 Read Uncommitted를 지원하지 않음","Repeatable Read는 Oracle 기본값이 아님","","Serializable은 따로 설정해야 쓰는 수준"],"t":"기본값은 둘 다 Read Committed. (참고로 MySQL InnoDB 기본은 Repeatable Read)"},"98":{"k":["낮음 → 높음: **RU → RC → RR → Serializable**"],"w":["","Read Uncommitted가 Read Committed보다 낮음","높은 것부터 나열한 역순","Read Committed가 Repeatable Read보다 낮음"],"t":"커밋 안 된 것도 읽음 → 커밋된 것만 → 반복해도 같은 값 → 줄 세우기. 의미 순서대로 외우세요."},"433":{"k":["Repeatable Read = 읽은 행 값은 보호, **새로 들어오는 행은 못 막음** → Phantom 발생"],"w":["Dirty Read는 Read Committed부터 막힘","Non-Repeatable Read는 Repeatable Read에서 막힘","","Phantom Read는 남아 있음"],"t":"RR에 남는 건 Phantom 하나뿐. 이 한 줄이 가장 많이 출제됩니다."},"476":{"k":["**Read Committed** = Dirty만 막음, Non-Repeatable·Phantom 발생"],"w":["Read Uncommitted는 Dirty Read도 허용","","Repeatable Read는 Non-Repeatable도 막음","Serializable은 모두 막음"],"t":"Committed = 커밋된 것만 읽는다 → 커밋 안 된 값(Dirty)은 못 읽음."},"530":{"k":["커밋 전 값을 읽었는데 상대가 ROLLBACK → 존재하지 않는 값을 읽은 셈 = **Dirty Read**"],"w":["Phantom은 새 행이 생기는 것","Non-Repeatable은 커밋된 수정으로 값이 바뀌는 것","","Lost Update는 갱신이 덮어써지는 것"],"t":"Dirty Read의 위험은 '롤백된 값을 근거로 계산'하는 데 있습니다."},"531":{"k":["Read Committed에서 발생: **Non-Repeatable Read, Phantom Read**"],"w":["Dirty Read는 Read Committed에서 막힘","","Dirty Read는 Read Committed에서 막힘","두 현상이 발생할 수 있음"],"t":"Dirty가 들어간 보기는 RC 문제에서 전부 지우고 시작하세요."},"532":{"k":["격리 수준↑ → Lock 범위↑ → **동시성↓**","RU가 동시성 최고, Serializable이 최저"],"w":["","Read Uncommitted가 동시성은 가장 높음","Serializable은 동시성이 가장 낮음","격리 수준이 높을수록 동시성이 줄어듦"],"t":"가장 느슨한 RU가 가장 빠르고, 가장 엄격한 Serializable이 가장 느립니다."},"551":{"k":["다른 트랜잭션의 **INSERT + COMMIT**으로 같은 조건 결과가 달라짐 = **Phantom Read**"],"w":["커밋된 데이터를 읽었으니 Dirty Read가 아님","","기존 행 값이 바뀐 게 아니라 새 행이 추가됨","갱신 손실이 아님"],"t":"상황 문제는 B가 한 일이 UPDATE인지 INSERT인지만 보세요. INSERT면 Phantom."},"1059":{"k":["커밋된 수정으로 같은 행 값이 바뀜 = **Non-Repeatable Read**","막는 최소 수준 = **Repeatable Read** (RC로는 못 막음)"],"w":["커밋된 수정이라 Dirty Read가 아님","","새 행이 아니라 같은 행의 값이 바뀐 것","Read Committed는 Dirty Read만 막아 이 현상을 못 막음"],"t":"현상 + 최소 격리 수준을 함께 묻는 문제는 짝이 정해져 있습니다: Dirty-RC, Non-Repeatable-RR, Phantom-Serializable."},"1083":{"k":["행 **개수**가 바뀜 = Phantom / 같은 행 **값**이 바뀜 = Non-Repeatable / 커밋 전 값 = Dirty"],"w":["커밋 전 값을 읽은 게 아님","같은 행의 값이 바뀐 게 아님","","갱신 손실이 아님"],"t":"세 현상을 '개수 / 값 / 커밋 전'으로 구분하면 헷갈릴 일이 없습니다."},"1350":{"k":["커밋 전 데이터 읽기 = **Dirty Read**, 막는 최소 수준 = **Read Committed**","트랜잭션 특성으로는 고립성 위반"],"w":["커밋되지 않은 값을 읽었으니 Non-Repeatable이 아님","새 행이 생긴 게 아님","","Read Uncommitted는 Dirty Read를 허용함"],"t":"현상 이름이 맞아도 격리 수준이 틀리면 오답입니다. 짝까지 확인하세요."},"94":{"k":["NULL ≠ 0 ≠ 공백","NULL 비교 → **UNKNOWN**, NULL 산술 → **NULL**","집계함수는 NULL을 **제외**하고 계산 (0으로 바꾸지 않음)"],"w":["NULL은 0이나 공백과 다름. 맞는 설명","NULL과 비교하면 UNKNOWN. 맞는 설명","NULL이 섞인 산술 결과는 NULL. 맞는 설명",""],"t":"AVG(컬럼)에서 NULL 행은 분모에서도 빠집니다. 0으로 바꾸면 분모에 들어가니 결과가 달라져요."},"95":{"k":["같은 테이블의 PK를 참조하는 FK(관리자번호 → 사원번호) = **계층형(재귀) 구조**","조회: **셀프 조인** 또는 **계층형 질의**(START WITH … CONNECT BY)"],"w":["","상호배타 관계가 아니라 자기 참조 구조이고 조회도 가능","1:M 자기 참조라 교차 엔터티가 필요 없음","자기 테이블 PK를 참조하는 FK를 정의할 수 있음"],"t":"사원-관리자, 부품-상위부품, 메뉴-상위메뉴는 모두 계층형 데이터 예시입니다."},"96":{"k":["**상호배타적** 관계 = 여러 부모 중 **하나와만** 관계 (개인고객 **또는** 법인고객)"],"w":["여러 프로젝트 동시 참여는 M:N 관계","","부서-사원은 일반 1:M 관계","학생-과목은 M:N 관계"],"t":"'또는', '중 한쪽'이 보이면 상호배타적(Arc) 관계입니다."},"431":{"k":["두 부모 중 **반드시 하나**와만 관계 = 상호배타적 관계"],"w":["계층형은 자기 자신을 참조하는 관계","","식별 관계는 PK 상속 방식 분류","비식별 관계는 PK 상속 방식 분류"],"t":"배타(Exclusive) = 하나를 고르면 나머지는 배제됩니다."},"533":{"k":["NULL = 아직 정해지지 않은 값(모르는 값)","NULL + 10 → NULL, NULL = NULL → **UNKNOWN**"],"w":["NULL은 공백 문자와 다름","NULL이 섞인 산술 결과는 NULL","NULL끼리 비교해도 UNKNOWN (TRUE 아님)",""],"t":"NULL끼리 같은지 보려면 = 대신 IS NULL을 써야 합니다. 시험에서 자주 묻는 포인트예요."},"534":{"k":["상위부품번호 → 같은 테이블 부품번호 = **계층형**(BOM 구조), 셀프 조인·계층형 질의로 조회"],"w":["자기 참조라 상호배타 관계가 아님","1:M 자기 참조라 교차 엔터티 불필요","","슈퍼/서브타입 구조가 아님"],"t":"'상위~번호' 컬럼이 같은 테이블을 가리키면 계층형입니다."},"552":{"k":["상호배타적 = 여러 부모 중 **하나**와만 관계 (Exclusive OR)"],"w":["","동시가 아니라 하나만","자기 자신과의 관계는 재귀(계층형) 관계","M:N과는 무관"],"t":"ERD에서는 두 관계선을 호(Arc)로 묶어 표시합니다. 그래서 Arc 관계라고도 해요."},"1081":{"k":["NULL 산술 → NULL, NULL 비교 → **UNKNOWN**","COUNT(*)는 **행 자체**를 세니 NULL 행도 포함, COUNT(컬럼)은 NULL 제외"],"w":["NULL + 1은 NULL","NULL은 공백 문자가 아님","COUNT(*)는 NULL이 있는 행도 셈",""],"t":"COUNT(*)와 COUNT(컬럼)의 차이는 시험 단골입니다. 별표는 행, 컬럼은 값을 셉니다."},"1189":{"k":["여러 관계 중 하나만 선택 = **상호 배타적(Arc)** 관계, ERD에 아크 기호"],"w":["식별 관계는 PK 상속 방식 분류","포괄적 관계는 동시에 여러 개 가능","재귀적 관계는 자기 자신 참조",""],"t":"차량-법인/개인, 계좌-개인/법인 같은 '소유자 둘 중 하나' 구조가 Arc의 전형입니다."},"1417":{"k":["Arc 관계 = 하나의 엔터티가 여러 엔터티 중 **하나와만** 관계 (계좌 → 개인 또는 법인)"],"w":["","동시가 아니라 하나만","M:N 해소는 교차 엔터티 몫","자기 자신과의 관계는 재귀 관계"],"t":"배타·재귀·포괄·교차 네 단어의 뜻을 한 줄씩 구분해 두면 이 유형은 전부 풀립니다."},"1562":{"k":["여러 엔터티 중 하나와만 = **배타적(Arc)** 관계"],"w":["포괄적은 여러 개와 동시에 관계 가능","재귀적은 자기 자신 참조","","식별 관계는 PK 상속 방식 분류"],"t":"'하나와만' → 배타적."},"1608":{"k":["한 시점에 **오직 하나의 부모**와만 관계 = **상호 배타적** 관계"],"w":["","재귀 관계는 자기 자신 참조","식별 관계는 PK 상속 방식 분류","포괄적 관계는 여러 개 동시에 가능"],"t":"'오직 하나'라는 강조 표현이 나오면 상호 배타적입니다."},"101":{"k":["IE 표기법 = **까마귀발(Crow's Foot)** 표기법 (관계선 끝이 까마귀 발 모양)"],"w":["","Chen 표기법은 마름모(관계)·타원(속성)을 쓰는 다른 표기법","Barker 표기법은 Oracle CASE에서 쓰는 표기법","UML은 객체지향 표기법"],"t":"IE = Information Engineering. 시험의 ERD 그림은 거의 이 표기법입니다."},"102":{"k":["IE 기호: **까마귀발(<) = 다(多)**, 막대(│) = 1, 원(○) = 0"],"w":["0은 동그라미(○)","정확히 1은 세로 막대(│)","","식별 관계는 선 종류(실선)로 표시"],"t":"기호 세 개만 외우세요. ○ 0, │ 1, < 여러 개."},"103":{"k":["IE 기호 **○ = 0** → 없어도 됨(선택 참여)"],"w":["1개는 세로 막대(│)","","여러 개는 까마귀발(<)","필수 참여는 세로 막대(│)"],"t":"동그라미는 숫자 0 모양 그대로입니다."},"104":{"k":["**││** = 최소 1, 최대 1 = 정확히 1 (필수 1)"],"w":["0 또는 1은 ○│","0개 이상은 ○<","1개 이상은 │<",""],"t":"IE 기호 쌍은 '먼 쪽 = 최소, 붙은 쪽 = 최대'로 읽습니다. ││는 최소도 1, 최대도 1."},"105":{"k":["**○<** = 최소 0(○), 최대 여러 개(<) = 0개 이상"],"w":["","정확히 1은 ││","0 또는 1은 ○│","1개 이상은 │<"],"t":"○<가 가장 느슨한 조건(없어도 되고 많아도 됨)입니다."},"106":{"k":["**│<** = 최소 1(│), 최대 여러 개(<) = 1개 이상"],"w":["0 또는 1은 ○│","정확히 1은 ││","","0개 이상은 ○<"],"t":"네 조합(││, ○│, │<, ○<)을 표로 한 번 그려 보면 바로 외워집니다."},"107":{"k":["IE 기호 읽기: 엔터티에 **붙은 기호 = 최대**, **먼 기호 = 최소**"],"w":["반대. 붙은 기호가 최대, 먼 기호가 최소","","한쪽은 최소, 한쪽은 최대를 뜻함","기호가 엔터티에 붙었는지로 판단해야 함"],"t":"엔터티 바로 옆 기호만 봐도 차수(1:N 등)가 나옵니다. 그다음에 먼 기호로 필수/선택을 보세요."},"108":{"k":["IE 관계선 **실선 = 식별** 관계 (부모 PK가 자식 PK로), 점선 = 비식별"],"w":["비식별 관계는 점선","선택 참여는 ○ 기호로 표시","M:N은 양쪽 끝 모두 까마귀발",""],"t":"선 모양 = 식별 여부, 끝 기호 = 차수와 참여. 역할을 섞지 마세요."},"109":{"k":["IE **점선 = 비식별** 관계 → 부모 PK가 자식 일반 속성(FK)으로","필수/선택은 선 모양이 아니라 ○·│ 기호로"],"w":["","식별 관계는 실선","점선도 정의된 관계(비식별)","선택 참여는 ○ 기호로 표시하지 선 종류가 아님"],"t":"점선을 '선택적'으로 착각하는 실수가 많습니다. 점선은 오직 비식별 표시예요."},"110":{"k":["사원 쪽 끝 ○< → 부서 하나당 사원 **0명 이상**","부서 쪽 끝 ││ → 사원 한 명당 부서 **정확히 1개**"],"w":["사원 쪽 최소가 ○라 사원이 0명일 수 있음","부서 쪽 끝이 ││라 사원은 한 부서에만 소속","","사원 쪽이 까마귀발이라 1:N 관계"],"t":"IE 기호는 '반대편에서 봤을 때 몇 개인가'입니다. 사원 쪽 끝 기호 = 부서 1개에 사원이 몇 명?"},"111":{"k":["부서 쪽 ││ → 사원은 부서가 **정확히 1개 필수** → 부서 없는 사원 불가"],"w":["사원 쪽이 까마귀발이라 1:N. 맞는 설명","","부서 쪽 ││라 사원은 정확히 하나의 부서. 맞는 설명","사원 쪽 ○<라 사원이 없는 부서 가능. 맞는 설명"],"t":"'~없이 존재할 수 있다'는 상대편 끝의 먼 기호가 ○인지 확인하면 됩니다. 여기선 │라 불가."},"112":{"k":["주문 쪽 끝 │< → 고객 한 명당 주문 **1건 이상**","고객 쪽 끝 ○│(최대 1, 최소 0) → 주문은 고객이 없어도 됨"],"w":["고객 쪽 최소가 ○라 주문은 고객 없이도 가능","주문 쪽 최소가 │라 고객은 주문이 최소 1건","고객 쪽 최대가 1이라 1:N",""],"t":"어느 쪽 끝 기호를 읽어야 하는지 헷갈리면 '이 기호가 붙은 엔터티의 개수'라고 생각하세요."},"113":{"k":["양쪽 끝 모두 까마귀발 = **M:N** → **교차 엔터티**(수강)로 1:M 두 개로 분해"],"w":["","과목 컬럼 여러 개는 반복 컬럼이라 1NF 위배","병합하면 중복이 폭증하고 M:N도 해소되지 않음","FK 하나로는 M:N을 표현할 수 없음"],"t":"양쪽 까마귀발을 보면 바로 '교차 엔터티'를 떠올리세요."},"118":{"k":["IE 엔터티 박스: 구분선 **위칸 = PK**, 아래칸 = 일반 속성"],"w":["PK는 엔터티 박스 안에 표시","","관계선 위에는 관계명을 씀","아래칸은 일반 속성 영역"],"t":"박스 위칸에 있는 속성이 몇 개인지 보면 복합 PK 여부도 바로 보입니다."},"119":{"k":["ERD 읽는 순서: **최대값 → 차수**(1:1, 1:N, M:N), **최소값 → 필수/선택**, **선 종류 → 식별 여부**"],"w":["선 종류는 식별 여부이지 차수가 아님","최소값은 참여 여부. 차수는 최대값으로 판단","엔터티 이름 길이는 관계와 무관",""],"t":"세 정보를 각각 다른 곳에서 읽는다는 점이 핵심입니다."},"434":{"k":["부서 쪽 ││ → 사원 입장에서 부서 **정확히 1개(필수)**","사원 쪽 ○< → 부서 입장에서 사원 0명 이상 → **1:N**"],"w":["사원 쪽 최소가 ○라 사원 0명도 가능","","부서 쪽 최대가 1이라 한 부서에만 소속","한쪽 끝이 ││라 1:N"],"t":"부서-사원 ││ / ○< 조합은 IE 문제의 기본형입니다. 여기서 막히지 않게 해 두세요."},"535":{"k":["게시글 쪽 │< → 회원당 게시글 **1개 이상**","회원 쪽 ○│ → 게시글은 회원 없이도 가능"],"w":["회원 쪽 최소가 ○라 회원 없이도 게시글 존재 가능","","게시글 쪽이 까마귀발이라 1:N","게시글 쪽 최소가 │라 최소 1개는 작성"],"t":"보기 1과 2가 서로 다른 쪽 끝을 읽는 문장입니다. 문장 주어가 무엇인지 꼭 확인하세요."},"536":{"k":["양쪽 끝 모두 ││ = **필수 1:1**"],"w":["","사원증 쪽 ││라 정확히 1개 (0개 불가)","까마귀발이 없어 1:1","사원 쪽 ││라 사원증은 사원이 필수"],"t":"까마귀발이 하나도 없으면 1:1입니다. 그다음 ○ 유무로 필수/선택을 보세요."},"537":{"k":["차수(최대값) = 엔터티에 **붙은 쪽** 기호 (│ 또는 <)","먼 쪽 기호(○ 또는 │) = 최소값(참여)"],"w":["먼 쪽 기호는 최소값으로 참여 여부를 뜻함","엔터티 이름은 차수와 무관","관계선 색은 표기 요소가 아님",""],"t":"붙은 쪽이 '<'면 다(多), '│'면 1. 이것만으로 1:1·1:N·M:N이 정해집니다."},"538":{"k":["'부서에 사원 1명 이상' = 사원 쪽 끝 **│<** (최소 1, 최대 多)"],"w":["○<는 0명 이상이라 사원이 없어도 됨","││는 정확히 1명","","○│는 0 또는 1명"],"t":"'반드시'는 먼 쪽 기호 │, '여러 명'은 붙은 쪽 기호 <. 두 조건을 따로 기호로 바꾸세요."},"553":{"k":["**○│** = 최소 0, 최대 1 = 0 또는 1"],"w":["1개 이상은 │<","정확히 1은 ││","0개 이상은 ○<",""],"t":"IE 기호 네 조합: ││ 정확히1, ○│ 0~1, │< 1이상, ○< 0이상."},"1050":{"k":["주문 쪽 ○< → 고객 한 명당 주문 0개 이상(선택)","고객 쪽 ││ → 주문 하나당 고객 정확히 1명(필수)"],"w":["","주문 쪽 먼 기호가 ○라 주문이 0개여도 됨","고객 쪽 ││라 주문에는 고객이 반드시 있어야 함","고객 쪽 최대가 1이라 1:N"],"t":"IE 해석 문제는 두 문장(이쪽에서 본 저쪽, 저쪽에서 본 이쪽)을 다 맞춰야 정답입니다."},"1051":{"k":["IE: 식별 = 실선, 비식별 = 점선","○ = 0(선택), │ = 1, < = 多","붙은 기호 = 최대, 먼 기호 = 최소"],"w":["반대. 식별이 실선, 비식별이 점선","","○는 0으로 선택 참여","까마귀발은 여러 개"],"t":"IE 규칙 네 줄(선 모양, 세 기호, 붙은/먼 위치)만 정확하면 IE 문제는 계산 문제가 됩니다."},"1232":{"k":["점선 = 비식별 → 고객번호는 주문의 **FK(일반 속성)**, PK 아님","고객 쪽 ││ → 주문마다 고객 필수"],"w":["점선이라 비식별. 고객번호는 PK에 포함되지 않음","주문 쪽 ○라 주문 없는 고객도 존재 가능","고객 쪽 ││라 주문은 고객이 반드시 있어야 함",""],"t":"그림 하나로 선 모양·끝 기호를 동시에 묻는 문제입니다. 보기마다 어느 정보를 묻는지 분류하세요."},"1372":{"k":["수강 쪽 ○< → 학생은 수강이 **0건이어도** 존재 가능","학생 쪽 ││ → 수강마다 학생 필수"],"w":["","학생 쪽 ││라 수강은 반드시 학생 하나에 속함. 맞는 해석","수강 쪽 까마귀발이라 여러 개 가능. 맞는 해석","수강 쪽 ○라 하나도 없어도 됨. 맞는 해석"],"t":"부모(학생)를 만들려고 자식(수강)이 먼저 있어야 한다는 건 순서가 거꾸로입니다."},"1373":{"k":["상품 쪽 ││ → 주문상세마다 상품 **정확히 1** (필수)","주문상세 쪽 ○< → 상품은 주문상세 0개여도 됨"],"w":["주문상세 쪽 ○라 상품이 주문상세에 안 쓰여도 됨","상품 쪽 ││라 주문상세에는 상품이 필수","주문상세 쪽 까마귀발이라 상품 하나가 여러 주문상세에 쓰임",""],"t":"점선(비식별)은 이 문제에서 함정입니다. 필수/선택은 선이 아니라 ○·│로 읽어요."},"1414":{"k":["양쪽 ○│ = **선택 1:1** → 서로 없을 수도 있고, 있으면 최대 하나"],"w":["마더보드 쪽 ○라 없을 수도 있음","","컴퓨터 쪽 ○라 마더보드는 컴퓨터 없이도 존재","최대 1개라 여러 개가 아님"],"t":"○│ 양쪽이면 '있어도 되고 없어도 되는 1:1'입니다."},"1418":{"k":["수강 쪽 ○< → 학생은 수강 **0건**이어도 등록 가능","점선 = 비식별 → 학생ID는 FK"],"w":["학생 쪽 ││라 수강은 반드시 학생에 속함. 맞는 설명","수강 쪽 ○라 수강 이력 없는 학생 가능. 맞는 설명","","학생ID는 학생을 참조하는 외래키. 맞는 설명"],"t":"'~하려면 최소 한 건 있어야 한다'는 │가 있어야 성립합니다. ○면 틀린 문장."},"1469":{"k":["수강 쪽 ○< → 과목은 수강이 **0건**일 수 있음"],"w":["까마귀발이 수강 쪽 한 곳이라 1:M. 맞는 해석","수강 쪽 ○라 수강자 없는 과목 가능. 맞는 해석","과목 쪽 ││라 수강은 반드시 과목 하나에 속함. 맞는 해석",""],"t":"'반드시 1건 이상'은 │<일 때만 맞습니다. ○<면 틀려요."},"1606":{"k":["비회원 주문 가능 → 주문에서 본 고객 0~1 → 고객 쪽 **○│**","고객당 주문 여러 건(0 이상) → 주문 쪽 **○<**"],"w":["고객 필수 + 주문 1건 이상 필수라 조건과 다름","고객 쪽 ││라 비회원 주문이 불가능","","고객 쪽까지 까마귀발이라 M:N"],"t":"조건 문장을 '누가 몇 개 가지는지'로 쪼갠 뒤, 그 '몇 개'를 해당 엔터티 쪽 끝에 그리면 됩니다."},"1609":{"k":["사원 쪽 ○< → 사원 **없는 부서** 가능","주민번호가 유일하면 후보키, FK 값은 부모에 있어야 함(참조 무결성)"],"w":["유일하다면 후보키가 될 수 있음. 맞는 설명","FK 값은 부서에 있는 값이어야 함(NULL 제외). 맞는 설명","부서번호(PK)로 부서위치를 알 수 있음. 맞는 설명",""],"t":"키·무결성·IE 해석이 한 문제에 섞였지만, 틀린 건 IE 기호 해석 하나입니다."},"99":{"k":["Barker: `#` 주식별자, `*` 필수(NOT NULL), `o` 선택(NULL 허용)","IE 표기법은 NULL 허용 여부를 표시하지 않음"],"w":["IE는 NULL 허용을 기호로 표시하지 않음","#은 주식별자","*은 필수(NOT NULL)",""],"t":"속성 앞 기호(#, *, o)는 Barker 전용입니다. IE에는 없어요."},"114":{"k":["**Barker** 표기법 = Oracle CASE 표기법, **선 종류(실선/점선)로 필수/선택**"],"w":["IE는 ○·│ 기호로 필수/선택을 표시","Chen은 사각형·마름모·타원 표기","","UML은 Oracle CASE 표기법이 아님"],"t":"Barker = Oracle CASE. 이 짝은 그대로 외우세요."},"115":{"k":["Barker 속성 기호: **# = 주식별자**, * = 필수, o = 선택"],"w":["선택 속성은 o","","Barker는 FK를 속성 기호로 표시하지 않음","파생 속성은 별도 기호가 없음"],"t":"#은 '번호(Number)'처럼 식별자 느낌입니다."},"116":{"k":["Barker `o` = optional = NULL 허용(선택) 속성"],"w":["","주식별자는 #","필수 속성은 *","외래키는 속성 기호로 표시하지 않음"],"t":"o = optional. 영어 첫 글자로 외우면 됩니다."},"117":{"k":["Barker 필수/선택 = **관계선 실선(필수) / 점선(선택)**","IE는 ○·│ 기호로 필수/선택"],"w":["동그라미·세로 막대는 IE 표기","까마귀발은 다(多)를 뜻함","","속성 앞 기호는 속성의 필수/선택"],"t":"실선·점선이 나오면 표기법부터 확인하세요. IE는 식별/비식별, Barker는 필수/선택."},"120":{"k":["**Chen** 표기법: 엔터티 = 사각형, 관계 = **마름모**, 속성 = **타원**"],"w":["IE는 사각형과 까마귀발 관계선","Barker는 둥근 사각형과 실선/점선","","UML은 클래스 박스와 연관선"],"t":"마름모가 보이면 Chen입니다. 다른 표기법은 관계를 선으로만 그려요."},"435":{"k":["Barker `*` = 필수 속성 (NOT NULL)"],"w":["주식별자는 #","","선택 속성은 o","Barker는 FK를 속성 기호로 표시하지 않음"],"t":"별표(*)는 '반드시'라는 강조 표시라고 생각하세요."},"539":{"k":["Barker 관계선 한쪽 절반 **점선** = 그쪽 엔터티 참여가 **선택적**"],"w":["Barker에서 식별은 선 종류로 표시하지 않음","","M:N은 양쪽 까마귀발","관계 삭제 예정이라는 의미는 없음"],"t":"Barker는 선을 반씩 나눠 각 엔터티의 참여를 따로 표시합니다."},"540":{"k":["Barker도 **까마귀발 쪽 = 다(多)**","# 주식별자 · * 필수 · o 선택"],"w":["","*는 필수 속성. 맞는 설명","o는 선택 속성. 맞는 설명","#은 주식별자. 맞는 설명"],"t":"까마귀발 = 多는 IE와 Barker가 똑같습니다."},"554":{"k":["사각형(엔터티) · 마름모(관계) · 타원(속성) = **Chen**"],"w":["IE는 까마귀발 표기","Barker는 둥근 사각형과 실선/점선","","UML은 클래스 다이어그램"],"t":"도형 세 가지가 나오면 Chen입니다."},"1191":{"k":["Barker: 실선 = 필수, **점선 = 선택** 참여, 까마귀발 = 多"],"w":["필수 참여는 실선","M:N은 까마귀발로 표시","Barker에서 선 종류는 식별 여부가 아님",""],"t":"Barker 점선 = 선택. IE 점선 = 비식별. 이 둘을 바꿔 내는 문제가 많습니다."},"1234":{"k":["IE 실선/점선 = **식별/비식별**","Barker 실선/점선 = **필수/선택**, 식별 관계는 UID 바(관계선 위 막대)로 표시"],"w":["IE는 까마귀발로 다(多) 표시. 맞는 설명","IE는 실선·점선으로 식별·비식별 구분. 맞는 설명","","Barker는 실선·점선으로 필수·선택 구분. 맞는 설명"],"t":"같은 실선·점선이 표기법마다 뜻이 다릅니다. 표로 두 칸만 정리해 두세요."},"1235":{"k":["Barker: # 주식별자, * 필수, **o 선택(NULL 허용)**","IE는 NULL 허용 표시 없음"],"w":["IE는 NULL 허용 여부를 표시하지 않음","*는 필수(NOT NULL)","","Barker는 o로 NULL 허용을 표시할 수 있음"],"t":"NULL 표시 = Barker만 가능. 이 사실 하나로 1번·4번이 정리됩니다."},"1516":{"k":["Chen: 엔터티 사각형, 관계 마름모, 속성 **타원**"],"w":["","마름모는 관계","사각형은 엔터티","삼각형은 Chen 표기에 없음"],"t":"속성은 동글동글한 타원. 엔터티 주위에 매달려 있는 모양입니다."},"121":{"k":["DDL: **CREATE · ALTER · DROP · RENAME · TRUNCATE**","GRANT·REVOKE = DCL"],"w":["CREATE는 DDL","ALTER는 DDL","TRUNCATE는 DDL (데이터를 지우지만 구조 명령으로 분류)",""],"t":"TRUNCATE는 데이터를 지우는데도 DDL입니다. 이걸 DML로 착각하게 만드는 문제가 단골이에요."},"122":{"k":["DML: **SELECT · INSERT · UPDATE · DELETE · MERGE**","RENAME은 구조를 바꾸는 DDL"],"w":["INSERT는 DML","","UPDATE는 DML","MERGE는 DML"],"t":"데이터 값을 다루면 DML, 테이블 자체(구조·이름)를 다루면 DDL."},"123":{"k":["DCL = 권한 제어: **GRANT, REVOKE**"],"w":["","COMMIT·ROLLBACK은 TCL","CREATE·DROP은 DDL","INSERT·DELETE는 DML"],"t":"Control = 권한 통제. GRANT(주다)/REVOKE(뺏다) 두 개뿐입니다."},"124":{"k":["TCL: **COMMIT · ROLLBACK · SAVEPOINT**","DELETE는 DML"],"w":["COMMIT은 TCL","ROLLBACK은 TCL","","SAVEPOINT는 TCL"],"t":"트랜잭션을 확정·취소·표시하는 명령만 TCL입니다. 데이터를 지우는 DELETE는 DML."},"125":{"k":["TRUNCATE = **DDL** (테이블을 처음 만든 상태로 초기화)","Oracle에서 자동 커밋 → 롤백 불가"],"w":["데이터를 지우지만 구조 명령이라 DML이 아님","권한 명령이 아님","트랜잭션 제어 명령이 아님",""],"t":"TRUNCATE는 '지우기'처럼 보여서 DML로 착각하기 쉽습니다. 시험은 정확히 그 착각을 노려요."},"126":{"k":["MERGE = 있으면 UPDATE, 없으면 INSERT → **DML**"],"w":["구조를 바꾸는 게 아니라 행을 넣고 고치는 명령","","권한 제어 명령이 아님","트랜잭션 제어 명령이 아님"],"t":"DML 다섯 개: SELECT, INSERT, UPDATE, DELETE, MERGE."},"127":{"k":["SELECT만 따로 분류하면 **DQL**(Data Query Language)","시험에선 DML에 포함시키기도 함"],"w":["","DDL은 구조 정의(CREATE 등)","TCL은 COMMIT·ROLLBACK","DCL은 GRANT·REVOKE"],"t":"Query = 조회. 질문에 'SELECT만 따로'라는 단서가 있을 때만 DQL이 답입니다."},"139":{"k":["COMMIT = **TCL** (DCL 아님)","DCL = GRANT, REVOKE"],"w":["RENAME은 DDL. 맞는 연결","MERGE는 DML. 맞는 연결","","SAVEPOINT는 TCL. 맞는 연결"],"t":"TCL과 DCL은 글자 하나 차이라 섞어 냅니다. T = Transaction, D = 권한(Data Control)."},"436":{"k":["DDL = CREATE · ALTER · DROP · RENAME · **TRUNCATE**"],"w":["","INSERT·DELETE·MERGE는 DML","GRANT·REVOKE는 DCL","COMMIT·SAVEPOINT는 TCL"],"t":"보기 묶음 문제는 하나라도 다른 분류가 섞이면 탈락입니다."},"558":{"k":["RENAME = 객체 이름(구조) 변경 → **DDL**"],"w":["RENAME은 데이터가 아니라 구조(이름)를 바꿈","권한 명령이 아님","","트랜잭션 명령이 아님"],"t":"테이블 '자체'에 손대면 DDL입니다. 이름도 테이블의 일부예요."},"559":{"k":["권한 부여/회수 = **DCL** (GRANT, REVOKE)"],"w":["DDL은 구조 정의","","DML은 데이터 조작","TCL은 트랜잭션 제어"],"t":"권한 = DCL, 단 하나의 짝입니다."},"560":{"k":["DCL – REVOKE ✓","TRUNCATE는 DDL, INSERT는 DML, GRANT는 DCL"],"w":["","TRUNCATE는 DDL","INSERT는 DML","GRANT는 DCL"],"t":"연결 문제는 보기마다 명령어 하나씩 분류를 확인하면 됩니다. 헷갈리는 건 TRUNCATE뿐이에요."},"561":{"k":["CREATE·ALTER·DROP = DDL, **MERGE = DML**"],"w":["CREATE는 DDL로 나머지와 같은 분류","ALTER는 DDL","DROP은 DDL",""],"t":"'성격이 다른 하나'는 다수 분류를 먼저 정하고 튀는 걸 고르세요."},"562":{"k":["트랜잭션 제어 = **TCL**: COMMIT, ROLLBACK, SAVEPOINT"],"w":["CREATE·DROP은 DDL","GRANT·REVOKE는 DCL","","INSERT·UPDATE는 DML"],"t":"TCL은 데이터 값을 직접 바꾸지 않습니다. 이미 바꾼 걸 확정하거나 되돌릴 뿐이에요."},"563":{"k":["Oracle: **DDL 실행 시 자동 커밋** → 앞의 DML도 확정","SELECT는 트랜잭션 상태에 영향 없음"],"w":["CREATE TABLE은 DDL이라 자동 커밋","","ALTER TABLE은 DDL이라 자동 커밋","TRUNCATE는 DDL이라 자동 커밋"],"t":"Oracle에서 DDL은 실행 전후로 COMMIT이 붙는다고 생각하세요. SQL Server는 다릅니다(DDL도 롤백 가능)."},"564":{"k":["행 추가 = **INSERT**","UPDATE = 기존 행 수정, ALTER = 구조 변경, CREATE = 객체 생성"],"w":["","UPDATE는 기존 행 수정","ALTER는 테이블 구조 변경","CREATE는 테이블 같은 객체 생성"],"t":"행은 INSERT, 컬럼 추가는 ALTER TABLE ... ADD. 행/컬럼을 헷갈리지 마세요."},"565":{"k":["DELETE·UPDATE = **DML**","TRUNCATE·DROP = DDL, REVOKE = DCL"],"w":["TRUNCATE는 DDL","DROP은 DDL","REVOKE는 DCL",""],"t":"삭제 계열 세 명령(DELETE, TRUNCATE, DROP) 중 DML은 DELETE 하나뿐입니다."},"1084":{"k":["TRUNCATE = 저장 공간까지 초기화하는 **DDL**, 자동 커밋"],"w":["","MERGE는 DML","INSERT는 DML","DELETE는 DML"],"t":"DML이 '아닌' 것 문제에서 TRUNCATE가 보이면 거의 확정입니다."},"1157":{"k":["TCL = **COMMIT, ROLLBACK, SAVEPOINT**"],"w":["","GRANT·REVOKE는 DCL","CREATE·ALTER·DROP은 DDL","INSERT·UPDATE·DELETE는 DML"],"t":"다섯 분류의 대표 명령을 한 줄씩 외워 두면 분류 문제는 1초 컷입니다."},"1378":{"k":["RENAME = 객체 이름 변경 = **DDL**","TCL = COMMIT, ROLLBACK, SAVEPOINT"],"w":["TRUNCATE는 DDL. 맞는 분류","MERGE는 DML. 맞는 분류","","GRANT는 DCL. 맞는 분류"],"t":"RENAME은 TCL 쪽에 끼워 넣어도 그럴듯해 보이게 만든 함정입니다."},"1445":{"k":["DCL = GRANT, **REVOKE**"],"w":["INSERT는 DML","TRUNCATE는 DDL","COMMIT은 TCL",""],"t":"DCL은 두 개뿐이라 보기에서 GRANT나 REVOKE를 찾으면 끝입니다."},"128":{"k":["관계형 모델 제안 = **E. F. Codd** (1970, IBM)","Peter Chen = ER 모델, Barker = Barker 표기법"],"w":["Peter Chen은 ER 모델(Chen 표기법)을 제안","Richard Barker는 Barker 표기법을 만든 사람","","Larry Ellison은 Oracle 창업자"],"t":"관계형 = Codd. 이름 짝 문제는 이 한 줄이면 됩니다."},"129":{"k":["RDBMS = **테이블(2차원 표)**로 저장 + 테이블 간 관계 + 무결성 제약 + **SQL**"],"w":["트리 구조는 계층형 DB","","RDBMS의 표준 언어가 SQL","제약조건으로 무결성을 보장함"],"t":"RDBMS 설명 문제의 정답은 '테이블', '관계', '무결성', 'SQL' 중 둘 이상이 들어간 문장입니다."},"130":{"k":["관계대수 **Selection(σ)** = 조건에 맞는 **행** 고르기 → SQL의 WHERE","Projection(π) = **열** 고르기"],"w":["Projection은 열을 고르는 연산","Join은 두 릴레이션을 결합하는 연산","Union은 합집합 연산",""],"t":"이름과 SQL 절이 엇갈립니다. Selection은 SELECT 절이 아니라 WHERE 절이에요."},"131":{"k":["**Projection(π)** = 특정 **열** 추출 → SQL의 SELECT 컬럼 목록"],"w":["","Selection은 행을 고르는 연산","Divide는 나누기 연산","Product는 카티션 곱"],"t":"Project = 투영. 표를 옆에서 비춰 일부 열만 비치게 한다고 상상하세요."},"132":{"k":["합집합 UNION, 교집합 INTERSECT, 차집합 MINUS(EXCEPT), **카티션 곱 = CROSS JOIN**"],"w":["합집합은 UNION. 맞는 대응","교집합은 INTERSECT. 맞는 대응","차집합은 MINUS. 맞는 대응",""],"t":"NATURAL JOIN은 같은 이름 컬럼으로 묶는 조인이지 모든 조합(곱)이 아닙니다."},"133":{"k":["Selection(σ) = 행 거르기 = **WHERE**","SELECT 컬럼 목록 = Projection"],"w":["SELECT 컬럼 목록은 Projection(열 선택)","FROM은 대상 테이블 지정","","ORDER BY는 정렬이라 관계대수 대응이 없음"],"t":"이름이 같은 SELECT 절을 고르게 만드는 함정입니다. 행 = WHERE."},"134":{"k":["Projection(π) = **SELECT 뒤의 컬럼 목록**"],"w":["WHERE는 행을 거르는 Selection","","GROUP BY는 그룹화","HAVING은 그룹 조건"],"t":"π(열) ↔ SELECT 목록, σ(행) ↔ WHERE. 두 줄로 정리됩니다."},"135":{"k":["순수 관계 연산자: **Select · Project · Join · Divide**","일반 집합 연산자: Union · Intersection · Difference · Product"],"w":["Select는 순수 관계 연산자","Project는 순수 관계 연산자","Join은 순수 관계 연산자",""],"t":"집합 연산(합·교·차·곱)은 수학 집합에서 온 것, 순수 관계 연산은 관계형 모델에서 새로 만든 것."},"437":{"k":["Selection = 행을 거르는 조건(`SAL > 2000`)","Projection = 보여 줄 열(`ENAME`)"],"w":["Selection과 Projection이 뒤바뀜","","EMP는 대상 테이블일 뿐 연산이 아님","Projection은 SELECT 컬럼 목록"],"t":"SQL 문장에서 WHERE 뒤 = Selection, SELECT 뒤 = Projection. 위치로 외우세요."},"566":{"k":["Join(⨝) = **공통 속성** 기준으로 두 릴레이션을 하나로 결합"],"w":["행 고르기는 Selection","열 고르기는 Projection","","모든 행 조합은 Product, 그대로 이어 붙이기는 Union 쪽"],"t":"Join의 핵심 단어는 '공통 속성'입니다. 이게 없으면 Product(곱)."},"567":{"k":["Projection = SELECT 목록의 열 **ENAME, SAL**"],"w":["FROM은 대상 릴레이션 지정","","WHERE는 Selection","테이블 전체가 아니라 열 일부를 고르는 것"],"t":"Projection을 물으면 SELECT와 FROM 사이를 보세요."},"568":{"k":["Divide(÷) = 나눗셈: 다른 릴레이션의 **모든** 값과 짝을 이루는 행 찾기","Product(×) = 행 수의 **곱**"],"w":["","Projection은 열의 일부. 맞는 연결","Product는 행 수의 곱만큼 생성. 맞는 연결","Selection은 행의 일부. 맞는 연결"],"t":"행 수의 '합'이 나오는 연산은 없습니다(UNION ALL이 그나마 비슷). 합이라는 말이 보이면 의심."},"569":{"k":["RDBMS 저장 형태 = **테이블(행과 열의 2차원 표)**"],"w":["트리는 계층형 DB","그래프는 그래프 DB","키-값은 NoSQL(Key-Value 저장소)",""],"t":"Relation = 표. 관계형의 '관계'가 테이블 자체를 뜻한다는 점도 알아 두세요."},"570":{"k":["관계형 DB: 제약조건으로 무결성 · SQL 사용 · 키로 관계 연결 · 정규화로 **중복 최소화**"],"w":["제약조건으로 무결성을 보장. 맞는 특징","SQL로 데이터를 다룸. 맞는 특징","","테이블 간 관계를 키로 연결. 맞는 특징"],"t":"관계형 DB가 '중복을 강제'하는 일은 없습니다. 중복을 허용하는 건 반정규화 같은 선택일 뿐이에요."},"571":{"k":["일반 집합 연산자: 합집합 · 교집합 · 차집합 · **카티션 곱**","순수 관계 연산자: **Select** · Project · Join · Divide"],"w":["합집합은 일반 집합 연산자","","카티션 곱은 일반 집합 연산자","교집합은 일반 집합 연산자"],"t":"'합·교·차·곱'은 집합, 'S·P·J·D'는 순수 관계. 두 묶음으로 나눠 두세요."},"1085":{"k":["**Join** = 공통 속성 기준으로 값이 같은 튜플을 수평 결합","Select = 행, Project = 열, Division = 나누기"],"w":["셀렉트는 조건에 맞는 행 선택","프로젝트는 필요한 열 선택","디비전은 나누기 연산",""],"t":"'공통 속성', '수평으로 결합' = 조인. 정의 문구가 거의 그대로 나옵니다."},"1170":{"k":["SQL = **비절차적(선언적)** 언어: 원하는 결과만 기술, 처리 방법은 DBMS(옵티마이저)가 결정","**집합 단위** 처리, ANSI/ISO 표준 존재"],"w":["SQL은 처리 순서를 지정하지 않는 비절차적 언어","SQL은 여러 행을 집합 단위로 처리","","ANSI/ISO 표준이 있음"],"t":"'무엇을(What)'만 말하고 '어떻게(How)'는 DBMS에 맡기는 게 SQL입니다."},"1570":{"k":["SELECT(σ) ↔ WHERE, PROJECT(π) ↔ SELECT 절, JOIN ↔ 조인","**DIVIDE**는 SQL에 직접 대응 없음 → NOT EXISTS 이중 구조 등으로 표현"],"w":["관계 연산 SELECT는 SQL WHERE에 해당. 맞는 설명","PROJECT는 SQL SELECT 절에 해당. 맞는 설명","JOIN은 공통 속성으로 합침. 맞는 설명",""],"t":"MINUS는 차집합(DIFFERENCE)에 대응합니다. DIVIDE와 혼동하게 만든 보기예요."},"1613":{"k":["SQL 특징: 구조적 · 집합적 · **선언적(비절차적)** 언어"],"w":["구조적 언어는 SQL(Structured Query Language)의 특징","집합 단위로 처리하는 집합적 언어","결과를 선언하는 선언적 언어",""],"t":"SQL의 S는 Structured. 절차적(Procedural)은 PL/SQL 쪽 이야기입니다."},"141":{"k":["논리적 실행 순서: **FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY** (FWGHSO)"],"w":["SELECT는 FROM보다 먼저 처리될 수 없음","SELECT는 GROUP BY·HAVING 뒤에 처리","","WHERE가 GROUP BY보다 먼저"],"t":"실행 순서는 '프웨그해셀오'로 외우면 별칭 문제까지 한 번에 풀립니다."},"142":{"k":["가장 먼저 = **FROM** (어느 테이블에서 가져올지부터)"],"w":["","WHERE는 FROM 다음","SELECT는 HAVING 다음","GROUP BY는 WHERE 다음"],"t":"쓰는 순서(SELECT부터)와 실행 순서(FROM부터)가 다르다는 게 포인트입니다."},"143":{"k":["SELECT 뒤에 처리되는 절은 **ORDER BY**뿐 → 그래서 ORDER BY에서만 컬럼 별칭 사용 가능"],"w":["WHERE는 SELECT보다 먼저","GROUP BY는 SELECT보다 먼저","HAVING은 SELECT 바로 앞",""],"t":"'ORDER BY만 SELECT 뒤' 이 한 줄이 별칭 문제의 근거입니다."},"144":{"k":["컬럼 별칭은 SELECT에서 생김 → 그 뒤에 실행되는 **ORDER BY**에서만 사용 (19c 이하 기준)","23ai는 GROUP BY·HAVING 별칭 허용(시험은 19c 기준)"],"w":["WHERE는 SELECT보다 먼저 실행돼 별칭을 모름","","GROUP BY는 SELECT보다 먼저라 19c 이하에선 오류","HAVING도 SELECT보다 먼저라 19c 이하에선 오류"],"t":"실습 환경이 23ai면 GROUP BY 별칭이 돌아갑니다. 시험은 19c 기준이니 '오류'로 답하세요."},"145":{"k":["WHERE는 SELECT보다 먼저 → **별칭(ANN) 모름** → 오류","WHERE에는 계산식(`SAL*12`)을 그대로"],"w":["","계산식을 WHERE에 그대로 쓰면 정상","ORDER BY는 SELECT 뒤라 별칭 사용 가능","ORDER BY 위치 번호 사용은 정상"],"t":"별칭 오류 문제는 별칭이 어느 절에 쓰였는지만 보면 됩니다. ORDER BY가 아니면 오류."},"146":{"k":["GROUP BY도 SELECT보다 먼저 → `GROUP BY D`(별칭) 오류 (19c 이하)"],"w":["일반적인 GROUP BY라 정상","ORDER BY에서 별칭 사용은 정상","","ORDER BY에서 집계 별칭 사용은 정상"],"t":"GROUP BY 별칭 사용은 23ai부터 됩니다. 시험 문제에 '시험 기준'이라고 붙어 있는 이유예요."},"147":{"k":["테이블 별칭은 **FROM**에서 정의 → FROM이 가장 먼저라 **모든 절에서** 사용 가능","별칭을 주면 Oracle에선 원래 테이블명으로 수식 불가"],"w":["테이블 별칭은 FROM 절에서 정의","FROM이 가장 먼저 실행되니 모든 절에서 사용 가능","별칭을 정하면 Oracle에선 원래 이름으로 수식할 수 없음",""],"t":"컬럼 별칭(ORDER BY에서만)과 테이블 별칭(어디서나)을 구분하세요."},"148":{"k":["Oracle 컬럼 별칭에 공백·특수문자·대소문자 유지 → **큰따옴표**","작은따옴표는 문자열 값"],"w":["작은따옴표는 문자열 리터럴","","대괄호는 SQL Server 방식","큰따옴표로 감싸면 가능"],"t":"작은따옴표 = 값, 큰따옴표 = 이름(식별자). 이 구분은 SQL 전체에 통합니다."},"149":{"k":["AS 생략 가능(`ENAME 이름`)","작은따옴표 별칭 · 공백 별칭(따옴표 없이) · 예약어 별칭 = 오류"],"w":["","작은따옴표는 별칭에 쓸 수 없음 (ORA-00923)","공백이 있는 별칭은 큰따옴표가 필요","FROM은 예약어라 별칭으로 쓸 수 없음"],"t":"한글 별칭은 따옴표 없이도 됩니다. 공백만 없으면요."},"150":{"k":["Oracle 별칭에 **작은따옴표** 불가 (ORA-00923)"],"w":["공백 별칭을 큰따옴표로 감싸 정상","AS 별칭 정상","","ORDER BY에서 별칭 사용 정상"],"t":"SQL Server는 작은따옴표 별칭도 허용합니다. 'Oracle에서'라는 조건을 꼭 보세요."},"155":{"k":["WHERE에서 계산 결과로 조건 → **계산식을 다시 쓴다** (`WHERE SAL*12 > 30000`)"],"w":["WHERE는 SELECT보다 먼저라 별칭을 모름","ORDER BY 번호는 WHERE에서 쓸 수 없음","HAVING은 그룹 조건용. 행 조건은 WHERE",""],"t":"인라인 뷰로 감싸면 바깥 WHERE에서 별칭을 쓸 수 있다는 것도 함께 알아 두세요."},"156":{"k":["… GROUP BY → HAVING → **SELECT** → ORDER BY"],"w":["ORDER BY는 SELECT 다음","","GROUP BY는 HAVING보다 먼저","WHERE는 GROUP BY보다 먼저"],"t":"HAVING에서 SELECT 별칭을 못 쓰는 이유가 바로 이 순서입니다."},"159":{"k":["HAVING도 SELECT보다 먼저 → 별칭(TOTAL) 사용 불가 → **집계식 그대로** `HAVING SUM(SAL) > 9000`"],"w":["","HAVING에 집계식을 그대로 써서 정상","ORDER BY 별칭은 정상","ORDER BY 위치 번호는 정상"],"t":"HAVING에는 별칭 대신 집계함수를 다시 적는다. 시험에서 반복되는 패턴입니다."},"441":{"k":["WHERE에서 별칭(Y) 사용 → 오류","ORDER BY는 별칭·위치 번호 모두 가능"],"w":["ORDER BY 별칭은 정상","WHERE에 계산식을 쓴 건 정상","","ORDER BY 위치 번호는 정상"],"t":"2번과 3번은 별칭이냐 식이냐만 다릅니다. 이런 쌍이 보이면 둘 중 하나가 답이에요."},"572":{"k":["FWGHSO: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY"],"w":["","SELECT는 HAVING 뒤에 처리","WHERE는 GROUP BY 앞, SELECT는 ORDER BY 앞","HAVING은 GROUP BY 뒤"],"t":"WHERE(행 거르기) → GROUP BY(묶기) → HAVING(그룹 거르기). 거르고, 묶고, 또 거른다."},"573":{"k":["컬럼 별칭은 **ORDER BY**에서만 사용 가능 (19c 이하)"],"w":["WHERE에서 별칭 사용 불가","19c 이하 GROUP BY에서 별칭 사용 불가","19c 이하 HAVING에서 별칭 사용 불가",""],"t":"정상 실행되는 것을 고르라면 별칭이 ORDER BY에 있는 보기를 찾으세요."},"574":{"k":["Oracle: 테이블 별칭(E)을 주면 원래 이름(EMP.)으로 수식 불가 (ORA-00904)"],"w":["별칭으로 수식해 정상","별칭이 없으면 테이블명으로 수식 가능","","수식 없이 컬럼만 쓰면 정상"],"t":"별칭을 붙이는 순간 테이블 이름은 그 별칭으로 바뀐다고 생각하세요."},"575":{"k":["`SAL * 12 연봉` → AS 생략된 별칭 → 결과 컬럼명 **연봉**"],"w":["별칭이 붙어 계산식이 컬럼명으로 표시되지 않음","","원래 컬럼명이 아니라 별칭이 표시됨","AS 생략은 정상 문법"],"t":"식 뒤에 공백 하나 두고 이름이 붙어 있으면 별칭입니다."},"576":{"k":["컬럼 별칭은 WHERE에서 **사용 불가**","공백·대소문자 유지 = 큰따옴표, AS 생략 가능"],"w":["","공백이 있으면 큰따옴표로 감쌈. 맞는 설명","대소문자를 구분하려면 큰따옴표. 맞는 설명","AS는 생략 가능. 맞는 설명"],"t":"'자유롭게'라는 말은 별칭 문제에서 거의 틀린 말입니다."},"577":{"k":["큰따옴표 별칭 → **대소문자 그대로** 유지 (\"Name\" → Name)","따옴표 없는 별칭은 대문자로 변환"],"w":["큰따옴표로 감싸 대문자 변환이 일어나지 않음","별칭이 우선 표시됨","정상 문법",""],"t":"Oracle은 따옴표 없는 이름을 전부 대문자로 바꿉니다. 큰따옴표는 '쓴 그대로' 고정."},"578":{"k":["ORDER BY는 **맨 마지막** 실행 → 별칭·위치 번호 사용 가능","GROUP BY 없으면 SELECT에 없는 컬럼으로도 정렬 가능"],"w":["SELECT 목록 별칭 사용 가능. 맞는 설명","위치 번호 사용 가능. 맞는 설명","","SELECT에 없는 컬럼으로도 정렬 가능. 맞는 설명"],"t":"ORDER BY 관련 문장 중 '먼저 실행'만 틀린 말입니다."},"579":{"k":["GROUP BY 사용 시 ORDER BY는 **GROUP BY 컬럼이나 집계함수**로만 정렬 가능"],"w":["그룹 결과에 없는 개별 컬럼은 정렬 기준이 될 수 없음","","ORDER BY는 사용 가능","GROUP BY가 정렬을 보장하지 않음"],"t":"GROUP BY 후에는 행이 그룹 단위로 줄어듭니다. 그룹에 없는 컬럼은 '어느 값'인지 정할 수 없어요."},"580":{"k":["WHERE에는 계산식 그대로: `WHERE SAL*12 > 30000`"],"w":["","WHERE에서 별칭 사용 불가","HAVING은 그룹 조건용","큰따옴표를 붙여도 WHERE는 별칭을 모름"],"t":"별칭에 큰따옴표를 붙여도 실행 순서는 바뀌지 않습니다."},"581":{"k":["WHERE로 CLERK 먼저 제외 → 부서별 COUNT → HAVING ≥ 3","10번 2명, 20번 3명, 30번 5명 → **2행**(20, 30)"],"w":["30번만 센 값. 20번도 3명이라 포함","조건을 만족하는 그룹이 있음","10번은 CLERK 제외 시 2명이라 탈락",""],"t":"WHERE가 GROUP BY보다 먼저라 '제외하고 센다'는 점이 핵심입니다. EMP 직무 분포를 한 번 적어 두면 편해요."},"582":{"k":["테이블 별칭은 FROM에서 정의 → FROM이 가장 먼저 → **쿼리의 모든 절**에서 사용"],"w":["SELECT 외 다른 절에서도 사용 가능","WHERE 외 다른 절에서도 사용 가능","","ORDER BY 외 다른 절에서도 사용 가능"],"t":"테이블 별칭은 어디서나, 컬럼 별칭은 ORDER BY에서만. 두 별칭의 범위가 정반대입니다."},"583":{"k":["큰따옴표 필수: 별칭에 **공백·특수문자**가 있거나, **대소문자를 그대로** 유지하고 싶을 때"],"w":["따옴표 없는 별칭은 원래 대문자로 처리되니 대문자엔 따옴표가 필요 없음","","AS 생략 여부와 무관","별칭 길이와 무관"],"t":"\"월 급여\"처럼 띄어쓰기가 들어가면 큰따옴표 없이는 SQL이 두 단어로 읽어 버립니다."},"1086":{"k":["HAVING은 SELECT보다 먼저 → 별칭(합계) 사용 불가 → `HAVING SUM(급여) > 4000`","ORDER BY는 별칭·위치 번호 모두 가능"],"w":["ORDER BY에서 별칭 사용은 정상","ORDER BY 위치 번호는 정상","","WHERE에 일반 컬럼 조건은 정상"],"t":"표 데이터가 길게 나와도 문법 문제면 데이터는 볼 필요가 없습니다. 먼저 무엇을 묻는지 확인하세요."},"1179":{"k":["DISTINCT는 SELECT한 **컬럼 조합 전체** 기준으로 중복 제거","(10,A) (10,B) (20,A) → **3행**"],"w":["(10, B)를 빠뜨린 값","","중복을 일부만 제거한 값","DISTINCT 적용 전 행 수"],"t":"DISTINCT 뒤에 컬럼이 두 개면 '두 값이 모두 같은 행'만 중복입니다."},"1207":{"k":["테이블 별칭을 주면 그 쿼리 안에선 **별칭으로만** 참조 (EMP.ENAME 오류)"],"w":["컬럼 별칭 앞 AS는 생략 가능. 맞는 설명","테이블 별칭은 FROM에서 지정. 맞는 설명","ORDER BY에서 컬럼 별칭 사용 가능. 맞는 설명",""],"t":"별칭을 준 뒤 원래 이름을 쓰는 보기는 Oracle 기준으로 항상 오류입니다."},"1243":{"k":["Oracle: **테이블 별칭 앞에 AS 불가** (`FROM EMP AS E` 오류)","컬럼 별칭 앞 AS는 가능, SQL Server는 둘 다 허용"],"w":["별칭으로 수식해 정상","","컬럼 별칭에 AS는 정상","AS 생략 별칭은 정상"],"t":"AS는 컬럼 별칭 전용(Oracle). 테이블 뒤에 AS가 보이면 Oracle 오류입니다."},"1244":{"k":["같은 이름 테이블 두 개(HR.STADIUM, SPORT.STADIUM) → `STADIUM.NAME`은 **모호** → 오류","별칭이나 스키마명으로 구분"],"w":["","별칭을 써서 정상","별칭 A, B로 구분해 정상","스키마.테이블.컬럼으로 구분해 정상"],"t":"모호성 오류(column ambiguously defined)는 같은 이름이 둘 이상일 때 생깁니다."},"1299":{"k":["컬럼 별칭은 WHERE에서 **사용 불가** (WHERE가 SELECT보다 먼저)"],"w":["AS 생략 가능. 맞는 설명","","공백 별칭은 큰따옴표. 맞는 설명","ORDER BY에서 별칭 사용 가능. 맞는 설명"],"t":"별칭 문제 정답의 절반은 'WHERE에서 별칭'입니다."},"1348":{"k":["FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY"],"w":["","SELECT가 맨 앞일 수 없음","WHERE가 GROUP BY보다 먼저","HAVING은 GROUP BY 뒤, SELECT는 ORDER BY 앞"],"t":"실행 순서는 '쓰는 순서에서 SELECT만 HAVING 뒤로 옮긴 것'이라고 기억해도 됩니다."},"1544":{"k":["WHERE에서 별칭(코드) 사용 → 오류"],"w":["","ORDER BY 별칭은 정상","ORDER BY 위치 번호는 정상","큰따옴표 별칭 정의는 정상"],"t":"한글 별칭이어도 규칙은 같습니다. 별칭이 WHERE에 있으면 오류."},"158":{"k":["`||` = 문자열 연결 (Oracle)","7369 = SMITH, CLERK → `SMITH(CLERK)`"],"w":["JOB과 괄호까지 이어 붙임","공백이 아니라 괄호로 연결함","","|| 연결은 정상 문법"],"t":"EMP 단골 사원: 7369 SMITH(CLERK), 7839 KING(PRESIDENT), 7788 SCOTT(ANALYST). 외워 두면 시간이 줄어요."},"161":{"k":["`SUBSTR(문자, 시작, 길이)`: 5번째(D)부터 3글자 → `Dev`","공백도 한 글자"],"w":["","4글자를 셈. 길이는 3","4번째(공백)부터 센 결과","3번째부터 센 결과"],"t":"SUBSTR은 1부터 셉니다. 'SQL Developer'에서 4번째는 공백이에요."},"162":{"k":["LENGTH는 **공백 포함** 글자 수 → SQL(3) + 공백(1) + Developer(9) = **13**"],"w":["공백을 빼고 센 값","한 글자 더 센 값","","Developer만 센 값"],"t":"LENGTH 문제는 공백을 빠뜨리는 실수가 대부분입니다."},"163":{"k":["`INSTR(문자, 찾을문자)` = **처음** 나오는 위치 → HELLO의 O = 5","없으면 0"],"w":["","두 번째 O(WORLD 쪽) 위치","다른 문자 위치로 착각한 값","O가 있으니 0이 아님"],"t":"INSTR의 3·4번째 인자(시작 위치, 몇 번째)가 없으면 '처음부터 첫 번째'입니다."},"164":{"k":["`LPAD(문자, 전체길이, 채울문자)` = **왼쪽**을 채워 전체 길이 맞춤","AB를 5자리로 → 별표 3개 + AB"],"w":["오른쪽을 채운 결과. 그건 RPAD","양쪽에 나눠 채우지 않음","전체 길이 5가 아니라 4",""],"t":"두 번째 인자는 '채울 개수'가 아니라 '최종 전체 길이'입니다."},"165":{"k":["`LTRIM(문자, 제거문자)` = **왼쪽**만 제거 → `ABCxx`"],"w":["양쪽 제거는 TRIM","","오른쪽 제거는 RTRIM","LTRIM이 왼쪽 x를 제거함"],"t":"L = Left, R = Right. 이름에 방향이 들어 있습니다."},"166":{"k":["INITCAP = **단어마다 첫 글자만** 대문자, 나머지 소문자"],"w":["전체 대문자는 UPPER","전체 소문자는 LOWER","","단어마다 첫 글자를 바꿈. 두 번째 단어도 대문자"],"t":"INIT(첫) + CAP(대문자). 단어 단위라는 점을 놓치지 마세요."},"438":{"k":["SUBSTR 음수 시작 = **뒤에서** 센 위치부터 → `David`","LENGTH 공백 포함 = 11","REPLACE 3번째 인자 생략 → 찾은 문자열 **삭제**"],"w":["","음수 시작은 뒤에서 5번째부터라 David","LENGTH는 공백 포함 11, REPLACE는 World를 지움","REPLACE 세 번째 인자를 생략하면 World가 삭제됨"],"t":"REPLACE에서 바꿀 값을 안 주면 '빈 문자열로 바꾸기' = 삭제입니다."},"584":{"k":["UPPER = 전부 대문자, LOWER = 전부 소문자"],"w":["","UPPER·LOWER 결과가 뒤바뀜","첫 글자만 대문자는 INITCAP","LOWER는 소문자로 바꿈"],"t":"문자 함수 기초 3종: UPPER, LOWER, INITCAP."},"585":{"k":["SUBSTR 길이 생략 → 시작 위치부터 **끝까지** → `CDEFG`"],"w":["앞 3글자가 아니라 3번째부터 끝까지","길이 생략은 한 글자가 아니라 끝까지","4번째부터 센 값",""],"t":"SUBSTR('ABCDEFG', 3)는 'C부터 끝까지'. 두 번째 인자가 시작 위치라는 걸 잊지 마세요."},"586":{"k":["SUBSTR 음수 시작: 뒤에서 3번째(E)부터 2글자 → `EF`"],"w":["뒤에서 4번째부터 센 값","뒤에서 2번째부터 센 값","","앞에서 3번째부터 센 값"],"t":"음수 시작이어도 읽는 방향은 왼쪽→오른쪽입니다. 시작점만 뒤에서 셉니다."},"587":{"k":["RTRIM = **오른쪽** 공백 제거 → `SQLD!`"],"w":["RTRIM이 오른쪽 공백을 지움","","앞에 공백이 생기지 않음","연결 순서는 바뀌지 않음"],"t":"TRIM 계열은 두 번째 인자를 생략하면 공백을 지웁니다."},"588":{"k":["TRIM은 **양끝** 공백만 제거, 가운데 공백 유지 → `A B` = 3글자"],"w":["","가운데 공백까지 지운 줄 착각한 값","TRIM 전 원래 길이","가운데 공백까지 지운 값"],"t":"가운데 공백까지 지우려면 REPLACE(문자, ' ', '')를 써야 합니다."},"589":{"k":["`REPLACE(문자, '-', '')` = 하이픈을 빈 문자열로 → 삭제 효과 → `20261114`"],"w":["하이픈이 지워짐","Oracle에서 ''는 NULL이지만 REPLACE 결과는 NULL이 아님","공백이 아니라 빈 문자열로 바뀜",""],"t":"날짜 문자열에서 구분자를 없애는 전형적인 사용법입니다."},"590":{"k":["`INSTR(문자, 찾을, 시작위치, n번째)` → 1번째부터 찾은 **두 번째 A** = 4"],"w":["첫 번째 A 위치","세 번째 A 위치","","N의 위치"],"t":"BANANA: B1 A2 N3 A4 N5 A6. 위치를 적어 놓고 세면 실수가 없습니다."},"591":{"k":["RPAD = **오른쪽**을 채워 전체 길이 맞춤 → `700`"],"w":["왼쪽 채우기는 LPAD","","전체 3자리로 채워짐","자리수가 모자람"],"t":"LPAD('7',3,'0')이면 007. 사번 앞자리 0 채우기는 LPAD를 씁니다."},"592":{"k":["Oracle CONCAT은 **인자 2개**만 → 중첩하면 여러 개 연결 가능 → `ABC`"],"w":["","중첩하면 각 CONCAT이 인자 2개라 정상","C까지 붙음","공백이 들어가지 않음"],"t":"CONCAT('A','B','C')처럼 3개를 바로 넣으면 Oracle에서 오류입니다. 중첩은 괜찮아요."},"593":{"k":["ASCII('A') = 65, CHR(66) = B","소문자 a = 97"],"w":["CHR(66)은 대문자 B","A는 65, 66이 B","97은 소문자 a",""],"t":"대문자 A=65, 소문자 a=97. 두 숫자만 기억하면 나머지는 순서대로 세면 됩니다."},"594":{"k":["LTRIM 두 번째 인자 = 제거할 **문자 집합** → 왼쪽부터 x·y가 아닌 문자가 나올 때까지 제거 → `SQLxy`"],"w":["x와 y를 모두 제거해야 함","LTRIM은 왼쪽만 제거","","오른쪽 제거는 RTRIM"],"t":"'xy'는 문자열이 아니라 x 또는 y라는 집합입니다. 'xyx' 세 글자가 다 지워져요."},"595":{"k":["Oracle `+`는 **숫자 연산** → 'A'를 숫자로 못 바꿔 오류 (ORA-01722)","문자 연결은 `||` 또는 CONCAT"],"w":["|| 연결은 정상","","CONCAT은 정상","숫자 1은 문자로 자동 변환돼 정상"],"t":"SQL Server는 +로 문자를 연결합니다. 'Oracle에서'라는 조건을 꼭 확인하세요."},"1087":{"k":["LTRIM은 **왼쪽만** → `LTRIM('xxSQLxx','x')` = `SQLxx`","양쪽은 `TRIM('x' FROM 'xxSQLxx')`"],"w":["LENGTH는 공백 포함 10. 맞음","4번째(D)부터 3글자 Dev. 맞음","ORACLE에서 A는 3번째. 맞음",""],"t":"보기마다 직접 계산해 보는 유형입니다. 그중 TRIM 방향 함정이 가장 자주 나와요."},"1088":{"k":["Oracle `||`는 NULL을 **빈 문자열처럼** 처리 → `SQLD`","SQL Server `+` 연결은 NULL이 섞이면 NULL (CONCAT 함수는 NULL 무시)"],"w":["","Oracle ||는 NULL을 무시해 NULL이 되지 않음","공백이 생기지 않음","정상 문법"],"t":"산술 연산(+, -)에 NULL이 섞이면 NULL이지만, Oracle 문자열 연결(||)은 예외입니다."},"1193":{"k":["SUBSTR 위치는 **1부터** 셈: Busan의 5번째 = n → 공백 포함 4글자 `n Ha`"],"w":["7.455를 소수 둘째 자리로 반올림하면 7.46. 맞음","DATA는 4글자. 맞음","UPPER는 대문자. 맞음",""],"t":"시작 위치를 하나 앞당겨 센 결과(an H)를 보기로 넣는 함정입니다. 글자 위에 번호를 써 보세요."},"1203":{"k":["RTRIM = 오른쪽에서 지정 문자를 **연속된 만큼 모두** 제거 → `abcd`"],"w":["오른쪽 x가 지워지고 앞부분이 남음","RTRIM이 적용되어 바뀜","","x를 하나만 남기지 않고 모두 지움"],"t":"TRIM 계열은 '한 글자만'이 아니라 다른 문자가 나올 때까지 계속 지웁니다."},"1271":{"k":["단일 행 함수는 SELECT·**WHERE·GROUP BY**·ORDER BY 어디서나 사용 가능","예: `GROUP BY SUBSTR(입사일, 1, 4)`"],"w":["행마다 결과 하나. 맞는 설명","","함수 중첩 가능. 맞는 설명","여러 인자를 받을 수 있음. 맞는 설명"],"t":"단일 행 함수를 못 쓰는 곳은 거의 없습니다. 쓸 수 없다는 보기를 의심하세요."},"1375":{"k":["SUBSTR 길이 생략 = 끝까지, 음수 시작 = 뒤에서","①②③ = `fgh`, ④는 2글자 `fg`"],"w":["6번째부터 끝까지 fgh","뒤에서 3번째부터 끝까지 fgh","f의 위치(6)부터 3글자 fgh",""],"t":"INSTR 결과를 SUBSTR 시작 위치로 넣는 중첩 문제는 안쪽 함수부터 숫자로 바꿔 놓고 푸세요."},"1420":{"k":["TRIM 계열은 문자 **제거**, REPLACE는 **치환** → `YYDATAYY`"],"w":["왼쪽 z 제거 → DATA","오른쪽 z 제거 → DATA","양쪽 z 제거 → DATA",""],"t":"REPLACE에 세 번째 인자가 있으면 지우는 게 아니라 바꿉니다."},"1451":{"k":["문자열 안 작은따옴표는 **두 번** 써서 표현: `'It''s'` → It's"],"w":["''는 작은따옴표 한 글자로 해석됨","","따옴표가 사라지지 않음","정상 문법"],"t":"작은따옴표 이스케이프는 SQL 공통 규칙입니다. 백슬래시를 쓰지 않아요."},"1574":{"k":["LENGTH('abcdefg') = 7 → 7 − 2 = **5번째부터 끝까지** → `efg`"],"w":["3번째부터 센 값","4번째부터 센 값","","길이 생략 시 끝까지라 한 글자가 아님"],"t":"중첩 함수는 안쪽부터 숫자로 바꾸세요. SUBSTR('abcdefg', 5)로 바꾸면 끝."},"167":{"k":["`ROUND(n, 2)` = 소수 둘째 자리까지 → 1234.57","`ROUND(n, -2)` = 십의 자리에서 반올림 → 백 단위 → 1200"],"w":["","ROUND는 반올림이라 .567 → .57","-2 자리는 34를 반올림해 1200","자릿수가 반대로 적용됨"],"t":"음수 자릿수는 소수점 왼쪽으로 갑니다. -1 일의 자리, -2 십의 자리를 0으로 만들어요."},"168":{"k":["TRUNC = **버림**","`TRUNC(n, -2)` → 1200, 자릿수 생략 → 소수 이하 버림 → 1234"],"w":["TRUNC는 버림이라 1300이 될 수 없음","자릿수 생략 시 소수 이하를 버려 1234","TRUNC는 버림이라 1300이 아님",""],"t":"ROUND와 TRUNC의 결과를 같이 묻는 문제는 TRUNC부터 계산하면 더 쉽습니다(무조건 버림)."},"169":{"k":["CEIL = 크거나 같은 **최소 정수**(올림), FLOOR = 작거나 같은 **최대 정수**(내림)","음수: CEIL(-3.2) = -3, FLOOR(-3.2) = -4"],"w":["CEIL과 FLOOR를 서로 바꾼 값","","FLOOR(-3.2)는 더 작은 -4","CEIL(-3.2)는 더 큰 -3"],"t":"수직선을 그리세요. CEIL은 오른쪽(큰 쪽), FLOOR는 왼쪽(작은 쪽)으로 갑니다."},"170":{"k":["MOD(17,5) = 나머지 2, POWER(3,2) = 9, ABS(-7) = 7"],"w":["MOD는 2, POWER는 9, ABS는 양수 7","POWER(3,2)는 3×3 = 9","","17 ÷ 5의 나머지는 2"],"t":"POWER(3,2)를 3×2로 계산하는 실수가 함정입니다."},"171":{"k":["날짜 − 날짜 = **일수**(숫자)","10/14 → 11/14 = 31일 (10월은 31일까지)"],"w":["","10월은 31일까지라 30이 아님","월 수가 아니라 일수를 반환","날짜끼리 빼기는 정상"],"t":"월마다 일수가 다릅니다. 30으로 대충 계산하지 마세요."},"172":{"k":["Oracle 날짜 연산 단위 = **일**","1/24 = 1시간, 1/24/60 = 1분"],"w":["하루 뒤는 +1","24일 뒤는 +24","1분 뒤는 +1/24/60",""],"t":"1/24는 하루를 24로 나눈 것. 그래서 1시간입니다."},"439":{"k":["자릿수 -1 = **일의 자리**에서 반올림/버림","ROUND(15.58,-1) = 20, TRUNC(15.58,-1) = 10, MOD(11,3) = 2, SIGN(-3) = -1"],"w":["","자릿수 -1을 소수 첫째 자리로 착각한 값","TRUNC는 버림이라 10, SIGN(-3)은 -1","ROUND(15.58,-1)은 20, MOD(11,3)은 2"],"t":"네 함수를 한 줄에 묻는 문제는 각각 따로 계산하고, 확실한 값부터 보기를 지워 가세요."},"596":{"k":["ROUND(45.926, 1): 둘째 자리 2 → 내림 → 45.9","TRUNC(45.926, 1) → 45.9"],"w":["","둘째 자리가 2라 반올림해도 45.9","TRUNC(…, 1)은 소수 첫째 자리까지","자릿수 1이 적용되어 정수가 아님"],"t":"ROUND는 바로 다음 자리 숫자만 봅니다. 그 뒤 숫자(6)는 상관없어요."},"597":{"k":["자릿수 생략 = 0 → 정수","ROUND(45.926) = 46, TRUNC(45.926) = 45"],"w":["자릿수 생략은 정수 단위","ROUND는 반올림이라 46","TRUNC는 버림이라 45",""],"t":"ROUND와 TRUNC의 기본 자릿수는 0입니다."},"598":{"k":["Oracle ROUND(-2.5) = **-3** (절댓값 기준 반올림)","CEIL(-2.5) = -2, FLOOR(-2.5) = -3"],"w":["CEIL과 FLOOR가 뒤바뀜","Oracle ROUND(-2.5)는 -3","","ROUND와 CEIL 값이 맞지 않음"],"t":"음수 반올림은 0에서 멀어지는 쪽입니다. -2.5 → -3."},"599":{"k":["MOD(10,3) = 1, MOD(10,5) = 0","나누는 수보다 작으면 나머지는 그대로: MOD(3,10) = 3"],"w":["MOD(10,5)는 0, MOD(3,10)은 3","","MOD(10,3)은 1","MOD(3,10)은 3"],"t":"3 ÷ 10은 몫 0, 나머지 3. 작은 수를 큰 수로 나누면 자기 자신이 나머지입니다."},"600":{"k":["SIGN: 양수 1, 0은 0, 음수 -1"],"w":["","SIGN은 값이 아니라 부호만 반환","SIGN(0)은 0","SIGN은 기호가 아니라 숫자를 반환"],"t":"SIGN은 결과가 1, 0, -1 세 가지뿐입니다."},"601":{"k":["날짜 + 1 = **하루 뒤** → 2026-11-15"],"w":["+1이 적용되어 바뀜","1은 연이 아니라 일 단위","1은 월이 아니라 일 단위",""],"t":"월을 더하려면 ADD_MONTHS를 씁니다. 날짜 + 숫자는 언제나 '일'."},"602":{"k":["3/24일 = **3시간** → 09:00 + 3시간 = 12:00"],"w":["3/24는 3분이 아니라 3시간","30분이 아님","","기준 시각 09:00에 더해야 함"],"t":"분을 더하려면 /24/60까지 나눠야 합니다. 3/24는 시간 단위예요."},"603":{"k":["문자 → 날짜 = **TO_DATE**(문자, 포맷)","날짜/숫자 → 문자 = TO_CHAR"],"w":["TO_CHAR는 날짜·숫자를 문자로 바꿈","","TO_NUMBER는 숫자 변환","CAST AS NUMBER는 숫자 변환"],"t":"TO_ 뒤 단어가 '결과 타입'입니다. TO_DATE는 날짜를 만들어요."},"604":{"k":["`TO_CHAR(숫자, '999,999,999')` → 천 단위 콤마, 남는 자리는 앞쪽 공백"],"w":["","포맷이 적용돼 콤마가 들어감","Oracle 포맷 기호 ,는 콤마로 표시","정상 문법"],"t":"9는 '숫자 자리', 0은 '빈 자리를 0으로 채움'. 999와 000의 차이도 함께 기억하세요."},"605":{"k":["날짜 TRUNC(날짜, 'MM') = **그 달 1일**","'YYYY' → 1월 1일, 생략 → 그날 00:00"],"w":["월말이 아니라 월초","연 단위(YYYY)로 자른 결과","자르지 않은 원래 날짜",""],"t":"날짜 TRUNC는 '해당 단위의 시작점'으로 내립니다."},"606":{"k":["ABS(-7) = 7, POWER(2,3) = 8 → **15**"],"w":["7 + 8을 잘못 계산한 값","부호 처리를 잘못한 값","","POWER(2,3)은 8 (2×3이 아님)"],"t":"POWER(a, b)는 a를 b번 곱합니다."},"607":{"k":["날짜 ± 숫자 = 날짜, 날짜 − 날짜 = 일수","**날짜 + 날짜 = 오류**"],"w":["날짜 + 숫자 = 날짜. 맞는 설명","","날짜 + 1/24 = 1시간 뒤. 맞는 설명","날짜 − 날짜 = 일수. 맞는 설명"],"t":"날짜끼리 '빼기'만 의미가 있습니다. 더하기는 의미가 없어 오류예요."},"1089":{"k":["ROUND(45.678,1) = 45.7, TRUNC(45.678,-1) = 40","CEIL(-2.3) = -2, FLOOR(-2.3) = -3"],"w":["ROUND(45.678,1)은 45.7","TRUNC(-1)은 40이고 CEIL·FLOOR가 뒤바뀜","ROUND는 반올림이라 45.7",""],"t":"CEIL·FLOOR는 음수에서 정확히 반대로 생각하기 쉽습니다. 수직선을 떠올리세요."},"1090":{"k":["날짜 − 날짜 = 일수 숫자 → 14 − 1 = **13**"],"w":["결과 단위는 주가 아니라 일수 숫자","14 − 1은 13","","날짜끼리 빼기는 정상"],"t":"1일부터 14일까지 '며칠 차이'는 13일입니다. 날짜 수(14개)와 헷갈리지 마세요."},"1181":{"k":["날짜 포맷: **MM = 월**, **MI = 분**, HH24 = 24시간제 시","`'HH24:MM'` → 시:월 → `09:11`"],"w":["분을 보려면 MI를 써야 함. MM은 월","05는 초(SS) 값","HH24는 24시간제라 9시는 09",""],"t":"MM/MI 혼동은 단골 함정입니다. 분(Minute)은 MI, 월(Month)은 MM."},"1205":{"k":["FLOOR(-2.3) = **-3** (작거나 같은 최대 정수)","CEIL(-2.7) = -2, TRUNC(-2.7) = -2, ROUND(-2.3) = -2"],"w":["CEIL(-2.7)은 큰 쪽 정수 -2","ROUND(-2.3)은 -2","TRUNC(-2.7)은 소수점만 버려 -2",""],"t":"음수에서 TRUNC는 0 쪽으로, FLOOR는 더 작은 쪽으로 갑니다. 둘의 차이가 여기서 드러나요."},"1219":{"k":["MIN(COL1) = 숫자 9","MAX(TO_CHAR(COL1)) = **문자 비교** → '9' > '50' > '100' → '9'","숫자 + 문자 → 묵시적 변환 → 9 + 9 = **18**"],"w":["숫자 + 문자열 숫자는 묵시적 형변환으로 계산됨","MAX(TO_CHAR)를 숫자 최대 100으로 착각한 값","MAX(TO_CHAR)를 50으로 착각한 값",""],"t":"문자열 비교는 첫 글자부터 사전순입니다. '9'가 '100'보다 큽니다."},"1314":{"k":["숫자 / 0 → **오류**(ORA-01476)","0 / 숫자 → 0","숫자 / NULL → **NULL**"],"w":["(1)은 0으로 나누기라 NULL이 아니라 오류","(1)은 오류","","(2)는 0 / 300 = 0"],"t":"NULL 연산은 NULL이지만 0으로 나누기는 오류입니다. 둘을 구분하세요."},"1338":{"k":["CEIL(5.01) = 6 (올림), ROUND(5.5) = 6, FLOOR(5.99) = 5 (내림)"],"w":["","CEIL은 소수가 조금이라도 있으면 올려 6","ROUND(5.5)는 반올림해 6","FLOOR(5.99)는 내림이라 5"],"t":"CEIL은 0.01만 있어도 올립니다. 반올림처럼 생각하면 틀려요."},"1398":{"k":["날짜 TRUNC(…, 'MM') = 그달 1일","날짜 ROUND(…, 'MM') = **16일부터** 다음 달 1일로"],"w":["","ROUND는 16일 이후면 다음 달 1일","TRUNC는 1일로 자름","전월 말일이 아님"],"t":"월 반올림 기준은 16일입니다. 15일까지는 이번 달 1일, 16일부터는 다음 달 1일."},"1402":{"k":["문자열 BETWEEN '2025-12' AND '2026-04' → 5개월","EXTRACT(MONTH)로 1월·4월 제외 → **3행**"],"w":["한 달을 빠뜨린 값","","1월이나 4월을 포함한 값","제외 조건을 무시한 값"],"t":"YYYY-MM 형식 문자열은 사전순 = 시간순이라 BETWEEN이 날짜처럼 작동합니다."},"1454":{"k":["TRUNC(987.654, -2) = 900 (십의 자리 이하 버림)","TRUNC(987.654, 1) = 987.6"],"w":["","TRUNC는 버림이라 반올림 결과(1000, 987.7)가 아님","-2는 백 단위만 남김. 980은 -1","1은 987.6 (버림)"],"t":"TRUNC는 숫자를 절대 키우지 않습니다. 원래 값보다 큰 보기는 바로 지우세요."},"1487":{"k":["BETWEEN은 **양 끝 포함** → 15일 00:00:00 행까지 포함","하루만 고르려면 `>= 14일 AND < 15일` 반열린 구간"],"w":["반열린 구간으로 정확히 하루. 정상","","TRUNC로 시각을 지우고 비교. 정상","날짜를 문자열로 바꿔 비교. 정상"],"t":"시각이 포함된 DATE에 BETWEEN을 쓰면 끝날 자정이 딸려 들어옵니다. 실무에서도 흔한 버그예요."},"1493":{"k":["ROUND(145.5, -1) = 150 (일의 자리 반올림)","ROUND(-3.456, 1) = -3.5","TRUNC(3.99) = **3** (버림)"],"w":["(나)도 맞음","(다) TRUNC(3.99)는 3","(가)도 맞고 (다)는 틀림",""],"t":"TRUNC는 반올림하지 않습니다. 3.99도 3이에요."},"1494":{"k":["월 = **MM**, 분 = **MI**","SUBSTR(5,2) · EXTRACT(MONTH) · TO_CHAR(…,'MM') 모두 11"],"w":["5번째부터 2글자 = 11","EXTRACT(MONTH) = 11","","TO_CHAR(…, 'MM') = 11"],"t":"시간 정보가 없는 날짜에 MI를 쓰면 00이 나옵니다."},"1585":{"k":["CEIL(6.1) = 7, FLOOR(7.9) = 7, ROUND(6.5) = 7, TRUNC(7.5) = 7"],"w":["","FLOOR(7.9)는 7, TRUNC(7.5)는 7","CEIL은 올림이라 7, ROUND(6.5)는 7","ROUND(6.5)는 7"],"t":"네 함수 결과가 모두 같게 만든 문제입니다. 하나씩 계산하면 쉽게 풀려요."},"1620":{"k":["MAX(A) = 30","MIN(TO_CHAR(B)) = 문자 비교 → '100' < '80' < '90' → '100'","30 + '100' → 묵시적 변환 → **130**"],"w":["","MIN(TO_CHAR)를 숫자 최소 80으로 착각","MIN(TO_CHAR)를 90으로 착각","묵시적 형변환으로 정상 실행"],"t":"TO_CHAR로 감싼 MIN/MAX는 문자 정렬 기준입니다. '1'로 시작하는 '100'이 가장 작아요."},"174":{"k":["NVL(COMM, 0)으로 NULL → 0 후 SUM","30번: 300 + 500 + 1400 + 0 + 0 + 0 = **2200**"],"w":["","COMM 값 중 하나를 빠뜨린 합","실제 합보다 큰 값","NVL로 NULL을 0으로 바꾸고 SUM도 NULL을 제외하니 NULL이 아님"],"t":"SUM은 원래 NULL을 무시하므로 SUM(COMM)도 2200입니다. NVL이 결과를 바꾸는 건 COUNT·AVG 쪽이에요."},"175":{"k":["NVL2(A, B, C): A가 **NULL이 아니면 B**, NULL이면 C","COMM = 0은 NULL이 아님 → Y"],"w":["","0은 NULL이 아니라 두 번째 인자 Y","NVL2는 지정한 두 값 중 하나를 반환","0은 NULL이 아님"],"t":"0과 NULL은 다릅니다. TURNER(COMM=0)는 이 점을 묻는 단골 예시예요."},"176":{"k":["NULLIF(A, B): **같으면 NULL**, 다르면 A"],"w":["NULLIF는 두 번째 값을 반환하지 않음","다를 때는 첫 번째 값을 반환","같을 때는 NULL",""],"t":"NULLIF = '같으면(IF) NULL'. 이름 그대로입니다."},"177":{"k":["COALESCE = 왼쪽부터 **처음 NULL이 아닌 값**"],"w":["NULL이 아닌 값(3)이 있음","","4보다 앞에 있는 3이 먼저","합계가 아니라 첫 번째 NULL 아닌 값"],"t":"COALESCE는 인자를 몇 개든 받을 수 있습니다. NVL은 2개만."},"247":{"k":["NULL이 섞인 **산술 연산 = NULL**","KING의 COMM은 NULL → 5000 + NULL = NULL"],"w":["COMM이 NULL이라 더하면 NULL","NULL은 0이 아님","","NULL 연산은 오류가 아니라 NULL"],"t":"급여 + 커미션 계산엔 NVL이 꼭 필요합니다. 시험이 그걸 확인하는 문제예요."},"248":{"k":["`SAL + NVL(COMM, 0)` → NULL을 0으로 바꾼 뒤 더함 → 5000"],"w":["NVL로 NULL을 0으로 바꿔 NULL이 아님","SAL 5000에 0을 더함","정상 문법",""],"t":"247번과 짝 문제입니다. NVL 하나로 NULL과 5000이 갈립니다."},"608":{"k":["SUM은 NULL 무시 → 850","COUNT(NVL(AMT, 0)) → NULL이 0이 되어 **6건** 모두 셈"],"w":["","NVL로 NULL이 0이 되어 COUNT는 6","SUM은 NULL이 아님","합계가 1000이 아님 (100+200+300+200+50)"],"t":"COUNT(컬럼)은 NULL을 빼고 셉니다. NVL로 감싸면 NULL이 사라져 모든 행이 세어져요."},"609":{"k":["NVL(STATUS, 'NEW'): NULL이면 'NEW'로 치환"],"w":["NVL로 치환되어 NULL이 아님","정상 문법","4번 행의 STATUS는 NULL",""],"t":"행 하나만 고르는 문제는 해당 행의 값만 확인하면 됩니다."},"610":{"k":["`STATUS <> 'DONE'`만 쓰면 NULL 행은 UNKNOWN → 제외","NVL(STATUS, 'X')로 NULL을 값으로 바꾸면 포함 → CANCEL + NULL = **2건**"],"w":["NVL 없이 썼을 때의 결과","DONE이 아닌 행은 2건","","행 수가 맞지 않음"],"t":"부정 조건(<>, NOT IN)은 NULL 행을 빠뜨립니다. NULL까지 포함하려면 NVL이나 OR IS NULL을 쓰세요."},"611":{"k":["NVL2(NULL, 'A', 'B') = B","NVL2(0, 'A', 'B') = A (0은 NULL 아님)"],"w":["NULL과 0의 결과가 뒤바뀜","","0은 NULL이 아니라 A","NVL2는 NULL을 반환하지 않음"],"t":"NVL2의 두 번째 인자는 'NULL이 아닐 때' 값입니다. 순서가 직관과 반대라 헷갈려요."},"612":{"k":["NULLIF(5,5) = NULL, NULLIF(3,4) = 3","COALESCE → 처음 NULL 아닌 값 **3**"],"w":["","NULLIF(5, 5)는 같아서 NULL","9보다 앞에 3이 있음","3이 NULL이 아님"],"t":"중첩 함수는 안쪽부터 값으로 바꾼 뒤 바깥 함수를 적용하세요."},"613":{"k":["인자 2개 **COALESCE(A, B) = NVL(A, B)**"],"w":["NULLIF는 A와 B가 같으면 NULL","DECODE(A, B, NULL)은 A가 B와 같으면 NULL","NVL2(A, B, A)는 A가 NULL이 아니면 B를 반환해 다름",""],"t":"NVL(A,B) ≡ COALESCE(A,B) ≡ NVL2(A, A, B) ≡ CASE WHEN A IS NULL THEN B ELSE A END."},"614":{"k":["AVG(AMT) = 850 / 5 = 170 (NULL 행 제외)","AVG(NVL(AMT,0)) = 850 / 6 ≈ 141.67"],"w":["NVL 후엔 분모가 6이라 값이 달라짐","두 값이 뒤바뀜","","합계지 평균이 아님"],"t":"AVG에서 NVL은 분모를 바꿉니다. 'NULL을 0으로 보고 평균'인지 '값 있는 것만 평균'인지 확인하세요."},"615":{"k":["NULL 치환: Oracle **NVL** / SQL Server **ISNULL** / MySQL IFNULL"],"w":["NVL은 Oracle 함수","","IFNULL은 MySQL 함수","NULLIF는 같으면 NULL을 돌려주는 다른 기능"],"t":"DBMS별 이름 차이를 묻는 문제입니다. 공통으로 쓰려면 COALESCE가 표준이에요."},"616":{"k":["문자 비교는 **대소문자 구분** → 'A' ≠ 'a' → NULLIF는 첫 번째 값 A"],"w":["","대소문자가 달라 같은 값이 아님","다를 때는 첫 번째 값을 반환","정상 문법"],"t":"Oracle 데이터 값 비교는 대소문자를 구분합니다(키워드·식별자는 구분 안 함)."},"617":{"k":["대상 행이 **0건**이면 SUM(…)은 NULL","NVL(SUM(COMM), 0) = 0, SUM(NVL(COMM, 0)) = NULL → 다름"],"w":["NULL이 섞여 있어도 행이 있으면 둘 다 같음","모두 NULL이어도 둘 다 0","0건이면 결과가 다름",""],"t":"행이 없으면 안쪽 NVL은 적용할 대상조차 없습니다. 바깥 NVL만 결과를 0으로 바꿀 수 있어요."},"1047":{"k":["기준 SQL: COMM이 NULL이면 SAL, 아니면 SAL + COMM → 1200, 1500, 1200","`NVL(SAL + COMM, 0)`은 나(COMM NULL)가 **0**이 됨"],"w":["COMM이 NULL이면 SAL만 더하는 같은 식","SAL + COMM이 NULL이면 SAL로 대체해 같음","CASE로 같은 분기를 표현해 같음",""],"t":"NVL을 어디에 거느냐가 핵심입니다. COMM에 걸어야지 합계 전체에 걸면 의미가 바뀝니다."},"1048":{"k":["NULLIF(A, B): 같으면 NULL, 다르면 A (A가 NULL이면 NULL)","행별: 1행 NULL→9, 2행 2, 3행 NULL→9 → 합 **20**"],"w":["NULLIF 결과를 잘못 계산한 값","","C만 세 번 더한 값","행 하나를 빠뜨린 값"],"t":"표가 나오면 행마다 안쪽 함수 결과를 옆에 적어 두고 바깥 함수를 적용하세요."},"1091":{"k":["COALESCE(커미션, 급여*0.1, 0): 행별로 처음 NULL 아닌 값","A 100, B 0(급여도 NULL → 급여*0.1도 NULL), C 50 → **150**"],"w":["","C의 50만 더한 값","A의 급여 전체를 더한 값","COALESCE가 0까지 대비해 NULL 아님"],"t":"NULL * 0.1도 NULL입니다. B행은 세 번째 인자 0까지 내려가요."},"1149":{"k":["COALESCE(A,B) = NVL(A,B) = CASE WHEN A IS NULL THEN B ELSE A END","NVL2(A, B, A)는 A가 NULL이 **아니면 B** → 다른 결과"],"w":["10, 5, 7, 3으로 나머지와 같음","10, 5, 7, 3으로 나머지와 같음","10, 5, 7, 3으로 나머지와 같음",""],"t":"NVL과 같은 NVL2는 NVL2(A, A, B)입니다. 인자 순서를 바꾼 함정이에요."},"1152":{"k":["AVG(NVL(금액,0)) = 4000/4 = 1000 (0도 분모에)","AVG(금액) = 4000/2 = 2000 (NULL 제외)"],"w":["A와 B 값이 뒤바뀜","A는 0을 포함해 1000","B는 NULL을 빼고 2000",""],"t":"NVL로 감싼 쪽이 항상 같거나 더 작은 평균이 나옵니다(0이 분모에 들어가니까)."},"1178":{"k":["NVL2(식, 값1, 값2): 식이 NULL **아니면 값1** → NVL2('A','B','C') = B"],"w":["같으면 NULL. 맞음","처음 NULL 아닌 값 X. 맞음","","NULL이면 대체값 Z. 맞음"],"t":"NVL2의 '2'는 결과 후보가 두 개라는 뜻입니다. 첫 번째 후보가 'NULL 아닐 때'."},"1195":{"k":["NULLIF('A','A') = **NULL** (같으면 NULL)"],"w":["처음 NULL 아닌 값 'A'","식이 NULL이라 세 번째 값 'B'","","첫 인자 'B'가 NULL이 아니라 'B'"],"t":"NULL을 '만들어 내는' 함수는 NULLIF뿐입니다."},"1242":{"k":["`CASE WHEN COL1 = 'A' THEN NULL ELSE COL1 END` = **NULLIF(COL1, 'A')**"],"w":["NVL은 NULL을 'A'로 바꾸는 식","COALESCE도 NULL을 'A'로 바꾸는 식","","NVL2는 값이 있으면 'A'를 반환"],"t":"NULLIF의 CASE 정의를 그대로 외워 두면 바로 맞힙니다."},"1245":{"k":["COALESCE(A, 10*B, 0): 1행 A=10, 2행 10×5=50, 3행 10×NULL=NULL → 0"],"w":["2행은 10 × 5 = 50","3행은 0까지 내려가 NULL이 아님","1행은 A = 10",""],"t":"식 인자(10*B)도 NULL이면 다음 인자로 넘어갑니다."},"1290":{"k":["NVL(C1,0)*2 + C2: 1행 0*2+10 = 10, 2행 30","3행은 C2가 NULL → 산술 결과 **NULL**"],"w":["1행은 NVL로 C1이 0이 되어 10","3행은 C2가 NULL이라 NULL","","C1 NVL 결과 계산이 틀림"],"t":"NVL은 감싼 컬럼에만 효과가 있습니다. 다른 컬럼의 NULL은 그대로 전파돼요."},"1337":{"k":["COALESCE = 왼쪽부터 처음 NULL 아닌 값 **하나** → 'Q'"],"w":["NULL 아닌 값이 있음","값을 이어 붙이지 않음","앞쪽 Q가 먼저",""],"t":"COALESCE는 연결 함수가 아닙니다. 하나만 돌려줘요."},"1425":{"k":["SAL + NVL(COMM, 0) → 1100 + 2000 + 1500 = **4600**","NVL 없이 SAL + COMM이면 B가 NULL → SUM 2600"],"w":["NVL 없이 B 행이 NULL이 되어 빠진 값","COMM을 빼고 SAL만 합한 값","NVL로 NULL이 없어 결과가 있음",""],"t":"SUM(SAL + COMM)은 '행 단위로 먼저 더하고' 합칩니다. 한쪽이 NULL이면 그 행 전체가 빠져요."},"1441":{"k":["㉠ A, ㉡ A(NULL이니 세 번째), ㉢ A(다르면 첫 값), ㉣ B"],"w":["","㉣은 'B'라 ㉠과 다름","㉣은 'B'라 ㉡과 다름","㉢은 'A', ㉣은 'B'"],"t":"네 함수를 한 번에 정리하는 문제입니다. 각 결과를 옆에 적고 같은 것끼리 묶으세요."},"1448":{"k":["**0도 NULL이 아닌 값** → COALESCE(NULL, 0, NULL, 4) = 0"],"w":["","0이 NULL 아닌 값이라 0 반환","앞쪽 0이 먼저","정상 문법"],"t":"0과 NULL은 다르다. NULL 함수 문제의 절반은 이 한 줄입니다."},"1455":{"k":["COALESCE(NULL, 0) = **0**","NULLIF(2,2), NVL2(NULL,'A',NULL), NVL(NULL,NULL)은 모두 NULL"],"w":["같은 값이라 NULL","","식이 NULL이라 세 번째 값 NULL","대체값도 NULL이라 NULL"],"t":"대체값 자리에 NULL을 넣으면 결과도 NULL이 될 수 있습니다."},"1473":{"k":["NVL2(식, 값1, 값2): 식이 NULL **아니면 값1**, NULL이면 **값2**","인자 3개 필수"],"w":["SAL이 NULL이면 세 번째 값 0을 반환","1은 NULL이 아니라 a를 반환","NVL2는 인자 3개가 필요",""],"t":"NVL은 2개, NVL2는 3개. 이름의 숫자와 인자 수가 다르니 주의하세요."},"1488":{"k":["COALESCE(V1, V2, V3): 30, 10, NULL","바깥 NVL(…, -1)로 3행 → **-1**"],"w":["3행은 NVL로 -1","마지막 인자(V3)를 먼저 본 값","","1·2행 값이 뒤바뀜"],"t":"COALESCE는 '왼쪽부터'. 오른쪽부터 보는 실수를 노린 보기가 있습니다."},"1548":{"k":["NVL은 **COMM에만** 적용 → SAL이 NULL이면 결과 NULL"],"w":["","COMM이 있으면 COMM + SAL. 맞는 설명","NVL의 두 인자는 타입이 호환돼야 함. 맞는 설명","COMM이 NULL이면 0 + SAL. 맞는 설명"],"t":"NVL 문제는 '어느 컬럼을 감쌌나'부터 확인하세요."},"1631":{"k":["NULL → 0: NVL(P,0), NVL2(P,P,0), COALESCE(P,0)","**NULLIF(P,0)**은 오히려 0을 NULL로 바꿈"],"w":["NULL을 0으로 바꿈","","NULL이면 0, 아니면 PRICE","NULL이면 0"],"t":"NULLIF는 NULL을 '없애는' 게 아니라 '만드는' 함수입니다. 0으로 나누기 방지에 자주 써요."},"178":{"k":["CASE는 **위에서부터 처음 맞는** 조건의 결과","'M' = 1500 이상 3000 미만: BLAKE, CLARK, JONES, ALLEN, TURNER → **5**"],"w":["1500~2999 중 일부만 센 값","TURNER(1500)를 빠뜨린 값. 1500 이상이라 포함","","3000 이상은 이미 'H'라 포함되지 않음"],"t":"두 번째 WHEN은 '첫 조건을 통과하지 못한 행'만 봅니다. 그래서 자동으로 3000 미만이 돼요."},"179":{"k":["DECODE: 일치하는 값이 없고 **기본값도 없으면 NULL**"],"w":["","30은 20과 같지 않음","DECODE는 비교 대상을 그대로 반환하지 않음","기본값 생략은 허용되고 NULL을 반환"],"t":"DECODE 인자 개수가 짝수면 기본값이 없는 겁니다. (비교값, 결과) 쌍만 있는 거죠."},"618":{"k":["단순 CASE에서 NULL은 어떤 WHEN과도 **일치하지 않음**","ELSE 생략 → **NULL**"],"w":["STATUS가 NULL이라 'DONE'과 일치하지 않음","STATUS가 NULL이라 'CANCEL'과 일치하지 않음","","ELSE 생략은 정상이고 NULL 반환"],"t":"CASE STATUS WHEN NULL로는 NULL을 못 잡습니다. CASE WHEN STATUS IS NULL을 써야 해요."},"619":{"k":["`COUNT(CASE WHEN 조건 THEN 1 END)` = 조건 맞는 행 수 (불일치 행은 NULL → COUNT에서 빠짐)","AMT ≥ 200: 200, 300, 200 → **3**"],"w":["300을 빠뜨린 값","","AMT 100까지 센 값","전체 행 수"],"t":"조건부 개수 세기의 정석 패턴입니다. ELSE 0을 넣으면 COUNT는 전부 세 버리니 주의!"},"620":{"k":["DONE 행 AMT: 100, NULL, 200, 50 → SUM은 NULL 제외 → **350**"],"w":["","DONE 합계를 잘못 계산한 값","STATUS와 무관한 전체 합계","SUM은 NULL을 제외하고 계산해 NULL이 아님"],"t":"CASE가 NULL을 돌려줘도 SUM이 알아서 빼 줍니다. 결과가 NULL이 되는 건 모든 값이 NULL일 때뿐."},"621":{"k":["CASE는 **처음 맞는 조건**에서 멈춤 → 'A'"],"w":["여러 개를 반환하지 않고 하나만 반환","첫 조건에서 이미 A로 결정","ELSE까지 가지 않음",""],"t":"조건이 겹치면 위쪽이 이깁니다. 그래서 범위 조건은 큰 값부터 쓰는 게 보통이에요."},"622":{"k":["`DECODE(컬럼, 값1, 결과1, 값2, 결과2, 기본값)` = `CASE 컬럼 WHEN 값1 THEN 결과1 WHEN 값2 THEN 결과2 ELSE 기본값 END`"],"w":["값과 결과가 뒤바뀜","비교 대상과 결과가 뒤바뀜","","WHEN 뒤 조건식이 없는 잘못된 문법"],"t":"DECODE는 단순형 CASE와 1:1로 바뀝니다. 마지막 홀수 번째 인자가 ELSE."},"623":{"k":["**DECODE는 NULL끼리 같다고** 봄 → '같음'","CASE WHEN NULL = NULL은 UNKNOWN → 불일치"],"w":["DECODE는 NULL끼리 같다고 봐서 '다름'이 아님","","일치해서 '같음'을 반환","정상 문법"],"t":"DECODE와 CASE의 유일한 동작 차이가 NULL 비교입니다. 시험에 잘 나와요."},"624":{"k":["1500 > 2000? 아니오 → 1500 > 1000? 예 → **'중'**"],"w":["","1500은 2000 초과가 아님","1000보다 커서 '중'","ELSE가 있어 NULL이 될 수 없음"],"t":"CASE는 조건을 위에서부터 하나씩 따라가면 됩니다."},"625":{"k":["`SUM(DECODE(JOB, 'CLERK', 1, 0))` = CLERK 인원 수","EMP CLERK: SMITH, ADAMS, JAMES, MILLER → **4**"],"w":["CLERK이 아닌 사람 수","전체 행 수","1이 아니라 합계",""],"t":"1/0을 더하는 방식은 COUNT(CASE …)와 같은 효과입니다. 피벗 문제에서 자주 봐요."},"626":{"k":["CASE는 위에서부터 검사, **처음 맞는 조건**의 결과 사용","ELSE 생략 → NULL, 여러 절에서 사용 가능"],"w":["ELSE 생략 시 NULL. 맞는 설명","SELECT·WHERE·ORDER BY 등에서 사용. 맞는 설명","","위에서부터 차례로 검사. 맞는 설명"],"t":"'마지막 결과'라는 보기는 CASE 동작과 정반대입니다."},"627":{"k":["**DECODE** = Oracle 전용 조건 함수 (CASE는 표준)"],"w":["NVL2는 NULL 여부에 따른 분기만 함","","COALESCE는 표준 함수","IIF는 SQL Server 함수"],"t":"Oracle 전용: DECODE, NVL, NVL2. 표준: CASE, COALESCE, NULLIF."},"1049":{"k":["DECODE는 **NULL끼리 같다고** 봄 → 'N'","단순 CASE(`CASE V WHEN NULL`)는 V = NULL 비교 → UNKNOWN → ELSE 'X'","NULL을 잡으려면 `CASE WHEN V IS NULL`"],"w":["CASE V WHEN NULL은 UNKNOWN이라 ELSE로 감","DECODE는 NULL끼리 같다고 봐 'N'","DECODE 결과가 'N'",""],"t":"DECODE와 CASE의 NULL 처리 차이는 시험에 반복 출제됩니다. 표로 기억하세요."},"1093":{"k":["CASE는 위에서부터 **처음 참인 WHEN**에서 멈춤","95는 첫 조건 `점수 >= 60`에서 바로 'C'","범위 조건은 **좁은(큰) 범위부터** 써야 함"],"w":["첫 조건(>= 60)에서 이미 멈춰 A까지 못 감","첫 조건에서 멈춰 B까지 못 감","60 이상이라 ELSE로 가지 않음",""],"t":"조건 순서를 일부러 잘못 쓴 CASE 문제입니다. 결과는 '쓴 순서대로' 나와요."},"1168":{"k":["ELSE 생략 → 어느 WHEN에도 안 걸리면 **NULL** (오류 아님)"],"w":["ELSE 생략은 정상 문법","ELSE가 없어 'L'이 나올 수 없음","2500은 3000 미만이라 M",""],"t":"CASE에서 ELSE는 선택입니다. 생략하면 ELSE NULL과 같아요."},"1209":{"k":["ORDER BY에 DECODE로 **사용자 정의 순서**: VVIP 1, VIP 2, GOLD 3, 나머지 4"],"w":["순서가 뒤바뀜","VIP는 2순위라 첫 행이 아님","GOLD는 3순위, 마지막은 4인 일반",""],"t":"ORDER BY에 DECODE·CASE를 넣으면 원하는 순서대로 정렬할 수 있습니다. 실무에서도 많이 써요."},"1267":{"k":["NULL IN ('A','B') → UNKNOWN → WHEN이 TRUE가 아님 → ELSE","C와 NULL → '취급안함' **2행**"],"w":["NULL 행도 ELSE로 감","","A·B는 '취급'","C와 NULL이 해당"],"t":"WHEN 조건이 UNKNOWN이면 ELSE로 갑니다. WHERE에선 버려지지만 CASE에선 ELSE로 가요."},"1342":{"k":["`CASE X WHEN NULL` → X = NULL 비교 → 항상 UNKNOWN → ELSE 0","IS NULL · DECODE · NVL2는 NULL이면 1"],"w":["IS NULL이 TRUE라 1","DECODE는 NULL끼리 같다고 봐 1","","X가 NULL이면 세 번째 값 1"],"t":"단순 CASE로는 NULL을 절대 못 잡습니다. 이 문장 하나로 이 유형은 다 풀려요."},"1436":{"k":["NULL = NULL → **UNKNOWN** → WHEN 통과 못 함 → ELSE 'N'"],"w":["","NULL = NULL은 TRUE가 아님","ELSE가 있어 NULL이 아님","정상 문법"],"t":"NULL은 자기 자신과도 같지 않습니다. 비교 결과는 늘 UNKNOWN."},"1446":{"k":["DECODE(NULL, NULL, …) → 같다고 봄 → 'Y'","CASE NULL WHEN NULL → UNKNOWN → ELSE 'N'"],"w":["CASE는 NULL = NULL이 UNKNOWN이라 'N'","DECODE는 NULL끼리 같다고 봐 'Y'","","두 결과가 뒤바뀜"],"t":"DECODE = 관대, CASE = 엄격. NULL에 대해서는 이렇게 기억하세요."},"1507":{"k":["첫 조건 `SCORE >= 80`에서 95·85 모두 'B'","70 → ELSE 'C'"],"w":["95도 첫 조건 >= 80에서 이미 B","","85는 A가 될 수 없음","순서가 뒤바뀜"],"t":"'A' 조건이 아래에 있어서 영원히 실행되지 않습니다. 죽은 조건을 찾는 문제예요."},"1592":{"k":["기준: SAL이 NULL이면 0, 아니면 SAL × 2","④는 NULL이면 0 + 1 = **1** → 다름"],"w":["SAL*2가 NULL이면 0이라 같음","NULL이면 0, 아니면 SAL*2라 같음","DECODE는 NULL끼리 같다고 봐 같음",""],"t":"'결과가 다른 것' 문제는 NULL 행 하나만 대입해 봐도 대부분 풀립니다."},"1617":{"k":["NVL2('X', 'Y', NULL) → 'X'가 NULL 아님 → **'Y'**","ELSE/기본값 없는 CASE·DECODE, 같은 값 NULLIF는 NULL"],"w":["ELSE가 없어 NULL","기본값이 없어 NULL","같은 값이라 NULL",""],"t":"결과 후보 중에 NULL이 있어도 그 후보가 선택되지 않으면 NULL이 아닙니다."},"181":{"k":["우선순위: **산술 → 비교 → NOT → AND → OR**"],"w":["NOT은 비교 연산 다음","AND는 NOT 다음","","OR가 가장 마지막"],"t":"계산(산술)을 먼저 하고, 비교하고, 그 결과를 논리로 묶는다고 생각하면 순서가 자연스럽습니다."},"182":{"k":["**AND가 OR보다 먼저**: `A OR B AND C` = `A OR (B AND C)`"],"w":["OR는 AND보다 나중","우선순위가 있어 왼쪽부터가 아님","AND가 OR보다 우선순위가 높음",""],"t":"AND를 곱하기, OR를 더하기로 생각하세요. 곱하기가 먼저입니다."},"183":{"k":["`DEPTNO = 20 OR (DEPTNO = 30 AND SAL > 2000)`","20번 5명 + 30번 BLAKE 1명 = **6**"],"w":["OR 앞의 20번 5명이 조건 없이 모두 포함돼 2명일 수 없음","20번만 센 값. 30번 BLAKE 추가 필요","","30번 전원을 더한 값. AND가 먼저 묶임"],"t":"EMP 부서 인원: 10번 3명, 20번 5명, 30번 6명. 외워 두면 계산이 빨라집니다."},"184":{"k":["괄호 먼저: (20번 또는 30번) **AND** SAL > 2000","JONES, SCOTT, FORD, BLAKE = **4**"],"w":["","괄호를 무시하고 AND를 먼저 묶은 값","일부 부서만 센 값","BLAKE(30번, 2850)를 빠뜨린 값"],"t":"183번과 괄호 하나 차이로 6 → 4가 됩니다. 괄호 위치부터 확인하세요."},"185":{"k":["NOT이 AND보다 먼저: `(NOT DEPTNO = 10) AND SAL > 2000`","BLAKE, JONES, SCOTT, FORD = **4**"],"w":["10번이 아니면서 2000 초과는 4명","SCOTT·FORD(3000)를 빠뜨린 값","4명 중 한 명을 빠뜨린 값",""],"t":"NOT은 바로 뒤 조건 하나에만 붙습니다. 전체를 부정하려면 괄호가 필요해요."},"443":{"k":["`JOB = 'CLERK' OR (JOB = 'MANAGER' AND SAL >= 2900)`","CLERK 4명 + JONES 1명 = **5**"],"w":["JONES만 센 값. CLERK은 SAL 조건 없이 모두 포함","CLERK만 센 값","","SAL 조건 없이 CLERK + MANAGER 전원"],"t":"AND가 붙은 쪽에만 조건이 걸립니다. OR 앞쪽은 독립 조건이에요."},"628":{"k":["`CUST = 'A' OR (CUST = 'B' AND AMT > 150)`","A 2건 + B 200 2건 = **4**"],"w":["","B 200 두 건 중 하나를 빠뜨린 값","B만 센 값. A 전체가 따로 붙음","C나 NULL 고객은 조건에 없어 5건이 아님"],"t":"A의 AMT NULL 행도 A 조건만으로 포함됩니다. AMT 조건은 B에만 걸려요."},"629":{"k":["괄호로 OR 먼저 → (A 또는 B) AND AMT > 150 → B의 200, 200 = **2**"],"w":["B 두 건 중 하나만 센 값","A의 100을 150 초과로 본 값","괄호를 무시하고 AND를 먼저 묶은 값",""],"t":"628번과 비교해 보세요. 괄호 하나로 결과가 4 → 2가 됩니다."},"630":{"k":["`SALESMAN OR (MANAGER AND 30번) OR SAL > 4000`","SALESMAN 4 + BLAKE 1 + KING 1 = **6**"],"w":["KING(SAL > 4000)을 빠뜨린 값","MANAGER 전원을 센 값. AND가 먼저 묶임","","BLAKE와 KING을 빠뜨린 값"],"t":"OR가 여러 개면 AND 묶음을 먼저 괄호로 표시하고, 나머지를 OR로 나열하세요."},"631":{"k":["NOT (10번 OR 20번) = 30번","30번이면서 SAL ≥ 1500: BLAKE, ALLEN, TURNER = **3**"],"w":["30번 중 1500 이상은 3명","","TURNER(1500)를 빠뜨린 값. 이상이라 포함","30번 전체 인원"],"t":"괄호 안 OR를 NOT으로 뒤집으면 드모르간: NOT A AND NOT B. 즉 10번도 20번도 아닌 것."},"632":{"k":["AND 먼저 → `A = 1 OR (B = 2 AND C = 3)`"],"w":["","OR를 먼저 묶은 해석","C = 3을 엉뚱한 쪽에 묶음","AND와 OR가 뒤바뀜"],"t":"괄호 없는 조건은 AND 덩어리에 먼저 괄호를 쳐 보세요."},"633":{"k":["우선순위 가장 낮음 = **OR**"],"w":["비교 연산자는 NOT보다 우선","NOT은 AND보다 우선","AND는 OR보다 우선",""],"t":"OR는 언제나 마지막입니다."},"634":{"k":["산술도 우선순위: `1000 + 500 * 2` = 1000 + 1000 = **2000**","SAL > 2000: KING, BLAKE, CLARK, JONES, SCOTT, FORD = **6**"],"w":["2000 초과자 중 한 명을 빠뜨린 값","덧셈을 먼저 해 3000 초과로 본 값","","1500 기준으로 본 값"],"t":"WHERE 안의 산술도 수학 순서대로 곱셈이 먼저입니다."},"1094":{"k":["NOT이 AND보다 먼저: `(부서 <> 10) AND 급여 > 1500`","부서 NULL(오세훈)은 비교가 UNKNOWN → 제외 → 정수진, 한예슬, 강다니 **3명**"],"w":["한 명을 빠뜨린 값","","부서가 NULL인 행까지 센 값","조건 일부를 무시한 값"],"t":"NOT (NULL = 10)도 UNKNOWN입니다. NOT은 UNKNOWN을 TRUE로 바꾸지 못해요."},"1300":{"k":["괄호로 OR 먼저 → (XX 또는 YY) AND 등급 1 AND 서울 → **2행**","괄호가 없으면 `XX OR (YY AND …)` → XX 전부 포함"],"w":["한 행을 빠뜨린 값","","괄호 없이 AND가 먼저 묶인 해석","조건을 무시한 전체 행"],"t":"OR 조건을 다른 AND 조건과 같이 쓸 땐 항상 괄호로 감싸야 합니다."},"1332":{"k":["괄호 → 산술 → 연결(`||`) → 비교 → IS NULL·LIKE·IN → BETWEEN → **NOT → AND → OR**"],"w":["","OR와 AND 순서가 바뀜","괄호가 가장 먼저","괄호·비교가 논리 연산보다 먼저"],"t":"시험에서는 '괄호 > 비교 > NOT > AND > OR' 다섯 단계만 알면 충분합니다."},"1490":{"k":["NOT > AND > OR → `A = 1 OR (B = 2 AND C = 3)`"],"w":["AND가 먼저 묶임","우선순위가 있어 왼쪽부터가 아님","","괄호 없이도 정상 문법"],"t":"괄호가 없어도 오류는 안 납니다. 대신 의도와 다르게 묶일 뿐이에요."},"1580":{"k":["③ `… AND TEAM = 'A' OR TEAM = 'B'` = `(… AND TEAM = 'A') OR TEAM = 'B'`","→ B팀은 포지션·키와 무관하게 전부 포함"],"w":["괄호로 OR를 묶어 정상","IN과 범위 비교로 정상","","괄호와 NOT으로 같은 범위를 표현해 정상"],"t":"옳지 않은 조건 찾기에선 괄호 없이 OR가 끝에 붙은 보기를 먼저 의심하세요."},"186":{"k":["BETWEEN A AND B = **양 끝 포함** (≥ A AND ≤ B)","1250 2명 + 1300 + 1500 + 1600 = **5**"],"w":["1250 두 명을 뺀 값. BETWEEN은 양 끝 포함","한쪽 끝(1600)을 뺀 값","","범위 밖 값까지 포함한 값"],"t":"BETWEEN은 작은 값을 앞에 써야 합니다. BETWEEN 1600 AND 1250은 결과가 0건이에요."},"187":{"k":["`BETWEEN A AND B` = `>= A AND <= B` → A가 B보다 크면 만족하는 값이 없어 **0건** (오류 아님)"],"w":["작은 값이 앞에 와야 정상 범위가 됨","","문법은 정상이고 결과가 0건일 뿐","조건에 맞는 행이 없음"],"t":"BETWEEN은 순서를 자동으로 바꿔 주지 않습니다. 그대로 풀어 쓰면 모순 조건이 보여요."},"188":{"k":["LIKE `_` = 정확히 한 글자, `%` = 0글자 이상","`'_A%'` = 두 번째 글자가 A → WARD, MARTIN, JAMES"],"w":["첫 글자가 A인 이름(ALLEN, ADAMS)을 센 값","A가 아무 위치에나 있는 이름 일부를 센 값","한 명만 센 값",""],"t":"언더바 개수 = 앞에 오는 글자 수입니다. _A면 A 앞에 한 글자."},"189":{"k":["`'%S'` = S로 **끝나는** 이름 → JONES, ADAMS, JAMES"],"w":["","S로 끝나는 이름은 3명","S로 시작하는 이름(SMITH, SCOTT)을 센 값","S가 포함된 이름을 센 값"],"t":"%의 위치가 곧 '아무거나'의 위치입니다. %S는 앞이 아무거나, S%는 뒤가 아무거나."},"190":{"k":["IN = 여러 값 중 하나 (OR 묶음)","20번 CLERK(SMITH, ADAMS) + ANALYST(SCOTT, FORD) = **4**"],"w":["한 직무만 센 값","20번 직원 중 한 명을 빠뜨린 값","","부서 조건 없이 CLERK + ANALYST를 모두 센 값"],"t":"IN 뒤의 AND는 IN 전체에 걸립니다. IN은 괄호로 이미 묶여 있으니까요."},"191":{"k":["NULL 판단은 **IS NULL**","COMM 값 있는 사람: ALLEN, WARD, MARTIN, TURNER(0) → 나머지 **10명**"],"w":["COMM이 있는 사람(IS NOT NULL) 수","","COMM이 NULL인 사람이 있음","전체 행 수"],"t":"TURNER의 COMM 0은 NULL이 아닙니다. 그래서 NULL은 14 − 4 = 10명."},"192":{"k":["`= NULL`은 항상 **UNKNOWN** → **0건**","NULL 비교는 IS NULL"],"w":["IS NULL로 썼을 때의 결과","COMM이 있는 사람 수","= NULL은 UNKNOWN이라 전체가 나오지 않음",""],"t":"= NULL은 오류가 아니라 0건입니다. '오류'라는 보기에 속지 마세요."},"193":{"k":["'같지 않다': **<> · != · ^=** (Oracle)","`><`는 없는 연산자"],"w":["<>는 표준 '같지 않다'","","!=도 '같지 않다'","^=는 Oracle의 '같지 않다'"],"t":"시험 단골인 ^=는 낯설지만 맞는 연산자입니다."},"194":{"k":["NOT BETWEEN 1000 AND 3000 = 1000 **미만** 또는 3000 **초과**","SMITH 800, JAMES 950, KING 5000 = **3** (3000은 BETWEEN에 포함되니 제외)"],"w":["","BETWEEN 안쪽 인원","KING(5000)을 빠뜨린 값","3000(SCOTT·FORD)을 범위 밖으로 잘못 본 값"],"t":"NOT BETWEEN은 경계값을 포함하지 않습니다. BETWEEN이 경계를 포함하니까 그 반대예요."},"195":{"k":["ESCAPE 문자 뒤의 `_`·`%`는 와일드카드가 아니라 **문자 그 자체**","→ 'A_'로 시작하는 값"],"w":["이스케이프 처리로 _가 문자 그대로가 됨","_가 와일드카드였을 때의 의미","","ESCAPE 문자는 실제 값에 포함되지 않음"],"t":"ESCAPE로 지정한 문자는 '바로 다음 한 글자를 일반 문자로 만든다'는 표시일 뿐입니다."},"196":{"k":["NOT IN = 목록 값 모두 아님","CLERK 4 + SALESMAN 4 제외 → 14 − 8 = **6**"],"w":["","한 직무만 제외한 값","한 직무만 제외한 값","제외 대상만 센 값의 절반"],"t":"EMP 직무 인원: CLERK 4, SALESMAN 4, MANAGER 3, ANALYST 2, PRESIDENT 1."},"197":{"k":["A와 N이 **둘 다** 포함된 이름 → ALLEN, MARTIN = **2**"],"w":["두 사람 중 한 명만 센 값","A가 있는 이름 일부까지 센 값","N 조건을 일부 무시한 값",""],"t":"LIKE 두 개를 AND로 묶으면 두 글자가 모두 있어야 합니다. 순서는 상관없어요."},"198":{"k":["AND 뒤에도 **컬럼을 다시** 써야 함: `SAL >= 1000 AND SAL <= 2000`"],"w":["","BETWEEN 사용은 정상","LIKE 사용은 정상","IS NOT NULL은 정상"],"t":"SQL은 수학처럼 1000 <= SAL <= 2000으로 줄여 쓸 수 없습니다."},"200":{"k":["1981년 입사자 = **10명**","1980 SMITH, 1982 MILLER, 1987 SCOTT·ADAMS 제외"],"w":["1981년 입사자 일부를 빠뜨린 값","","다른 해 입사자까지 포함한 값","한 명을 빠뜨린 값"],"t":"EMP 입사 연도: 1980년 1명, 1981년 10명, 1982년 1명, 1987년 2명."},"442":{"k":["`_`는 와일드카드 → 문자 _를 찾으려면 **ESCAPE** 필요","`LIKE '%/_라면' ESCAPE '/'`"],"w":["_가 와일드카드라 '아무 글자 + 라면'으로 끝나는 값이 전부 걸림","","'_라면'으로 시작하는 조건인 데다 _도 와일드카드","=는 와일드카드를 해석하지 않아 글자 그대로 비교"],"t":"ESCAPE 문자는 아무 문자나 지정할 수 있습니다. / 나 ! 를 자주 써요."},"635":{"k":["`<>` 비교에서 NULL은 **UNKNOWN** → 제외","CANCEL 1건만"],"w":["STATUS NULL 행까지 센 값","","DONE 아닌 행을 잘못 센 값","전체 행 수"],"t":"'DONE이 아닌 것'에 NULL은 들어가지 않습니다. 포함하려면 OR STATUS IS NULL."},"636":{"k":["BETWEEN 100 AND 200 → 100, 200, 200 = **3** (NULL 제외)"],"w":["","200 두 건 중 하나를 빠뜨린 값","범위 밖 값을 포함한 값","범위 밖 값을 포함한 값"],"t":"AMT가 NULL인 행은 어떤 범위 조건에도 걸리지 않습니다."},"637":{"k":["NOT IN에서 NULL 행은 **UNKNOWN** → 제외","C 1건만"],"w":["NULL 행까지 센 값","NULL 행을 포함한 값","범위 밖 값을 포함한 값",""],"t":"NOT IN 목록에 NULL이 들어 있으면 결과가 아예 0건이 됩니다. 이것도 자주 나와요."},"638":{"k":["`IN ('A', NULL)` = `= 'A' OR = NULL` → NULL 행은 = NULL로 안 걸림 → A **2건**"],"w":["A 행은 = 'A'로 통과","NULL 행은 = NULL로 걸리지 않음","","전체 행 수"],"t":"IN 목록 속 NULL은 아무 효과가 없습니다(IN일 때). NOT IN일 때는 전체를 0건으로 만들어요."},"639":{"k":["IS NULL OR IS NULL → 4번(STATUS NULL) + 2번(AMT NULL) = **2**"],"w":["둘 중 하나만 센 값","","행 수가 맞지 않음","NULL 행이 있음"],"t":"IS NULL은 NULL 비교에서 TRUE/FALSE를 확실히 돌려주는 유일한 방법입니다."},"640":{"k":["끝에서 두 번째 글자 = T 뒤에 **한 글자(_)** → `'S%T_'`"],"w":["","두 번째 글자가 T인 조건","T로 끝나는 조건이고 S 위치도 고정 안 됨","T가 어디든 있으면 되는 조건"],"t":"끝에서 n번째 = 뒤에 _를 n−1개 붙인다고 생각하세요."},"641":{"k":["`'%L%L%'` = L이 **두 번 이상** → ALLEN, MILLER = **2**"],"w":["L이 한 번만 있는 이름까지 센 값","한 명을 더 센 값","한 명을 빠뜨린 값",""],"t":"BLAKE, CLARK은 L이 하나뿐이라 제외됩니다."},"642":{"k":["언더바 4개 = **정확히 4글자** → KING, WARD, FORD = **3**"],"w":["한 명을 더 센 값","5글자 이름까지 센 값","","한 명을 빠뜨린 값"],"t":"%가 없으면 길이가 고정됩니다. 언더바 개수 = 글자 수."},"643":{"k":["% 문자 자체를 찾으려면 ESCAPE: `LIKE '%!%%' ESCAPE '!'` 같은 형태","ESCAPE 문자 뒤의 %는 문자 그대로"],"w":["%%%는 와일드카드 세 개라 모든 값이 걸림","","=는 값 전체가 '%'일 때만 참","_는 아무 글자 하나라 거의 모든 값이 걸림"],"t":"가운데 %만 문자이고 양쪽 %는 와일드카드입니다. '%가 어딘가에 들어 있는 값'이 돼요."},"644":{"k":["NOT BETWEEN도 NULL은 **제외**","COMM 값 있는 4명 중 범위 밖: MARTIN 1400, TURNER 0 = **2**"],"w":["","NULL 행까지 센 값","COMM 값이 있는 사람 수","COMM이 NULL인 사람 수"],"t":"NOT을 붙여도 NULL 행은 돌아오지 않습니다. UNKNOWN의 부정도 UNKNOWN이니까요."},"645":{"k":["MGR이 NULL인 사람은 KING뿐 → IS NOT NULL = **13**"],"w":["상사 역할을 하는 사람 수","전체 행 수","MGR이 NULL인 사람 수",""],"t":"KING = 최상위 관리자(MGR NULL). 계층형 질의 문제에서도 시작점으로 계속 나옵니다."},"646":{"k":["`BETWEEN 1000 AND 2000` ≡ `>= 1000 AND <= 2000`"],"w":["= NULL은 항상 0건이라 다름","IS NULL 조건이 추가돼 결과가 다를 수 있음","","=는 와일드카드를 해석하지 않아 다름"],"t":"BETWEEN을 부등호로 바꿀 때 등호(=)를 빼먹지 마세요."},"647":{"k":["IN 목록 중 없는 값(40번)은 그냥 매칭 0건","10번 3명 → **3**"],"w":["40번 사원은 없음","","10번 사원이 있음","전체 행 수"],"t":"DEPT에는 40번(OPERATIONS)이 있지만 EMP에는 40번 사원이 없습니다. 외부 조인 문제의 단골 소재예요."},"648":{"k":["NOT (AMT > 100) → AMT ≤ 100: 100, 50 = **2**","AMT NULL은 NOT을 해도 UNKNOWN → 제외"],"w":["","50을 빠뜨린 값","NULL 행까지 센 값","행 수가 맞지 않음"],"t":"NOT은 TRUE ↔ FALSE만 뒤집습니다. UNKNOWN은 그대로 남아요."},"649":{"k":["1987년 이후 입사: SCOTT, ADAMS = **2**"],"w":["1987년 이후는 2명","한 명을 더 센 값","한 명을 빠뜨린 값",""],"t":"EMP에서 SCOTT·ADAMS만 1987년 입사입니다. 최근 입사자 문제에 자주 나와요."},"650":{"k":["NULL 판단 = **IS NULL / IS NOT NULL**"],"w":["= NULL은 항상 UNKNOWN","==는 SQL 연산자가 아님","","IN NULL은 문법이 맞지 않음"],"t":"NULL에는 =가 통하지 않는다. NULL 문제의 출발점입니다."}};
